import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Language, ImageItem } from './types';
import { translations } from './i18n';
import { colorizeImage, fileToBase64 } from './services/geminiService';
import { ImageCard } from './components/ImageCard';
import { AdPlaceholder } from './components/AdPlaceholder';

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('he');
  const [images, setImages] = useState<ImageItem[]>([]);
  const [targetLabel, setTargetLabel] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [isDragging, setIsDragging] = useState(false);
  const [selectedImage, setSelectedImage] = useState<ImageItem | null>(null);
  const [zoomLevel, setZoomLevel] = useState(1);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const t = translations[lang];
  const isRtl = lang === 'he';

  useEffect(() => {
    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const adjustZoom = useCallback((delta: number) => {
    setZoomLevel(prev => Math.min(Math.max(prev + delta, 0.5), 3));
  }, []);

  const closeOverlay = useCallback(() => {
    setSelectedImage(null);
    setZoomLevel(1);
  }, []);

  // Keyboard Shortcuts for Modal
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!selectedImage) return;

      if (e.key === '+' || e.key === '=') {
        adjustZoom(0.25);
      } else if (e.key === '-' || e.key === '_') {
        adjustZoom(-0.25);
      } else if (e.key === 'Escape') {
        closeOverlay();
      }
    };

    if (selectedImage) {
      window.addEventListener('keydown', handleKeyDown);
    }

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [selectedImage, adjustZoom, closeOverlay]);

  const handleFiles = (files: FileList | null) => {
    if (!files) return;
    const newImages: ImageItem[] = Array.from(files).map(file => ({
      id: Math.random().toString(36).substr(2, 9),
      file,
      previewUrl: URL.createObjectURL(file),
      status: 'pending'
    }));
    setImages(prev => [...prev, ...newImages]);
  };

  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const onDragEnter = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const onDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    const rect = e.currentTarget.getBoundingClientRect();
    if (
      e.clientX <= rect.left ||
      e.clientX >= rect.right ||
      e.clientY <= rect.top ||
      e.clientY >= rect.bottom
    ) {
      setIsDragging(false);
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    handleFiles(e.dataTransfer.files);
  };

  const onRemoveImage = (id: string) => {
    setImages(prev => prev.filter(img => img.id !== id));
  };

  const clearAll = () => {
    setImages([]);
    setTargetLabel('');
  };

  const processAll = async () => {
    if (isProcessing) return;
    setIsProcessing(true);

    const pendingImages = images.filter(img => img.status === 'pending');

    for (const item of pendingImages) {
      setImages(prev => prev.map(img => 
        img.id === item.id ? { ...img, status: 'processing' } : img
      ));

      try {
        const base64 = await fileToBase64(item.file);
        const resultUrl = await colorizeImage(base64, item.file.type);

        setImages(prev => prev.map(img => 
          img.id === item.id ? { ...img, status: 'completed', resultUrl } : img
        ));
      } catch (err) {
        setImages(prev => prev.map(img => 
          img.id === item.id ? { ...img, status: 'error', error: String(err) } : img
        ));
      }
    }

    setIsProcessing(false);
  };

  const downloadAll = () => {
    const completedImages = images.filter(img => img.status === 'completed' && img.resultUrl);
    if (completedImages.length === 0) return;

    if (window.confirm(t.confirmDownload)) {
      const prefix = targetLabel.trim() || 'colorized';
      completedImages.forEach(img => {
        exportSingle(img, prefix);
      });
    }
  };

  const exportSingle = (img: ImageItem, prefix?: string) => {
    if (!img.resultUrl) return;
    const finalPrefix = prefix || targetLabel.trim() || 'colorized';
    const link = document.createElement('a');
    link.href = img.resultUrl;
    link.download = `${finalPrefix}_${img.file.name}`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const shareSingle = async (img: ImageItem) => {
    if (!img.resultUrl) return;
    try {
      if (navigator.share) {
        await navigator.share({
          title: t.title,
          text: t.shareTitle,
          url: window.location.href,
        });
      } else {
        await navigator.clipboard.writeText(window.location.href);
        alert(isRtl ? 'הקישור הועתק!' : 'Link copied to clipboard!');
      }
    } catch (err) {
      console.error('Sharing failed', err);
    }
  };

  return (
    <div className={`min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 font-sans ${isRtl ? 'rtl' : 'ltr'}`} dir={isRtl ? 'rtl' : 'ltr'}>
      {/* Header */}
      <header className="sticky top-0 z-40 bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border-b border-slate-200 dark:border-slate-800">
        <div className="max-w-6xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-gradient-to-tr from-indigo-600 to-pink-500 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-500/20">
              <svg className="w-5 h-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
              </svg>
            </div>
            <h1 className="text-xl font-black tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-pink-500">
              {t.title}
            </h1>
          </div>

          <div className="flex items-center gap-4">
            {isOffline && (
              <span className="text-xs font-bold bg-amber-500/10 text-amber-600 dark:text-amber-400 px-2 py-1 rounded-full flex items-center gap-1">
                <span className="w-2 h-2 bg-amber-500 rounded-full animate-pulse"></span>
                {t.offlineReady}
              </span>
            )}
            <button 
              onClick={() => setLang(lang === 'en' ? 'he' : 'en')}
              className="px-3 py-1 text-sm font-semibold rounded-full border border-slate-200 dark:border-slate-700 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
            >
              {t.languageName}
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-6 py-12">
        <div className="text-center mb-12">
          <h2 className="text-4xl md:text-5xl font-extrabold mb-4 tracking-tight">
            {t.subtitle}
          </h2>
          <p className="text-slate-500 dark:text-slate-400 max-w-2xl mx-auto text-lg">
            {lang === 'en' 
              ? 'Effortlessly transform monochromatic images into full-color photos using deep learning AI models.' 
              : 'הפוך תמונות שחור-לבן לצבעוניות ללא מאמץ באמצעות מודלים של למידה עמוקה.'}
          </p>
        </div>

        <AdPlaceholder label={t.adPlaceholder} />

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Controls Panel */}
          <div className="lg:col-span-1 space-y-6">
            <div className="bg-white dark:bg-slate-900 p-6 rounded-3xl shadow-xl shadow-slate-200/50 dark:shadow-none border border-slate-200 dark:border-slate-800">
              <label className="block text-sm font-bold text-slate-700 dark:text-slate-300 mb-2">
                {t.targetFolder}
              </label>
              <div className="relative group">
                 <input 
                  type="text" 
                  value={targetLabel}
                  onChange={(e) => setTargetLabel(e.target.value)}
                  placeholder={t.targetFolderPlaceholder}
                  className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                />
                <div className="absolute inset-y-0 right-3 flex items-center pointer-events-none opacity-20 group-focus-within:opacity-50 transition-opacity">
                  <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z" />
                  </svg>
                </div>
              </div>

              <div className="mt-8 space-y-3">
                <button 
                  onClick={processAll}
                  disabled={isProcessing || images.filter(i => i.status === 'pending').length === 0}
                  className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-300 dark:disabled:bg-slate-800 text-white font-bold rounded-2xl shadow-lg shadow-indigo-600/20 transition-all flex items-center justify-center gap-2 transform active:scale-95"
                >
                  {isProcessing ? (
                    <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                  ) : (
                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
                    </svg>
                  )}
                  {t.colorizeBtn}
                </button>

                <button 
                  onClick={downloadAll}
                  disabled={images.filter(i => i.status === 'completed').length === 0}
                  className="w-full py-4 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-700 dark:text-slate-200 font-bold rounded-2xl hover:bg-slate-50 dark:hover:bg-slate-750 transition-all flex items-center justify-center gap-2"
                >
                  <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                  </svg>
                  {t.downloadAll}
                </button>

                <button 
                  onClick={clearAll}
                  className="w-full py-3 text-slate-500 dark:text-slate-400 text-sm font-semibold hover:text-red-500 transition-colors"
                >
                  {t.clearBtn}
                </button>
              </div>
            </div>
          </div>

          <div className="lg:col-span-2 space-y-6">
            <div 
              onDragOver={onDragOver}
              onDragEnter={onDragEnter}
              onDragLeave={onDragLeave}
              onDrop={handleDrop}
              onClick={() => fileInputRef.current?.click()}
              className={`relative group bg-white dark:bg-slate-900 border-2 border-dashed rounded-3xl p-12 text-center cursor-pointer transition-all shadow-lg shadow-slate-200/50 dark:shadow-none overflow-hidden ${isDragging ? 'border-indigo-500 scale-[1.01] bg-indigo-50/50' : 'border-slate-300 dark:border-slate-800 hover:border-indigo-500'}`}
            >
              {isDragging && (
                <div className="absolute inset-0 z-10 bg-indigo-600/90 flex flex-col items-center justify-center text-white p-6 pointer-events-none animate-in fade-in zoom-in-95 duration-200">
                  <div className="w-24 h-24 bg-white/20 rounded-full flex items-center justify-center mb-4">
                    <svg className="w-12 h-12" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" />
                    </svg>
                  </div>
                  <h3 className="text-3xl font-black">{t.dropNow}</h3>
                </div>
              )}

              <input 
                type="file" 
                multiple 
                accept="image/*"
                className="hidden" 
                ref={fileInputRef}
                onChange={(e) => handleFiles(e.target.files)}
              />
              <div className="w-20 h-20 bg-indigo-50 dark:bg-slate-800 rounded-full flex items-center justify-center mx-auto mb-6 group-hover:scale-110 group-hover:bg-indigo-100 transition-all">
                <svg className="w-10 h-10 text-indigo-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" />
                </svg>
              </div>
              <h3 className="text-xl font-bold mb-2">{t.dropzoneTitle}</h3>
              <p className="text-slate-500 dark:text-slate-400">{t.dropzoneSub}</p>
            </div>

            {images.length > 0 && (
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
                {images.map(img => (
                  <ImageCard 
                    key={img.id} 
                    item={img} 
                    t={t} 
                    onRemove={onRemoveImage}
                    onSelect={setSelectedImage} 
                    onShare={shareSingle}
                  />
                ))}
              </div>
            )}
          </div>
        </div>
      </main>

      {/* Comparison Modal */}
      {selectedImage && (
        <div 
          className="fixed inset-0 z-[60] flex flex-col bg-slate-950 animate-in fade-in duration-300 overflow-hidden"
          onClick={closeOverlay}
        >
          {/* Modal Header */}
          <div className="h-16 px-6 flex items-center justify-between border-b border-white/10 bg-slate-900/50 backdrop-blur z-[70]" onClick={e => e.stopPropagation()}>
            <div className="flex items-center gap-4">
               <button 
                  onClick={closeOverlay}
                  className="p-2 hover:bg-white/10 rounded-full transition-colors"
                >
                  <svg className="w-6 h-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
                  </svg>
                </button>
                <span className="text-white font-bold hidden sm:inline">{selectedImage.file.name}</span>
            </div>

            <div className="flex items-center gap-2">
              <button 
                onClick={() => adjustZoom(-0.25)}
                className="p-2 bg-white/10 hover:bg-white/20 text-white rounded-lg transition-colors"
                title={`${t.zoomOut} (-)`}
              >
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20 12H4" />
                </svg>
              </button>
              <div className="bg-white/10 text-white px-3 py-1.5 rounded-lg text-sm font-mono">
                {Math.round(zoomLevel * 100)}%
              </div>
              <button 
                onClick={() => adjustZoom(0.25)}
                className="p-2 bg-white/10 hover:bg-white/20 text-white rounded-lg transition-colors"
                title={`${t.zoomIn} (+)`}
              >
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                </svg>
              </button>
              <div className="w-px h-6 bg-white/20 mx-2 hidden sm:block"></div>
              <button 
                onClick={() => exportSingle(selectedImage)}
                disabled={!selectedImage.resultUrl}
                className="hidden sm:flex items-center gap-2 px-4 py-2 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-700 text-white rounded-lg font-bold transition-all"
              >
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                </svg>
                {t.export}
              </button>
               <button 
                onClick={() => shareSingle(selectedImage)}
                disabled={!selectedImage.resultUrl}
                className="p-2 bg-white/10 hover:bg-white/20 text-white rounded-lg transition-colors"
              >
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z" />
                </svg>
              </button>
            </div>
          </div>

          {/* Side by Side Area */}
          <div className="flex-1 overflow-auto bg-grid-white/[0.05] p-4 sm:p-8" onClick={e => e.stopPropagation()}>
            <div 
              className="flex flex-col lg:flex-row gap-8 items-center lg:items-stretch justify-center transition-transform duration-300 origin-top"
              style={{ transform: `scale(${zoomLevel})` }}
            >
              {/* Original */}
              <div className="relative group w-full max-w-2xl bg-black rounded-xl overflow-hidden shadow-2xl border border-white/10">
                <img 
                  src={selectedImage.previewUrl} 
                  alt="Original B&W" 
                  className="w-full h-full object-contain"
                />
                <div className="absolute top-4 left-4 bg-black/60 backdrop-blur-md px-3 py-1 rounded-full border border-white/20">
                  <span className="text-white text-xs font-bold uppercase tracking-widest">{t.original}</span>
                </div>
              </div>

              {/* Result */}
              <div className="relative group w-full max-w-2xl bg-black rounded-xl overflow-hidden shadow-2xl border border-white/10">
                {selectedImage.resultUrl ? (
                  <img 
                    src={selectedImage.resultUrl} 
                    alt="Colorized Result" 
                    className="w-full h-full object-contain animate-in fade-in duration-500"
                  />
                ) : (
                   <div className="aspect-[4/3] w-full flex flex-col items-center justify-center bg-slate-900">
                    <div className="w-12 h-12 border-4 border-white/10 border-t-indigo-500 rounded-full animate-spin"></div>
                    <p className="mt-4 text-white/50 text-sm font-medium">{t.processing}</p>
                  </div>
                )}
                <div className="absolute top-4 left-4 bg-indigo-600/80 backdrop-blur-md px-3 py-1 rounded-full border border-white/20">
                  <span className="text-white text-xs font-bold uppercase tracking-widest">{t.result}</span>
