export default App;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Language, ImageItem } from './types';
import { translations } from './i18n';
import { colorizeImage, fileToBase64 } from './services/geminiService';
import { ImageCard } from './components/ImageCard';
import { AdPlaceholder } from './components/AdPlaceholder';

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('he');
  const [images, setImages] = useState<ImageItem[]>([]);
  const [targetLabel, setTargetLabel] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [isDragging, setIsDragging] = useState(false);
  const [selectedImage, setSelectedImage] = useState<ImageItem | null>(null);
  const [zoomLevel, setZoomLevel] = useState(1);
  const [panOffset, setPanOffset] = useState({ x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const t = translations[lang];
  const isRtl = lang === 'he';

  // Derive progress
  const totalInBatch = images.length;
  const processedCount = images.filter(img => img.status === 'completed' || img.status === 'error').length;
  const progressPercent = totalInBatch > 0 ? Math.round((processedCount / totalInBatch) * 100) : 0;
  const currentlyProcessing = images.some(img => img.status === 'processing' || img.status === 'pending');

  useEffect(() => {
    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Instant processing logic
  const processNextPending = useCallback(async () => {
    const nextItem = images.find(img => img.status === 'pending');
    if (!nextItem || isProcessing) return;

    setIsProcessing(true);
    setImages(prev => prev.map(img => 
      img.id === nextItem.id ? { ...img, status: 'processing' } : img
    ));

    try {
      const base64 = await fileToBase64(nextItem.file);
      const resultUrl = await colorizeImage(base64, nextItem.file.type);
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'completed', resultUrl } : img
      ));
    } catch (err) {
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'error', error: String(err) } : img
      ));
    } finally {
      setIsProcessing(false);
    }
  }, [images, isProcessing]);

  useEffect(() => {
    processNextPending();
  }, [images, processNextPending]);

  const handleFiles = (files: FileList | null) => {
    if (!files) return;
    const newImages: ImageItem[] = Array.from(files).map(file => ({
      id: Math.random().toString(36).substr(2, 9),
      file,
      previewUrl: URL.createObjectURL(file),
      status: 'pending'
    }));
    setImages(prev => [...prev, ...newImages]);
  };

  const adjustZoom = useCallback((delta: number) => {
    setZoomLevel(prev => {
      const next = Math.min(Math.max(prev + delta, 1), 5);
      if (next === 1) setPanOffset({ x: 0, y: 0 });
      return next;
    });
  }, []);

  const resetView = () => {
    setZoomLevel(1);
    setPanOffset({ x: 0, y: 0 });
  };

  const onMouseDown = (e: React.MouseEvent) => {
    if (zoomLevel > 1) {
      setIsPanning(true);
    }
  };

  const onMouseMove = (e: React.MouseEvent) => {
    if (isPanning && zoomLevel > 1) {
      setPanOffset(prev => ({
        x: prev.x + e.movementX,
        y: prev.y + e.movementY
      }));
    }
  };

  const onMouseUp = () => setIsPanning(false);

  const closeOverlay = useCallback(() => {
    setSelectedImage(null);
    resetView();
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!selectedImage) return;
      if (e.key === '+' || e.key === '=') adjustZoom(0.5);
      else if (e.key === '-' || e.key === '_') adjustZoom(-0.5);
      else if (e.key === '0') resetView();
      else if (e.key === 'Escape') closeOverlay();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [selectedImage, adjustZoom, closeOverlay]);

  const exportSingle = (img: ImageItem, prefix?: string) => {
    if (!img.resultUrl) return;
    const finalPrefix = prefix || targetLabel.trim() || 'colorized';
    const link = document.createElement('a');
    link.href = img.resultUrl;
    link.download = `${finalPrefix}_${img.file.name}`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const shareSingle = async (img: ImageItem) => {
    if (!img.resultUrl) return;
    try {
      if (navigator.share) {
        await navigator.share({ title: t.title, text: t.shareTitle, url: window.location.href });
      } else {
        await navigator.clipboard.writeText(window.location.href);
        alert(isRtl ? 'הקישור הועתק!' : 'Link copied to clipboard!');
      }
    } catch (err) { console.error('Sharing failed', err); }
  };

  return (
    <div className={`min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 font-sans ${isRtl ? 'rtl' : 'ltr'}`} dir={isRtl ? 'rtl' : 'ltr'}>
      <header className="sticky top-0 z-40 bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border-b border-slate-200 dark:border-slate-800">
        <div className="max-w-6xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-gradient-to-tr from-indigo-600 to-pink-500 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-500/20">
              <svg className="w-5 h-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
              </svg>
            </div>
            <h1 className="text-xl font-black tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-pink-500">{t.title}</h1>
          </div>
          <div className="flex items-center gap-4">
            {isOffline && (
              <span className="text-xs font-bold bg-amber-500/10 text-amber-600 dark:text-amber-400 px-2 py-1 rounded-full flex items-center gap-1">
                <span className="w-2 h-2 bg-amber-500 rounded-full animate-pulse"></span>
                {t.offlineReady}
              </span>
            )}
            <button onClick={() => setLang(lang === 'en' ? 'he' : 'en')} className="px-3 py-1 text-sm font-semibold rounded-full border border-slate-200 dark:border-slate-700 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors">
              {t.languageName}
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-6 py-12">
        <div className="text-center mb-12">
          <h2 className="text-4xl md:text-5xl font-extrabold mb-4 tracking-tight">{t.subtitle}</h2>
          <p className="text-slate-500 dark:text-slate-400 max-w-2xl mx-auto text-lg">
            {lang === 'en' ? 'Effortlessly transform monochromatic images into full-color photos instantly.' : 'הפוך תמונות שחור-לבן לצבעוניות באופן מיידי.'}
          </p>
        </div>

        <AdPlaceholder label={t.adPlaceholder} />

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-1 space-y-6">
            <div className="bg-white dark:bg-slate-900 p-6 rounded-3xl shadow-xl border border-slate-200 dark:border-slate-800">
              <label className="block text-sm font-bold text-slate-700 dark:text-slate-300 mb-2">{t.targetFolder}</label>
              <input 
                type="text" 
                value={targetLabel} 
                onChange={(e) => setTargetLabel(e.target.value)} 
                placeholder={t.targetFolderPlaceholder}
                className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
              />
              <div className="mt-8 space-y-3">
                <button 
                  onClick={() => {
                    const completedImages = images.filter(img => img.status === 'completed' && img.resultUrl);
                    if (completedImages.length > 0 && window.confirm(t.confirmDownload)) {
                      completedImages.forEach(img => exportSingle(img));
                    }
                  }}
                  disabled={images.filter(i => i.status === 'completed').length === 0}
                  className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-300 dark:disabled:bg-slate-800 text-white font-bold rounded-2xl shadow-lg transition-all flex items-center justify-center gap-2"
                >
                  <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                  {t.downloadAll}
                </button>
                <button onClick={() => setImages([])} className="w-full py-3 text-slate-500 dark:text-slate-400 text-sm font-semibold hover:text-red-500 transition-colors">{t.clearBtn}</button>
              </div>
            </div>
          </div>

          <div className="lg:col-span-2 space-y-6">
            <div 
              onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
              onDragEnter={(e) => { e.preventDefault(); setIsDragging(true); }}
              onDragLeave={(e) => { e.preventDefault(); setIsDragging(false); }}
              onDrop={(e) => { e.preventDefault(); setIsDragging(false); handleFiles(e.dataTransfer.files); }}
              onClick={() => fileInputRef.current?.click()}
              className={`relative group bg-white dark:bg-slate-900 border-2 border-dashed rounded-3xl p-12 text-center cursor-pointer transition-all ${isDragging ? 'border-indigo-500 scale-[1.01] bg-indigo-50/50' : 'border-slate-300 dark:border-slate-800 hover:border-indigo-500'}`}
            >
              {isDragging && <div className="absolute inset-0 z-10 bg-indigo-600/90 flex flex-col items-center justify-center text-white p-6 animate-in fade-in zoom-in-95 duration-200"><h3 className="text-3xl font-black">{t.dropNow}</h3></div>}
              <input type="file" multiple accept="image/*" className="hidden" ref={fileInputRef} onChange={(e) => handleFiles(e.target.files)} />
              <div className="w-16 h-16 bg-indigo-50 dark:bg-slate-800 rounded-full flex items-center justify-center mx-auto mb-4"><svg className="w-8 h-8 text-indigo-600" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg></div>
              <h3 className="text-xl font-bold mb-1">{t.dropzoneTitle}</h3>
              <p className="text-slate-500 text-sm">{t.dropzoneSub}</p>
            </div>

            {/* Global Progress Bar */}
            {images.length > 0 && currentlyProcessing && (
              <div className="bg-white dark:bg-slate-900 p-4 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm animate-in slide-in-from-top duration-300">
                <div className="flex items-center justify-between mb-2">
                  <span className="text-sm font-bold text-indigo-600 dark:text-indigo-400">{t.processing}</span>
                  <span className="text-sm font-black">{progressPercent}%</span>
                </div>
                <div className="w-full h-3 bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
                  <div 
                    className="h-full bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500 transition-all duration-500 ease-out relative"
                    style={{ width: `${progressPercent}%` }}
                  >
                    <div className="absolute inset-0 bg-white/20 animate-[shimmer_2s_infinite] skew-x-12 translate-x-[-100%]"></div>
                  </div>
                </div>
                <p className="mt-2 text-[10px] text-slate-400 text-center uppercase tracking-widest font-bold">
                  {processedCount} / {totalInBatch} {lang === 'en' ? 'Images Ready' : 'תמונות מוכנות'}
                </p>
              </div>
            )}

            {images.length > 0 && (
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
                {images.map(img => (
                  <ImageCard key={img.id} item={img} t={t} onRemove={(id) => setImages(prev => prev.filter(i => i.id !== id))} onSelect={setSelectedImage} onShare={shareSingle} />
                ))}
              </div>
            )}
          </div>
        </div>
      </main>

      {/* Synchronized Comparison Modal */}
      {selectedImage && (
        <div className="fixed inset-0 z-[60] flex flex-col bg-slate-950 animate-in fade-in duration-300 overflow-hidden select-none" onClick={closeOverlay}>
          <div className="h-16 px-6 flex items-center justify-between border-b border-white/10 bg-slate-900/50 backdrop-blur z-[70]" onClick={e => e.stopPropagation()}>
            <div className="flex items-center gap-4">
               <button onClick={closeOverlay} className="p-2 hover:bg-white/10 rounded-full transition-colors"><svg className="w-6 h-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg></button>
               <span className="text-white font-bold hidden sm:inline">{selectedImage.file.name}</span>
            </div>
            <div className="flex items-center gap-2">
              <button onClick={() => adjustZoom(-0.5)} className="p-2 bg-white/10 hover:bg-white/20 text-white rounded-lg transition-colors"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20 12H4" /></svg></button>
              <div className="bg-white/10 text-white px-3 py-1.5 rounded-lg text-sm font-mono">{Math.round(zoomLevel * 100)}%</div>
              <button onClick={() => adjustZoom(0.5)} className="p-2 bg-white/10 hover:bg-white/20 text-white rounded-lg transition-colors"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg></button>
              <button onClick={resetView} className="ml-2 px-3 py-1.5 bg-white/5 hover:bg-white/15 text-[10px] text-white/70 font-bold rounded-lg border border-white/10 uppercase tracking-tighter transition-all">Reset (0)</button>
              <div className="w-px h-6 bg-white/20 mx-2 hidden sm:block"></div>
              <button onClick={() => exportSingle(selectedImage)} disabled={!selectedImage.resultUrl} className="hidden sm:flex items-center gap-2 px-4 py-2 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-700 text-white rounded-lg font-bold transition-all"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>{t.export}</button>
            </div>
          </div>

          <div 
            className={`flex-1 overflow-hidden bg-slate-900 cursor-move ${isPanning ? 'cursor-grabbing' : ''}`} 
            onMouseDown={onMouseDown} onMouseMove={onMouseMove} onMouseUp={onMouseUp} onMouseLeave={onMouseUp}
            onClick={e => e.stopPropagation()}
          >
            <div 
              className="flex flex-col lg:flex-row gap-4 h-full items-center justify-center p-8 transition-transform duration-75 ease-out will-change-transform"
              style={{ transform: `translate(${panOffset.x}px, ${panOffset.y}px) scale(${zoomLevel})` }}
            >
              <div className="relative w-full max-w-[45vw] lg:h-[70vh] aspect-auto bg-black rounded-xl overflow-hidden shadow-2xl border border-white/10">
                <img src={selectedImage.previewUrl} alt="Original" className="w-full h-full object-contain pointer-events-none" />
                <div className="absolute top-4 left-4 bg-black/60 backdrop-blur-md px-3 py-1 rounded-full border border-white/20"><span className="text-white text-[10px] font-bold uppercase tracking-widest">{t.original}</span></div>
              </div>
              <div className="relative w-full max-w-[45vw] lg:h-[70vh] aspect-auto bg-black rounded-xl overflow-hidden shadow-2xl border border-white/10">
                {selectedImage.resultUrl ? <img src={selectedImage.resultUrl} alt="Result" className="w-full h-full object-contain animate-in fade-in duration-500 pointer-events-none" /> : <div className="h-full w-full flex flex-col items-center justify-center bg-slate-900"><div className="w-10 h-10 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div></div>}
                <div className="absolute top-4 left-4 bg-indigo-600/80 backdrop-blur-md px-3 py-1 rounded-full border border-white/20"><span className="text-white text-[10px] font-bold uppercase tracking-widest">{t.result}</span></div>
              </div>
            </div>
          </div>
        </div>
      )}

      <footer className="py-12 border-t border-slate-200 dark:border-slate-800 text-center text-slate-400 text-sm">
        <p>© {new Date().getFullYear()} ChromaRestore AI. All Rights Reserved.</p>
        <p className="mt-2 opacity-50">{lang === 'en' ? 'Powered by Google Gemini Flash-Image' : 'מופעל ע"י Google Gemini Flash-Image'}</p>
      </footer>

      <style>{`
        @keyframes shimmer {
          0% { transform: translateX(-100%) skewX(-12deg); }
          100% { transform: translateX(200%) skewX(-12deg); }
        }
      `}</style>
    </div>
  );
};

