  const [isDragging, setIsDragging] = useState(false);
  const [selectedImage, setSelectedImage] = useState<ImageItem | null>(null);
  const [zoomLevel, setZoomLevel] = useState(1);
  const [panOffset, setPanOffset] = useState({ x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  const [isFullScreen, setIsFullScreen] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const modalRef = useRef<HTMLDivElement>(null);

  const t = translations[lang];
  const isRtl = lang === 'he';

  // Derive progress
  const totalInBatch = images.length;
  const processedCount = images.filter(img => img.status === 'completed' || img.status === 'error').length;
  const progressPercent = totalInBatch > 0 ? Math.round((processedCount / totalInBatch) * 100) : 0;
  const currentlyProcessing = images.some(img => img.status === 'processing' || img.status === 'pending');

  useEffect(() => {
    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Instant processing logic
  const processNextPending = useCallback(async () => {
    const nextItem = images.find(img => img.status === 'pending');
    if (!nextItem || isProcessing) return;

    setIsProcessing(true);
    setImages(prev => prev.map(img => 
      img.id === nextItem.id ? { ...img, status: 'processing' } : img
    ));

    try {
      const base64 = await fileToBase64(nextItem.file);
      const resultUrl = await colorizeImage(base64, nextItem.file.type);
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'completed', resultUrl } : img
      ));
    } catch (err) {
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'error', error: String(err) } : img
      ));
    } finally {
      setIsProcessing(false);
    }
  }, [images, isProcessing]);

  useEffect(() => {
    processNextPending();
  }, [images, processNextPending]);

  const handleFiles = (files: FileList | null) => {
    if (!files) return;
    const newImages: ImageItem[] = Array.from(files).map(file => ({
      id: Math.random().toString(36).substr(2, 9),
      file,
      previewUrl: URL.createObjectURL(file),
      status: 'pending'
    }));
    setImages(prev => [...prev, ...newImages]);
  };

  const adjustZoom = useCallback((delta: number) => {
    setZoomLevel(prev => {
      const next = Math.min(Math.max(prev + delta, 1), 8);
      if (next === 1) setPanOffset({ x: 0, y: 0 });
      return next;
    });
  }, []);

  const resetView = () => {
    setZoomLevel(1);
    setPanOffset({ x: 0, y: 0 });
  };

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      modalRef.current?.requestFullscreen().catch(err => {
        console.error(`Error attempting to enable full-screen mode: ${err.message}`);
      });
      setIsFullScreen(true);
    } else {
      document.exitFullscreen();
      setIsFullScreen(false);
    }
  };

  useEffect(() => {
    const onFsChange = () => setIsFullScreen(!!document.fullscreenElement);
    document.addEventListener('fullscreenchange', onFsChange);
    return () => document.removeEventListener('fullscreenchange', onFsChange);
  }, []);

  const onMouseDown = (e: React.MouseEvent) => {
    if (zoomLevel > 1) {
      setIsPanning(true);
    }
  };

  const onMouseMove = (e: React.MouseEvent) => {
    if (isPanning && zoomLevel > 1) {
      setPanOffset(prev => ({
        x: prev.x + e.movementX,
        y: prev.y + e.movementY
      }));
    }
  };

  const onMouseUp = () => setIsPanning(false);

  const onImageDoubleClick = () => {
    if (zoomLevel > 1) resetView();
    else adjustZoom(2);
  };

  const closeOverlay = useCallback(() => {
    setSelectedImage(null);
    resetView();
    if (document.fullscreenElement) document.exitFullscreen();
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!selectedImage) return;
      if (e.key === '+' || e.key === '=') adjustZoom(0.5);
      else if (e.key === '-' || e.key === '_') adjustZoom(-0.5);
      else if (e.key === '0') resetView();
      else if (e.key === 'f' || e.key === 'F') toggleFullScreen();
      else if (e.key === 'Escape') closeOverlay();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [selectedImage, adjustZoom, closeOverlay]);

  const exportSingle = (img: ImageItem, prefix?: string) => {
    if (!img.resultUrl) return;
    const finalPrefix = prefix || targetLabel.trim() || 'colorized';
    const link = document.createElement('a');
    link.href = img.resultUrl;
    link.download = `${finalPrefix}_${img.file.name}`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const shareSingle = async (img: ImageItem) => {
    if (!img.resultUrl) return;
    try {
      if (navigator.share) {
        await navigator.share({ title: t.title, text: t.shareTitle, url: window.location.href });
      } else {
        await navigator.clipboard.writeText(window.location.href);
        alert(isRtl ? 'הקישור הועתק!' : 'Link copied to clipboard!');
      }
    } catch (err) { console.error('Sharing failed', err); }
  };

  return (
    <div className={`min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 font-sans ${isRtl ? 'rtl' : 'ltr'}`} dir={isRtl ? 'rtl' : 'ltr'}>
      <header className="sticky top-0 z-40 bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border-b border-slate-200 dark:border-slate-800">
        <div className="max-w-6xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-gradient-to-tr from-indigo-600 to-pink-500 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-500/20">
              <svg className="w-5 h-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
              </svg>
            </div>
            <h1 className="text-xl font-black tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-pink-500">{t.title}</h1>
          </div>
          <div className="flex items-center gap-4">
            {isOffline && (
              <span className="text-xs font-bold bg-amber-500/10 text-amber-600 dark:text-amber-400 px-2 py-1 rounded-full flex items-center gap-1">
                <span className="w-2 h-2 bg-amber-500 rounded-full animate-pulse"></span>
                {t.offlineReady}
              </span>
            )}
            <button onClick={() => setLang(lang === 'en' ? 'he' : 'en')} className="px-3 py-1 text-sm font-semibold rounded-full border border-slate-200 dark:border-slate-700 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors">
              {t.languageName}
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-6 py-12">
        <div className="text-center mb-12">
          <h2 className="text-4xl md:text-5xl font-extrabold mb-4 tracking-tight">{t.subtitle}</h2>
          <p className="text-slate-500 dark:text-slate-400 max-w-2xl mx-auto text-lg">
            {lang === 'en' ? 'Effortlessly transform monochromatic images into full-color photos instantly.' : 'הפוך תמונות שחור-לבן לצבעוניות באופן מיידי.'}
          </p>
        </div>

        <AdPlaceholder label={t.adPlaceholder} />

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-1 space-y-6">
            <div className="bg-white dark:bg-slate-900 p-6 rounded-3xl shadow-xl border border-slate-200 dark:border-slate-800">
              <label className="block text-sm font-bold text-slate-700 dark:text-slate-300 mb-2">{t.targetFolder}</label>
              <input 
                type="text" 
                value={targetLabel} 
                onChange={(e) => setTargetLabel(e.target.value)} 
                placeholder={t.targetFolderPlaceholder}
                className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
              />
              <div className="mt-8 space-y-3">
                <button 
                  onClick={() => {
                    const completedImages = images.filter(img => img.status === 'completed' && img.resultUrl);
                    if (completedImages.length > 0 && window.confirm(t.confirmDownload)) {
                      completedImages.forEach(img => exportSingle(img));
                    }
                  }}
                  disabled={images.filter(i => i.status === 'completed').length === 0}
                  className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-300 dark:disabled:bg-slate-800 text-white font-bold rounded-2xl shadow-lg transition-all flex items-center justify-center gap-2"
                >
                  <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                  {t.downloadAll}
                </button>
                <button onClick={() => setImages([])} className="w-full py-3 text-slate-500 dark:text-slate-400 text-sm font-semibold hover:text-red-500 transition-colors">{t.clearBtn}</button>
              </div>
            </div>
          </div>

          <div className="lg:col-span-2 space-y-6">
            <div 
              onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
              onDragEnter={(e) => { e.preventDefault(); setIsDragging(true); }}
              onDragLeave={(e) => { e.preventDefault(); setIsDragging(false); }}
              onDrop={(e) => { e.preventDefault(); setIsDragging(false); handleFiles(e.dataTransfer.files); }}
              onClick={() => fileInputRef.current?.click()}
              className={`relative group bg-white dark:bg-slate-900 border-2 border-dashed rounded-3xl p-12 text-center cursor-pointer transition-all ${isDragging ? 'border-indigo-500 scale-[1.01] bg-indigo-50/50' : 'border-slate-300 dark:border-slate-800 hover:border-indigo-500'}`}
            >
              {isDragging && <div className="absolute inset-0 z-10 bg-indigo-600/90 flex flex-col items-center justify-center text-white p-6 animate-in fade-in zoom-in-95 duration-200"><h3 className="text-3xl font-black">{t.dropNow}</h3></div>}
              <input type="file" multiple accept="image/*" className="hidden" ref={fileInputRef} onChange={(e) => handleFiles(e.target.files)} />
              <div className="w-16 h-16 bg-indigo-50 dark:bg-slate-800 rounded-full flex items-center justify-center mx-auto mb-4"><svg className="w-8 h-8 text-indigo-600" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg></div>
              <h3 className="text-xl font-bold mb-1">{t.dropzoneTitle}</h3>
              <p className="text-slate-500 text-sm">{t.dropzoneSub}</p>
            </div>

            {/* Global Progress Bar */}
            {images.length > 0 && currentlyProcessing && (
              <div className="bg-white dark:bg-slate-900 p-4 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm animate-in slide-in-from-top duration-300">
                <div className="flex items-center justify-between mb-2">
                  <span className="text-sm font-bold text-indigo-600 dark:text-indigo-400">{t.processing}</span>
                  <span className="text-sm font-black">{progressPercent}%</span>
                </div>
                <div className="w-full h-3 bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
                  <div 
                    className="h-full bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500 transition-all duration-500 ease-out relative"
                    style={{ width: `${progressPercent}%` }}
                  >
                    <div className="absolute inset-0 bg-white/20 animate-[shimmer_2s_infinite] skew-x-12 translate-x-[-100%]"></div>
                  </div>
                </div>
                <p className="mt-2 text-[10px] text-slate-400 text-center uppercase tracking-widest font-bold">
                  {processedCount} / {totalInBatch} {lang === 'en' ? 'Images Ready' : 'תמונות מוכנות'}
                </p>
              </div>
            )}

            {images.length > 0 && (
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
                {images.map(img => (
                  <ImageCard key={img.id} item={img} t={t} onRemove={(id) => setImages(prev => prev.filter(i => i.id !== id))} onSelect={setSelectedImage} onShare={shareSingle} />
                ))}
              </div>
            )}
          </div>
        </div>
      </main>

      {/* Synchronized Comparison Modal */}
      {selectedImage && (
        <div 
          ref={modalRef}
          className="fixed inset-0 z-[60] flex flex-col bg-slate-950 animate-in fade-in duration-300 overflow-hidden select-none" 
          onClick={closeOverlay}
        >
          {/* Modal Header */}
          <div className="h-20 px-6 flex items-center justify-between border-b border-white/10 bg-slate-900/50 backdrop-blur z-[70]" onClick={e => e.stopPropagation()}>
            <div className="flex items-center gap-4">
               <button onClick={closeOverlay} className="p-2 hover:bg-white/10 rounded-full transition-colors"><svg className="w-6 h-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg></button>
               <div className="flex flex-col">
                 <span className="text-white font-bold text-sm sm:text-base truncate max-w-[150px] sm:max-w-xs">{selectedImage.file.name}</span>
                 <span className="text-white/40 text-[10px] uppercase tracking-widest font-bold">{t.zoomLevel}: {Math.round(zoomLevel * 100)}%</span>
               </div>
            </div>

            {/* Advanced Controls */}
            <div className="flex items-center gap-3 sm:gap-6">
              <div className="hidden md:flex items-center gap-3 bg-white/5 px-4 py-2 rounded-2xl border border-white/10">
                <button onClick={() => adjustZoom(-0.5)} className="text-white/50 hover:text-white transition-colors"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20 12H4" /></svg></button>
                <input 
                  type="range" 
                  min="1" max="8" step="0.1" 
                  value={zoomLevel} 
                  onChange={(e) => {
                    const next = parseFloat(e.target.value);
                    setZoomLevel(next);
                    if (next === 1) setPanOffset({ x: 0, y: 0 });
                  }}
                  className="w-24 sm:w-32 accent-indigo-500 h-1 rounded-full cursor-pointer"
                />
                <button onClick={() => adjustZoom(0.5)} className="text-white/50 hover:text-white transition-colors"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg></button>
              </div>

              <div className="flex items-center gap-2">
                <button 
                  onClick={toggleFullScreen} 
                  className="p-2.5 bg-white/5 hover:bg-white/15 text-white rounded-xl border border-white/10 transition-all"
                  title={t.fullScreen}
                >
                  {isFullScreen ? (
                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                  ) : (
                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" /></svg>
                  )}
                </button>
                <button 
                  onClick={resetView} 
                  className="hidden sm:block px-4 py-2.5 bg-white/5 hover:bg-white/15 text-white/70 text-xs font-black rounded-xl border border-white/10 uppercase transition-all"
                >
                  {t.resetView}
                </button>
                <div className="w-px h-6 bg-white/20 mx-1"></div>
                <button 
                  onClick={() => exportSingle(selectedImage)} 
                  disabled={!selectedImage.resultUrl} 
                  className="flex items-center gap-2 px-5 py-2.5 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-700 text-white rounded-xl font-black text-xs uppercase tracking-tight shadow-xl shadow-indigo-600/20 transition-all"
                >
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                  {t.export}
                </button>
              </div>
            </div>
          </div>

          {/* Interactive Workspace */}
          <div 
            className={`flex-1 overflow-hidden bg-slate-900 cursor-move ${isPanning ? 'cursor-grabbing' : ''}`} 
            onMouseDown={onMouseDown} onMouseMove={onMouseMove} onMouseUp={onMouseUp} onMouseLeave={onMouseUp}
            onDoubleClick={onImageDoubleClick}
            onClick={e => e.stopPropagation()}
          >
            <div 
              className="flex flex-col lg:flex-row gap-4 h-full items-center justify-center p-8 transition-transform duration-75 ease-out will-change-transform"
              style={{ transform: `translate(${panOffset.x}px, ${panOffset.y}px) scale(${zoomLevel})` }}
            >
              <div className="relative w-full max-w-[48vw] lg:h-[75vh] aspect-auto bg-black/40 rounded-2xl overflow-hidden shadow-2xl border border-white/10 ring-1 ring-white/5">
                <img src={selectedImage.previewUrl} alt="Original" className="w-full h-full object-contain pointer-events-none" />
                <div className="absolute top-4 left-4 bg-black/60 backdrop-blur-md px-3 py-1.5 rounded-xl border border-white/20 shadow-lg"><span className="text-white text-[10px] font-black uppercase tracking-widest">{t.original}</span></div>
              </div>
              <div className="relative w-full max-w-[48vw] lg:h-[75vh] aspect-auto bg-black/40 rounded-2xl overflow-hidden shadow-2xl border border-white/10 ring-1 ring-white/5">
                {selectedImage.resultUrl ? (
                  <img src={selectedImage.resultUrl} alt="Result" className="w-full h-full object-contain animate-in fade-in duration-700 pointer-events-none" />
                ) : (
                  <div className="h-full w-full flex flex-col items-center justify-center bg-slate-900/50">
                    <div className="w-12 h-12 border-[6px] border-indigo-500/20 border-t-indigo-500 rounded-full animate-spin"></div>
                    <span className="mt-4 text-white/40 text-xs font-bold uppercase tracking-widest">{t.processing}</span>
                  </div>
                )}
                <div className="absolute top-4 left-4 bg-indigo-600/80 backdrop-blur-md px-3 py-1.5 rounded-xl border border-white/20 shadow-lg"><span className="text-white text-[10px] font-black uppercase tracking-widest">{t.result}</span></div>
              </div>
            </div>
          </div>

          {/* Subtle View Hint */}
          <div className="absolute bottom-6 left-1/2 -translate-x-1/2 pointer-events-none opacity-40">
             <span className="text-white text-[9px] font-bold uppercase tracking-[0.3em] bg-black/20 px-4 py-2 rounded-full backdrop-blur-sm">Drag to pan • Double click to zoom</span>
          </div>
        </div>
      )}

      <footer className="py-12 border-t border-slate-200 dark:border-slate-800 text-center text-slate-400 text-sm">
        <p>© {new Date().getFullYear()} ChromaRestore AI. All Rights Reserved.</p>
        <p className="mt-2 opacity-50">{lang === 'en' ? 'Powered by Google Gemini Flash-Image' : 'מופעל ע"י Google Gemini Flash-Image'}</p>
      </footer>

      <style>{`
        @keyframes shimmer {
          0% { transform: translateX(-100%) skewX(-12deg); }
          100% { transform: translateX(200%) skewX(-12deg); }
        }
        input[type=range] {
          -webkit-appearance: none;
          background: rgba(255,255,255,0.1);
        }
        input[type=range]::-webkit-slider-thumb {
          -webkit-appearance: none;
          height: 16px;
          width: 16px;
          border-radius: 50%;
          background: #6366f1;
          cursor: pointer;
          border: 2px solid white;
          box-shadow: 0 0 10px rgba(99, 102, 241, 0.5);
        }
      `}</style>
    </div>
  );
};

export default App;

export type Language = 'en' | 'he';

export interface ImageItem {
  id: string;
  file: File;
  previewUrl: string;
  status: 'pending' | 'processing' | 'completed' | 'error';
  resultUrl?: string;
  error?: string;
}

export interface Translation {
  title: string;
  subtitle: string;
  dropzoneTitle: string;
  dropzoneSub: string;
  colorizeBtn: string;
  clearBtn: string;
  downloadAll: string;
  processing: string;
  completed: string;
  error: string;
  targetFolder: string;
  targetFolderPlaceholder: string;
  languageName: string;
  offlineReady: string;
  adPlaceholder: string;
  confirmDownload: string;
  dropNow: string;
  close: string;
  zoomIn: string;
  zoomOut: string;
  original: string;
  result: string;
  export: string;
  share: string;
  shareTitle: string;
  fullScreen: string;
  resetView: string;
  zoomLevel: string;
  imageCount: string;
}

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Language, ImageItem } from './types';
import { translations } from './i18n';
import { colorizeImage, fileToBase64 } from './services/geminiService';
import { ImageCard } from './components/ImageCard';
import { AdPlaceholder } from './components/AdPlaceholder';

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('he');
  const [images, setImages] = useState<ImageItem[]>([]);
  const [targetLabel, setTargetLabel] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [isDragging, setIsDragging] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const [zoomLevel, setZoomLevel] = useState(1);
  const [panOffset, setPanOffset] = useState({ x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  const [isFullScreen, setIsFullScreen] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const modalRef = useRef<HTMLDivElement>(null);
  const lastMousePos = useRef({ x: 0, y: 0 });

  const t = translations[lang];
  const isRtl = lang === 'he';

  const selectedImage = selectedIndex !== null ? images[selectedIndex] : null;

  // Derive progress
  const totalInBatch = images.length;
  const processedCount = images.filter(img => img.status === 'completed' || img.status === 'error').length;
  const progressPercent = totalInBatch > 0 ? Math.round((processedCount / totalInBatch) * 100) : 0;
  const currentlyProcessing = images.some(img => img.status === 'processing' || img.status === 'pending');

  useEffect(() => {
    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const processNextPending = useCallback(async () => {
    const nextItem = images.find(img => img.status === 'pending');
    if (!nextItem || isProcessing) return;

    setIsProcessing(true);
    setImages(prev => prev.map(img => 
      img.id === nextItem.id ? { ...img, status: 'processing' } : img
    ));

    try {
      const base64 = await fileToBase64(nextItem.file);
      const resultUrl = await colorizeImage(base64, nextItem.file.type);
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'completed', resultUrl } : img
      ));
    } catch (err) {
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'error', error: String(err) } : img
      ));
    } finally {
      setIsProcessing(false);
    }
  }, [images, isProcessing]);

  useEffect(() => {
    processNextPending();
  }, [images, processNextPending]);

  const handleFiles = (files: FileList | null) => {
    if (!files) return;
    const newImages: ImageItem[] = Array.from(files).map(file => ({
      id: Math.random().toString(36).substr(2, 9),
      file,
      previewUrl: URL.createObjectURL(file),
      status: 'pending'
    }));
    setImages(prev => [...prev, ...newImages]);
  };

  const adjustZoom = useCallback((delta: number) => {
    setZoomLevel(prev => {
      const next = Math.min(Math.max(prev + delta, 1), 8);
      if (next === 1) setPanOffset({ x: 0, y: 0 });
      return next;
    });
  }, []);

  const resetView = useCallback(() => {
    setZoomLevel(1);
    setPanOffset({ x: 0, y: 0 });
  }, []);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      modalRef.current?.requestFullscreen().catch(err => {
        console.error(`Error attempting to enable full-screen mode: ${err.message}`);
      });
      setIsFullScreen(true);
    } else {
      document.exitFullscreen();
      setIsFullScreen(false);
    }
  };

  useEffect(() => {
    const onFsChange = () => setIsFullScreen(!!document.fullscreenElement);
    document.addEventListener('fullscreenchange', onFsChange);
    return () => document.removeEventListener('fullscreenchange', onFsChange);
  }, []);

  const onMouseDown = (e: React.MouseEvent) => {
    if (zoomLevel > 1) {
      setIsPanning(true);
      lastMousePos.current = { x: e.clientX, y: e.clientY };
    }
  };

  const onMouseMove = (e: React.MouseEvent) => {
    if (isPanning && zoomLevel > 1) {
      const dx = e.clientX - lastMousePos.current.x;
      const dy = e.clientY - lastMousePos.current.y;
      setPanOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
      lastMousePos.current = { x: e.clientX, y: e.clientY };
    }
  };

  const onMouseUp = () => setIsPanning(false);

  const onImageDoubleClick = () => {
    if (zoomLevel > 1) resetView();
    else adjustZoom(1.5);
  };

  const closeOverlay = useCallback(() => {
    setSelectedIndex(null);
    resetView();
    if (document.fullscreenElement) document.exitFullscreen();
  }, [resetView]);

  const navigate = useCallback((dir: number) => {
    if (selectedIndex === null) return;
    const next = (selectedIndex + dir + images.length) % images.length;
    setSelectedIndex(next);
    resetView();
  }, [selectedIndex, images.length, resetView]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (selectedIndex === null) return;
      if (e.key === '+' || e.key === '=') adjustZoom(0.5);
      else if (e.key === '-' || e.key === '_') adjustZoom(-0.5);
      else if (e.key === '0') resetView();
      else if (e.key === 'f' || e.key === 'F') toggleFullScreen();
      else if (e.key === 'ArrowRight') isRtl ? navigate(-1) : navigate(1);
      else if (e.key === 'ArrowLeft') isRtl ? navigate(1) : navigate(-1);
      else if (e.key === 'Escape') closeOverlay();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [selectedIndex, adjustZoom, closeOverlay, navigate, resetView, isRtl]);

  const exportSingle = (img: ImageItem) => {
    if (!img.resultUrl) return;
    const finalPrefix = targetLabel.trim() || 'colorized';
    const link = document.createElement('a');
    link.href = img.resultUrl;
    link.download = `${finalPrefix}_${img.file.name}`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const shareSingle = async (img: ImageItem) => {
    if (!img.resultUrl) return;
    try {
      if (navigator.share) {
        await navigator.share({ title: t.title, text: t.shareTitle, url: window.location.href });
      } else {
        await navigator.clipboard.writeText(window.location.href);
        alert(isRtl ? 'הקישור הועתק!' : 'Link copied to clipboard!');
      }
    } catch (err) { console.error('Sharing failed', err); }
  };

  return (
    <div className={`min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 font-sans ${isRtl ? 'rtl' : 'ltr'}`} dir={isRtl ? 'rtl' : 'ltr'}>
      <header className="sticky top-0 z-40 bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border-b border-slate-200 dark:border-slate-800">
        <div className="max-w-6xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-gradient-to-tr from-indigo-600 to-pink-500 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-500/20">
              <svg className="w-5 h-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
              </svg>
            </div>
            <h1 className="text-xl font-black tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-pink-500">{t.title}</h1>
          </div>
          <div className="flex items-center gap-4">
            {isOffline && (
              <span className="text-xs font-bold bg-amber-500/10 text-amber-600 dark:text-amber-400 px-2 py-1 rounded-full flex items-center gap-1">
                <span className="w-2 h-2 bg-amber-500 rounded-full animate-pulse"></span>
                {t.offlineReady}
              </span>
            )}
            <button onClick={() => setLang(lang === 'en' ? 'he' : 'en')} className="px-3 py-1 text-sm font-semibold rounded-full border border-slate-200 dark:border-slate-700 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors">
              {t.languageName}
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-6 py-12">
        <div className="text-center mb-12">
          <h2 className="text-4xl md:text-5xl font-extrabold mb-4 tracking-tight">{t.subtitle}</h2>
          <p className="text-slate-500 dark:text-slate-400 max-w-2xl mx-auto text-lg">
            {lang === 'en' ? 'Effortlessly transform monochromatic images into full-color photos instantly.' : 'הפוך תמונות שחור-לבן לצבעוניות באופן מיידי.'}
          </p>
        </div>

        <AdPlaceholder label={t.adPlaceholder} />

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-1 space-y-6">
            <div className="bg-white dark:bg-slate-900 p-6 rounded-3xl shadow-xl border border-slate-200 dark:border-slate-800">
              <label className="block text-sm font-bold text-slate-700 dark:text-slate-300 mb-2">{t.targetFolder}</label>
              <input 
                type="text" 
                value={targetLabel} 
                onChange={(e) => setTargetLabel(e.target.value)} 
                placeholder={t.targetFolderPlaceholder}
                className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
              />
              <div className="mt-8 space-y-3">
                <button 
                  onClick={() => {
                    const completedImages = images.filter(img => img.status === 'completed' && img.resultUrl);
                    if (completedImages.length > 0 && window.confirm(t.confirmDownload)) {
                      completedImages.forEach(img => exportSingle(img));
                    }
                  }}
                  disabled={images.filter(i => i.status === 'completed').length === 0}
                  className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-300 dark:disabled:bg-slate-800 text-white font-bold rounded-2xl shadow-lg transition-all flex items-center justify-center gap-2"
                >
                  <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                  {t.downloadAll}
                </button>
                <button onClick={() => setImages([])} className="w-full py-3 text-slate-500 dark:text-slate-400 text-sm font-semibold hover:text-red-500 transition-colors">{t.clearBtn}</button>
              </div>
            </div>
          </div>

          <div className="lg:col-span-2 space-y-6">
            <div 
              onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
              onDragEnter={(e) => { e.preventDefault(); setIsDragging(true); }}
              onDragLeave={(e) => { e.preventDefault(); setIsDragging(false); }}
              onDrop={(e) => { e.preventDefault(); setIsDragging(false); handleFiles(e.dataTransfer.files); }}
              onClick={() => fileInputRef.current?.click()}
              className={`relative group bg-white dark:bg-slate-900 border-2 border-dashed rounded-3xl p-12 text-center cursor-pointer transition-all ${isDragging ? 'border-indigo-500 scale-[1.01] bg-indigo-50/50' : 'border-slate-300 dark:border-slate-800 hover:border-indigo-500'}`}
            >
              {isDragging && <div className="absolute inset-0 z-10 bg-indigo-600/90 flex flex-col items-center justify-center text-white p-6 animate-in fade-in zoom-in-95 duration-200"><h3 className="text-3xl font-black">{t.dropNow}</h3></div>}
              <input type="file" multiple accept="image/*" className="hidden" ref={fileInputRef} onChange={(e) => handleFiles(e.target.files)} />
              <div className="w-16 h-16 bg-indigo-50 dark:bg-slate-800 rounded-full flex items-center justify-center mx-auto mb-4"><svg className="w-8 h-8 text-indigo-600" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg></div>
              <h3 className="text-xl font-bold mb-1">{t.dropzoneTitle}</h3>
              <p className="text-slate-500 text-sm">{t.dropzoneSub}</p>
            </div>

            {/* Global Progress Bar */}
            {images.length > 0 && currentlyProcessing && (
              <div className="bg-white dark:bg-slate-900 p-4 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm animate-in slide-in-from-top duration-300">
                <div className="flex items-center justify-between mb-2">
                  <span className="text-sm font-bold text-indigo-600 dark:text-indigo-400">{t.processing}</span>
                  <span className="text-sm font-black">{progressPercent}%</span>
                </div>
                <div className="w-full h-3 bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
                  <div 
                    className="h-full bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500 transition-all duration-500 ease-out relative"
                    style={{ width: `${progressPercent}%` }}
                  >
                    <div className="absolute inset-0 bg-white/20 animate-[shimmer_2s_infinite] skew-x-12 translate-x-[-100%]"></div>
                  </div>
                </div>
                <p className="mt-2 text-[10px] text-slate-400 text-center uppercase tracking-widest font-bold">
                  {processedCount} / {totalInBatch} {lang === 'en' ? 'Images Ready' : 'תמונות מוכנות'}
                </p>
              </div>
            )}

            {images.length > 0 && (
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
                {images.map((img, idx) => (
                  <ImageCard 
                    key={img.id} 
                    item={img} 
                    t={t} 
                    onRemove={(id) => setImages(prev => prev.filter(i => i.id !== id))} 
                    onSelect={() => setSelectedIndex(idx)} 
                    onShare={shareSingle} 
                  />
                ))}
              </div>
            )}
          </div>
        </div>
      </main>

      {/* Advanced Synchronized Comparison Modal */}
      {selectedImage && (
        <div 
          ref={modalRef}
          className="fixed inset-0 z-[60] flex flex-col bg-slate-950 animate-in fade-in duration-300 overflow-hidden select-none" 
          onClick={closeOverlay}
        >
          {/* Modal Header */}
          <div className="h-20 px-6 flex items-center justify-between border-b border-white/10 bg-slate-900/50 backdrop-blur z-[70]" onClick={e => e.stopPropagation()}>
            <div className="flex items-center gap-4">
               <button onClick={closeOverlay} className="p-2 hover:bg-white/10 rounded-full transition-colors text-white" aria-label={t.close}>
                 <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
               </button>
               <div className="flex flex-col">
                 <span className="text-white font-bold text-sm sm:text-base truncate max-w-[120px] sm:max-w-xs">{selectedImage.file.name}</span>
                 <span className="text-indigo-400 text-[10px] uppercase tracking-widest font-black">
                   {t.imageCount.replace('{current}', String((selectedIndex || 0) + 1)).replace('{total}', String(images.length))}
                 </span>
               </div>
            </div>

            {/* Modal Controls */}
            <div className="flex items-center gap-3">
              {/* Desktop Nav */}
              <div className="hidden sm:flex items-center gap-1 mr-4">
                 <button onClick={() => navigate(-1)} className="p-2 hover:bg-white/10 text-white rounded-lg"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg></button>
                 <button onClick={() => navigate(1)} className="p-2 hover:bg-white/10 text-white rounded-lg"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg></button>
              </div>

              <div className="hidden lg:flex items-center gap-3 bg-white/5 px-4 py-2 rounded-2xl border border-white/10">
                <button onClick={() => adjustZoom(-0.5)} className="text-white/50 hover:text-white transition-colors" title={t.zoomOut}><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20 12H4" /></svg></button>
                <input 
                  type="range" 
                  min="1" max="8" step="0.1" 
                  value={zoomLevel} 
                  onChange={(e) => {
                    const next = parseFloat(e.target.value);
                    setZoomLevel(next);
                    if (next === 1) setPanOffset({ x: 0, y: 0 });
                  }}
                  className="w-24 sm:w-32 accent-indigo-500 h-1 rounded-full cursor-pointer"
                />
                <button onClick={() => adjustZoom(0.5)} className="text-white/50 hover:text-white transition-colors" title={t.zoomIn}><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg></button>
              </div>

              <div className="flex items-center gap-2">
                <button 
                  onClick={toggleFullScreen} 
                  className="p-2.5 bg-white/5 hover:bg-white/15 text-white rounded-xl border border-white/10 transition-all"
                  title={t.fullScreen}
                >
                  {isFullScreen ? (
                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                  ) : (
                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" /></svg>
                  )}
                </button>
                <button 
                  onClick={resetView} 
                  className="hidden md:block px-4 py-2.5 bg-white/5 hover:bg-white/15 text-white/70 text-[10px] font-black rounded-xl border border-white/10 uppercase tracking-widest transition-all"
                >
                  {t.resetView}
                </button>
                <div className="w-px h-6 bg-white/20 mx-1"></div>
                <button 
                  onClick={() => exportSingle(selectedImage)} 
                  disabled={!selectedImage.resultUrl} 
                  className="flex items-center gap-2 px-5 py-2.5 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-700 text-white rounded-xl font-black text-xs uppercase tracking-tight shadow-xl shadow-indigo-600/20 transition-all"
                >
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                  {t.export}
                </button>
              </div>
            </div>
          </div>

          {/* Large Navigation Overlay (Mobile/Touch Friendly) */}
          <div className="absolute inset-y-0 left-0 w-16 flex items-center justify-center z-[80] pointer-events-none sm:hidden">
             <button onClick={(e) => { e.stopPropagation(); navigate(-1); }} className="p-3 bg-black/20 text-white rounded-full pointer-events-auto backdrop-blur-sm"><svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg></button>
          </div>
          <div className="absolute inset-y-0 right-0 w-16 flex items-center justify-center z-[80] pointer-events-none sm:hidden">
             <button onClick={(e) => { e.stopPropagation(); navigate(1); }} className="p-3 bg-black/20 text-white rounded-full pointer-events-auto backdrop-blur-sm"><svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg></button>
          </div>

          {/* Interactive Comparison Area */}
          <div 
            className={`flex-1 overflow-hidden bg-slate-900 cursor-move relative ${isPanning ? 'cursor-grabbing' : ''}`} 
            onMouseDown={onMouseDown} onMouseMove={onMouseMove} onMouseUp={onMouseUp} onMouseLeave={onMouseUp}
            onDoubleClick={onImageDoubleClick}
            onClick={e => e.stopPropagation()}
          >
            <div 
              className="flex flex-col lg:flex-row gap-4 h-full items-center justify-center p-8 transition-transform duration-150 ease-out will-change-transform"
              style={{ transform: `translate(${panOffset.x}px, ${panOffset.y}px) scale(${zoomLevel})` }}
            >
              {/* Original Section */}
              <div className="relative w-full max-w-[48vw] lg:h-[75vh] aspect-auto bg-black/40 rounded-2xl overflow-hidden shadow-2xl border border-white/10 ring-1 ring-white/5 flex items-center justify-center">
                <img src={selectedImage.previewUrl} alt="Original" className="max-w-full max-h-full object-contain pointer-events-none" />
                <div className="absolute top-4 left-4 bg-black/60 backdrop-blur-md px-3 py-1.5 rounded-xl border border-white/20 shadow-lg"><span className="text-white text-[10px] font-black uppercase tracking-widest">{t.original}</span></div>
              </div>

              {/* Colorized Section */}
              <div className="relative w-full max-w-[48vw] lg:h-[75vh] aspect-auto bg-black/40 rounded-2xl overflow-hidden shadow-2xl border border-white/10 ring-1 ring-white/5 flex items-center justify-center">
                {selectedImage.resultUrl ? (
                  <img src={selectedImage.resultUrl} alt="Result" className="max-w-full max-h-full object-contain animate-in fade-in duration-700 pointer-events-none" />
                ) : (
                  <div className="h-full w-full flex flex-col items-center justify-center bg-slate-900/50 min-h-[300px]">
                    <div className="w-12 h-12 border-[6px] border-indigo-500/20 border-t-indigo-500 rounded-full animate-spin"></div>
                    <span className="mt-4 text-white/40 text-xs font-bold uppercase tracking-widest">{t.processing}</span>
                  </div>
                )}
                <div className="absolute top-4 left-4 bg-indigo-600/80 backdrop-blur-md px-3 py-1.5 rounded-xl border border-white/20 shadow-lg"><span className="text-white text-[10px] font-black uppercase tracking-widest">{t.result}</span></div>
              </div>
            </div>
          </div>

          {/* Status Label for Index */}
          <div className="absolute bottom-6 left-1/2 -translate-x-1/2 pointer-events-none flex flex-col items-center gap-2">
             <span className="text-white/40 text-[9px] font-bold uppercase tracking-[0.3em] bg-black/20 px-6 py-2.5 rounded-full backdrop-blur-md border border-white/5">
               {isRtl ? 'גרור להזזה • לחיצה כפולה לזום' : 'Drag to pan • Double click to zoom'}
             </span>
          </div>
        </div>
      )}

      <footer className="py-12 border-t border-slate-200 dark:border-slate-800 text-center text-slate-400 text-sm">
        <p>© {new Date().getFullYear()} ChromaRestore AI. All Rights Reserved.</p>
        <p className="mt-2 opacity-50">{lang === 'en' ? 'Powered by Google Gemini Flash-Image' : 'מופעל ע"י Google Gemini Flash-Image'}</p>
      </footer>

      <style>{`
        @keyframes shimmer {
          0% { transform: translateX(-100%) skewX(-12deg); }
          100% { transform: translateX(200%) skewX(-12deg); }
        }
        input[type=range] {
          -webkit-appearance: none;
          background: rgba(255,255,255,0.1);
        }
        input[type=range]::-webkit-slider-thumb {
          -webkit-appearance: none;
          height: 16px;
          width: 16px;
          border-radius: 50%;
          background: #6366f1;
          cursor: pointer;
          border: 2px solid white;
          box-shadow: 0 0 10px rgba(99, 102, 241, 0.5);
        }
        :fullscreen {
          background-color: #020617;
        }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Language, ImageItem } from './types';
import { translations } from './i18n';
import { colorizeImage, fileToBase64 } from './services/geminiService';
import { ImageCard } from './components/ImageCard';
import { AdPlaceholder } from './components/AdPlaceholder';

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('he');
  const [images, setImages] = useState<ImageItem[]>([]);
  const [targetLabel, setTargetLabel] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [isDragging, setIsDragging] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const [zoomLevel, setZoomLevel] = useState(1);
  const [panOffset, setPanOffset] = useState({ x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  const [isFullScreen, setIsFullScreen] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const modalRef = useRef<HTMLDivElement>(null);
  const lastMousePos = useRef({ x: 0, y: 0 });
  const velocity = useRef({ x: 0, y: 0 });
  const lastTimestamp = useRef(0);
  const animationFrameId = useRef<number | null>(null);

  const t = translations[lang];
  const isRtl = lang === 'he';

  const selectedImage = selectedIndex !== null ? images[selectedIndex] : null;

  // Derive progress
  const totalInBatch = images.length;
  const processedCount = images.filter(img => img.status === 'completed' || img.status === 'error').length;
  const progressPercent = totalInBatch > 0 ? Math.round((processedCount / totalInBatch) * 100) : 0;
  const currentlyProcessing = images.some(img => img.status === 'processing' || img.status === 'pending');

  useEffect(() => {
    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const processNextPending = useCallback(async () => {
    const nextItem = images.find(img => img.status === 'pending');
    if (!nextItem || isProcessing) return;

    setIsProcessing(true);
    setImages(prev => prev.map(img => 
      img.id === nextItem.id ? { ...img, status: 'processing' } : img
    ));

    try {
      const base64 = await fileToBase64(nextItem.file);
      const resultUrl = await colorizeImage(base64, nextItem.file.type);
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'completed', resultUrl } : img
      ));
    } catch (err) {
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'error', error: String(err) } : img
      ));
    } finally {
      setIsProcessing(false);
    }
  }, [images, isProcessing]);

  useEffect(() => {
    processNextPending();
  }, [images, processNextPending]);

  const handleFiles = (files: FileList | null) => {
    if (!files) return;
    const newImages: ImageItem[] = Array.from(files).map(file => ({
      id: Math.random().toString(36).substr(2, 9),
      file,
      previewUrl: URL.createObjectURL(file),
      status: 'pending'
    }));
    setImages(prev => [...prev, ...newImages]);
  };

  const adjustZoom = useCallback((delta: number) => {
    setZoomLevel(prev => {
      const next = Math.min(Math.max(prev + delta, 1), 8);
      if (next === 1) setPanOffset({ x: 0, y: 0 });
      return next;
    });
  }, []);

  const resetView = useCallback(() => {
    if (animationFrameId.current) cancelAnimationFrame(animationFrameId.current);
    setZoomLevel(1);
    setPanOffset({ x: 0, y: 0 });
    velocity.current = { x: 0, y: 0 };
  }, []);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      modalRef.current?.requestFullscreen().catch(err => {
        console.error(`Error attempting to enable full-screen mode: ${err.message}`);
      });
      setIsFullScreen(true);
    } else {
      document.exitFullscreen();
      setIsFullScreen(false);
    }
  };

  useEffect(() => {
    const onFsChange = () => setIsFullScreen(!!document.fullscreenElement);
    document.addEventListener('fullscreenchange', onFsChange);
    return () => document.removeEventListener('fullscreenchange', onFsChange);
  }, []);

  // Inertia Panning Logic
  const startInertia = useCallback(() => {
    const step = () => {
      setPanOffset(prev => ({
        x: prev.x + velocity.current.x * 12,
        y: prev.y + velocity.current.y * 12
      }));
      velocity.current.x *= 0.92; // Friction
      velocity.current.y *= 0.92;

      if (Math.abs(velocity.current.x) > 0.05 || Math.abs(velocity.current.y) > 0.05) {
        animationFrameId.current = requestAnimationFrame(step);
      } else {
        velocity.current = { x: 0, y: 0 };
        animationFrameId.current = null;
      }
    };
    animationFrameId.current = requestAnimationFrame(step);
  }, []);

  const onMouseDown = (e: React.MouseEvent) => {
    if (zoomLevel > 1) {
      if (animationFrameId.current) cancelAnimationFrame(animationFrameId.current);
      setIsPanning(true);
      lastMousePos.current = { x: e.clientX, y: e.clientY };
      lastTimestamp.current = performance.now();
      velocity.current = { x: 0, y: 0 };
    }
  };

  const onMouseMove = (e: React.MouseEvent) => {
    if (isPanning && zoomLevel > 1) {
      const now = performance.now();
      const dt = now - lastTimestamp.current;
      const dx = e.clientX - lastMousePos.current.x;
      const dy = e.clientY - lastMousePos.current.y;

      if (dt > 0) {
        velocity.current = { x: dx / dt, y: dy / dt };
      }

      setPanOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
      lastMousePos.current = { x: e.clientX, y: e.clientY };
      lastTimestamp.current = now;
    }
  };

  const onMouseUp = () => {
    if (isPanning) {
      setIsPanning(false);
      startInertia();
    }
  };

  const onWheel = (e: React.WheelEvent) => {
    e.stopPropagation();
    const delta = e.deltaY > 0 ? -0.2 : 0.2;
    adjustZoom(delta);
  };

  const onImageDoubleClick = () => {
    if (zoomLevel > 1) resetView();
    else adjustZoom(1.5);
  };

  const closeOverlay = useCallback(() => {
    setSelectedIndex(null);
    resetView();
    if (document.fullscreenElement) document.exitFullscreen();
  }, [resetView]);

  const navigate = useCallback((dir: number) => {
    if (selectedIndex === null) return;
    const next = (selectedIndex + dir + images.length) % images.length;
    setSelectedIndex(next);
    resetView();
  }, [selectedIndex, images.length, resetView]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (selectedIndex === null) return;
      if (e.key === '+' || e.key === '=') adjustZoom(0.5);
      else if (e.key === '-' || e.key === '_') adjustZoom(-0.5);
      else if (e.key === '0') resetView();
      else if (e.key === 'f' || e.key === 'F') toggleFullScreen();
      else if (e.key === 'ArrowRight') isRtl ? navigate(-1) : navigate(1);
      else if (e.key === 'ArrowLeft') isRtl ? navigate(1) : navigate(-1);
      else if (e.key === 'Escape') closeOverlay();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [selectedIndex, adjustZoom, closeOverlay, navigate, resetView, isRtl]);

  const exportSingle = (img: ImageItem) => {
    if (!img.resultUrl) return;
    const finalPrefix = targetLabel.trim() || 'colorized';
    const link = document.createElement('a');
    link.href = img.resultUrl;
    link.download = `${finalPrefix}_${img.file.name}`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const exportAll = () => {
    const completedImages = images.filter(img => img.status === 'completed' && img.resultUrl);
    if (completedImages.length === 0) return;

    if (window.confirm(`${t.confirmDownload} (${completedImages.length} images)`)) {
      completedImages.forEach((img, idx) => {
        // Delay slightly between downloads to avoid browser blocks
        setTimeout(() => exportSingle(img), idx * 250);
      });
    }
  };

  const shareSingle = async (img: ImageItem) => {
    if (!img.resultUrl) return;
    try {
      if (navigator.share) {
        await navigator.share({ title: t.title, text: t.shareTitle, url: window.location.href });
      } else {
        await navigator.clipboard.writeText(window.location.href);
        alert(isRtl ? 'הקישור הועתק!' : 'Link copied to clipboard!');
      }
    } catch (err) { console.error('Sharing failed', err); }
  };

  return (
    <div className={`min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 font-sans ${isRtl ? 'rtl' : 'ltr'}`} dir={isRtl ? 'rtl' : 'ltr'}>
      <header className="sticky top-0 z-40 bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border-b border-slate-200 dark:border-slate-800">
        <div className="max-w-6xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-gradient-to-tr from-indigo-600 to-pink-500 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-500/20">
              <svg className="w-5 h-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
              </svg>
            </div>
            <h1 className="text-xl font-black tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-pink-500">{t.title}</h1>
          </div>
          <div className="flex items-center gap-4">
            {isOffline && (
              <span className="text-xs font-bold bg-amber-500/10 text-amber-600 dark:text-amber-400 px-2 py-1 rounded-full flex items-center gap-1">
                <span className="w-2 h-2 bg-amber-500 rounded-full animate-pulse"></span>
                {t.offlineReady}
              </span>
            )}
            <button onClick={() => setLang(lang === 'en' ? 'he' : 'en')} className="px-3 py-1 text-sm font-semibold rounded-full border border-slate-200 dark:border-slate-700 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors">
              {t.languageName}
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-6 py-12">
        <div className="text-center mb-12">
          <h2 className="text-4xl md:text-5xl font-extrabold mb-4 tracking-tight">{t.subtitle}</h2>
          <p className="text-slate-500 dark:text-slate-400 max-w-2xl mx-auto text-lg">
            {lang === 'en' ? 'Effortlessly transform monochromatic images into full-color photos instantly.' : 'הפוך תמונות שחור-לבן לצבעוניות באופן מיידי.'}
          </p>
        </div>

        <AdPlaceholder label={t.adPlaceholder} />

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-1 space-y-6">
            <div className="bg-white dark:bg-slate-900 p-6 rounded-3xl shadow-xl border border-slate-200 dark:border-slate-800">
              <label className="block text-sm font-bold text-slate-700 dark:text-slate-300 mb-2">{t.targetFolder}</label>
              <input 
                type="text" 
                value={targetLabel} 
                onChange={(e) => setTargetLabel(e.target.value)} 
                placeholder={t.targetFolderPlaceholder}
                className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
              />
              <div className="mt-8 space-y-3">
                <button 
                  onClick={exportAll}
                  disabled={images.filter(i => i.status === 'completed').length === 0}
                  className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-300 dark:disabled:bg-slate-800 text-white font-bold rounded-2xl shadow-lg transition-all flex items-center justify-center gap-2"
                >
                  <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                  {t.downloadAll}
                </button>
                <button onClick={() => setImages([])} className="w-full py-3 text-slate-500 dark:text-slate-400 text-sm font-semibold hover:text-red-500 transition-colors">{t.clearBtn}</button>
              </div>
            </div>
          </div>

          <div className="lg:col-span-2 space-y-6">
            <div 
              onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
              onDragEnter={(e) => { e.preventDefault(); setIsDragging(true); }}
              onDragLeave={(e) => { e.preventDefault(); setIsDragging(false); }}
              onDrop={(e) => { e.preventDefault(); setIsDragging(false); handleFiles(e.dataTransfer.files); }}
              onClick={() => fileInputRef.current?.click()}
              className={`relative group bg-white dark:bg-slate-900 border-2 border-dashed rounded-3xl p-12 text-center cursor-pointer transition-all ${isDragging ? 'border-indigo-500 scale-[1.01] bg-indigo-50/50' : 'border-slate-300 dark:border-slate-800 hover:border-indigo-500'}`}
            >
              {isDragging && <div className="absolute inset-0 z-10 bg-indigo-600/90 flex flex-col items-center justify-center text-white p-6 animate-in fade-in zoom-in-95 duration-200"><h3 className="text-3xl font-black">{t.dropNow}</h3></div>}
              <input type="file" multiple accept="image/*" className="hidden" ref={fileInputRef} onChange={(e) => handleFiles(e.target.files)} />
              <div className="w-16 h-16 bg-indigo-50 dark:bg-slate-800 rounded-full flex items-center justify-center mx-auto mb-4"><svg className="w-8 h-8 text-indigo-600" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg></div>
              <h3 className="text-xl font-bold mb-1">{t.dropzoneTitle}</h3>
              <p className="text-slate-500 text-sm">{t.dropzoneSub}</p>
            </div>

            {/* Global Progress Bar */}
            {images.length > 0 && currentlyProcessing && (
              <div className="bg-white dark:bg-slate-900 p-4 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm animate-in slide-in-from-top duration-300">
                <div className="flex items-center justify-between mb-2">
                  <span className="text-sm font-bold text-indigo-600 dark:text-indigo-400">{t.processing}</span>
                  <span className="text-sm font-black">{progressPercent}%</span>
                </div>
                <div className="w-full h-3 bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
                  <div 
                    className="h-full bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500 transition-all duration-500 ease-out relative"
                    style={{ width: `${progressPercent}%` }}
                  >
                    <div className="absolute inset-0 bg-white/20 animate-[shimmer_2s_infinite] skew-x-12 translate-x-[-100%]"></div>
                  </div>
                </div>
                <p className="mt-2 text-[10px] text-slate-400 text-center uppercase tracking-widest font-bold">
                  {processedCount} / {totalInBatch} {lang === 'en' ? 'Images Ready' : 'תמונות מוכנות'}
                </p>
              </div>
            )}

            {images.length > 0 && (
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
                {images.map((img, idx) => (
                  <ImageCard 
                    key={img.id} 
                    item={img} 
                    t={t} 
                    onRemove={(id) => setImages(prev => prev.filter(i => i.id !== id))} 
                    onSelect={() => setSelectedIndex(idx)} 
                    onShare={shareSingle} 
                  />
                ))}
              </div>
            )}
          </div>
        </div>
      </main>

      {/* Advanced Synchronized Comparison Modal */}
      {selectedImage && (
        <div 
          ref={modalRef}
          className="fixed inset-0 z-[60] flex flex-col bg-slate-950 animate-in fade-in duration-300 overflow-hidden select-none" 
          onClick={closeOverlay}
        >
          {/* Modal Header */}
          <div className="h-20 px-6 flex items-center justify-between border-b border-white/10 bg-slate-900/50 backdrop-blur z-[70]" onClick={e => e.stopPropagation()}>
            <div className="flex items-center gap-4">
               <button onClick={closeOverlay} className="p-2 hover:bg-white/10 rounded-full transition-colors text-white" aria-label={t.close}>
                 <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
               </button>
               <div className="flex flex-col">
                 <span className="text-white font-bold text-sm sm:text-base truncate max-w-[120px] sm:max-w-xs">{selectedImage.file.name}</span>
                 <span className="text-indigo-400 text-[10px] uppercase tracking-widest font-black">
                   {t.imageCount.replace('{current}', String((selectedIndex || 0) + 1)).replace('{total}', String(images.length))}
                 </span>
               </div>
            </div>

            {/* Modal Controls */}
            <div className="flex items-center gap-3">
              <div className="hidden sm:flex items-center gap-1 mr-4">
                 <button onClick={() => navigate(-1)} className="p-2 hover:bg-white/10 text-white rounded-lg"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg></button>
                 <button onClick={() => navigate(1)} className="p-2 hover:bg-white/10 text-white rounded-lg"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg></button>
              </div>

              <div className="hidden lg:flex items-center gap-3 bg-white/5 px-4 py-2 rounded-2xl border border-white/10">
                <button onClick={() => adjustZoom(-0.5)} className="text-white/50 hover:text-white transition-colors" title={t.zoomOut}><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20 12H4" /></svg></button>
                <input 
                  type="range" 
                  min="1" max="8" step="0.1" 
                  value={zoomLevel} 
                  onChange={(e) => {
                    const next = parseFloat(e.target.value);
                    setZoomLevel(next);
                    if (next === 1) setPanOffset({ x: 0, y: 0 });
                  }}
                  className="w-24 sm:w-32 accent-indigo-500 h-1 rounded-full cursor-pointer"
                />
                <button onClick={() => adjustZoom(0.5)} className="text-white/50 hover:text-white transition-colors" title={t.zoomIn}><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg></button>
              </div>

              <div className="flex items-center gap-2">
                <button 
                  onClick={toggleFullScreen} 
                  className="p-2.5 bg-white/5 hover:bg-white/15 text-white rounded-xl border border-white/10 transition-all"
                  title={t.fullScreen}
                >
                  {isFullScreen ? (
                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                  ) : (
                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" /></svg>
                  )}
                </button>
                <button 
                  onClick={resetView} 
                  className="hidden md:block px-4 py-2.5 bg-white/5 hover:bg-white/15 text-white/70 text-[10px] font-black rounded-xl border border-white/10 uppercase tracking-widest transition-all"
                >
                  {t.resetView}
                </button>
                <div className="w-px h-6 bg-white/20 mx-1"></div>
                <button 
                  onClick={() => exportSingle(selectedImage)} 
                  disabled={!selectedImage.resultUrl} 
                  className="flex items-center gap-2 px-5 py-2.5 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-700 text-white rounded-xl font-black text-xs uppercase tracking-tight shadow-xl shadow-indigo-600/20 transition-all"
                >
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                  {t.export}
                </button>
              </div>
            </div>
          </div>

          {/* Large Navigation Overlay */}
          <div className="absolute inset-y-0 left-0 w-16 flex items-center justify-center z-[80] pointer-events-none sm:hidden">
             <button onClick={(e) => { e.stopPropagation(); navigate(-1); }} className="p-3 bg-black/20 text-white rounded-full pointer-events-auto backdrop-blur-sm"><svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg></button>
          </div>
          <div className="absolute inset-y-0 right-0 w-16 flex items-center justify-center z-[80] pointer-events-none sm:hidden">
             <button onClick={(e) => { e.stopPropagation(); navigate(1); }} className="p-3 bg-black/20 text-white rounded-full pointer-events-auto backdrop-blur-sm"><svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg></button>
          </div>

          {/* Interactive Comparison Area */}
          <div 
            className={`flex-1 overflow-hidden bg-slate-900 cursor-move relative ${isPanning ? 'cursor-grabbing' : ''}`} 
            onMouseDown={onMouseDown} onMouseMove={onMouseMove} onMouseUp={onMouseUp} onMouseLeave={onMouseUp}
            onWheel={onWheel}
            onDoubleClick={onImageDoubleClick}
            onClick={e => e.stopPropagation()}
          >
            <div 
              className="flex flex-col lg:flex-row gap-4 h-full items-center justify-center p-8 transition-transform duration-[50ms] ease-out will-change-transform"
              style={{ transform: `translate(${panOffset.x}px, ${panOffset.y}px) scale(${zoomLevel})` }}
            >
              {/* Original Section */}
              <div className="relative w-full max-w-[48vw] lg:h-[75vh] aspect-auto bg-black/40 rounded-2xl overflow-hidden shadow-2xl border border-white/10 ring-1 ring-white/5 flex items-center justify-center">
                <img src={selectedImage.previewUrl} alt="Original" className="max-w-full max-h-full object-contain pointer-events-none" />
                <div className="absolute top-4 left-4 bg-black/60 backdrop-blur-md px-3 py-1.5 rounded-xl border border-white/20 shadow-lg"><span className="text-white text-[10px] font-black uppercase tracking-widest">{t.original}</span></div>
              </div>

              {/* Colorized Section */}
              <div className="relative w-full max-w-[48vw] lg:h-[75vh] aspect-auto bg-black/40 rounded-2xl overflow-hidden shadow-2xl border border-white/10 ring-1 ring-white/5 flex items-center justify-center">
                {selectedImage.resultUrl ? (
                  <img src={selectedImage.resultUrl} alt="Result" className="max-w-full max-h-full object-contain animate-in fade-in duration-700 pointer-events-none" />
                ) : (
                  <div className="h-full w-full flex flex-col items-center justify-center bg-slate-900/50 min-h-[300px]">
                    <div className="w-12 h-12 border-[6px] border-indigo-500/20 border-t-indigo-500 rounded-full animate-spin"></div>
                    <span className="mt-4 text-white/40 text-xs font-bold uppercase tracking-widest">{t.processing}</span>
                  </div>
                )}
                <div className="absolute top-4 left-4 bg-indigo-600/80 backdrop-blur-md px-3 py-1.5 rounded-xl border border-white/20 shadow-lg"><span className="text-white text-[10px] font-black uppercase tracking-widest">{t.result}</span></div>
              </div>
            </div>
          </div>

          <div className="absolute bottom-6 left-1/2 -translate-x-1/2 pointer-events-none flex flex-col items-center gap-2">
             <span className="text-white/40 text-[9px] font-bold uppercase tracking-[0.3em] bg-black/20 px-6 py-2.5 rounded-full backdrop-blur-md border border-white/5">
               {isRtl ? 'גלור להזזה • לחיצה כפולה לזום • גלגלת לשינוי גודל' : 'Drag to pan • Double click to zoom • Scroll to zoom'}
             </span>
          </div>
        </div>
      )}

      <footer className="py-12 border-t border-slate-200 dark:border-slate-800 text-center text-slate-400 text-sm">
        <p>© {new Date().getFullYear()} ChromaRestore AI. All Rights Reserved.</p>
        <p className="mt-2 opacity-50">{lang === 'en' ? 'Powered by Google Gemini Flash-Image' : 'מופעל ע"י Google Gemini Flash-Image'}</p>
      </footer>

      <style>{`
        @keyframes shimmer {
          0% { transform: translateX(-100%) skewX(-12deg); }
          100% { transform: translateX(200%) skewX(-12deg); }
        }
        input[type=range] {
          -webkit-appearance: none;
          background: rgba(255,255,255,0.1);
        }
        input[type=range]::-webkit-slider-thumb {
          -webkit-appearance: none;
          height: 16px;
          width: 16px;
          border-radius: 50%;
          background: #6366f1;
          cursor: pointer;
          border: 2px solid white;
          box-shadow: 0 0 10px rgba(99, 102, 241, 0.5);
        }
        :fullscreen {
          background-color: #020617;
        }
      `}</style>
    </div>
  );
};

export default App;

export type Language = 'en' | 'he';

export interface ImageItem {
  id: string;
  file: File;
  previewUrl: string;
  status: 'pending' | 'processing' | 'completed' | 'error';
  resultUrl?: string;
  error?: string;
}

export interface Translation {
  title: string;
  subtitle: string;
  dropzoneTitle: string;
  dropzoneSub: string;
  colorizeBtn: string;
  clearBtn: string;
  downloadAll: string;
  processing: string;
  completed: string;
  error: string;
  targetFolder: string;
  targetFolderPlaceholder: string;
  languageName: string;
  offlineReady: string;
  adPlaceholder: string;
  confirmDownload: string;
  dropNow: string;
  close: string;
  zoomIn: string;
  zoomOut: string;
  original: string;
  result: string;
  export: string;
  share: string;
  shareTitle: string;
  fullScreen: string;
  resetView: string;
  zoomLevel: string;
  imageCount: string;
  tryExample: string;
  compareHint: string;
}

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Language, ImageItem } from './types';
import { translations } from './i18n';
import { colorizeImage, fileToBase64 } from './services/geminiService';
import { ImageCard } from './components/ImageCard';
import { AdPlaceholder } from './components/AdPlaceholder';

const EXAMPLE_IMAGES = [
  { name: 'Landscape.jpg', url: 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?q=80&w=800&auto=format&fit=crop&grayscale=true' },
  { name: 'Portrait.jpg', url: 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?q=80&w=800&auto=format&fit=crop&grayscale=true' },
  { name: 'Vintage.jpg', url: 'https://images.unsplash.com/photo-1533158307587-828f0a76ef46?q=80&w=800&auto=format&fit=crop&grayscale=true' }
];

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('he');
  const [images, setImages] = useState<ImageItem[]>([]);
  const [targetLabel, setTargetLabel] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [isDragging, setIsDragging] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const [zoomLevel, setZoomLevel] = useState(1);
  const [panOffset, setPanOffset] = useState({ x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  const [isFullScreen, setIsFullScreen] = useState(false);
  const [sliderPos, setSliderPos] = useState(50);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const modalRef = useRef<HTMLDivElement>(null);
  const lastMousePos = useRef({ x: 0, y: 0 });
  const velocity = useRef({ x: 0, y: 0 });
  const lastTimestamp = useRef(0);
  const animationFrameId = useRef<number | null>(null);

  const t = translations[lang];
  const isRtl = lang === 'he';

  const selectedImage = selectedIndex !== null ? images[selectedIndex] : null;

  useEffect(() => {
    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const processNextPending = useCallback(async () => {
    const nextItem = images.find(img => img.status === 'pending');
    if (!nextItem || isProcessing) return;

    setIsProcessing(true);
    setImages(prev => prev.map(img => 
      img.id === nextItem.id ? { ...img, status: 'processing' } : img
    ));

    try {
      const base64 = await fileToBase64(nextItem.file);
      const resultUrl = await colorizeImage(base64, nextItem.file.type);
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'completed', resultUrl } : img
      ));
    } catch (err) {
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'error', error: String(err) } : img
      ));
    } finally {
      setIsProcessing(false);
    }
  }, [images, isProcessing]);

  useEffect(() => {
    processNextPending();
  }, [images, processNextPending]);

  const handleFiles = (files: FileList | null) => {
    if (!files) return;
    const newImages: ImageItem[] = Array.from(files).map(file => ({
      id: Math.random().toString(36).substr(2, 9),
      file,
      previewUrl: URL.createObjectURL(file),
      status: 'pending'
    }));
    setImages(prev => [...prev, ...newImages]);
  };

  const loadExample = async (example: typeof EXAMPLE_IMAGES[0]) => {
    try {
      const response = await fetch(example.url);
      const blob = await response.blob();
      const file = new File([blob], example.name, { type: 'image/jpeg' });
      const newImage: ImageItem = {
        id: Math.random().toString(36).substr(2, 9),
        file,
        previewUrl: URL.createObjectURL(file),
        status: 'pending'
      };
      setImages(prev => [...prev, newImage]);
    } catch (err) {
      console.error("Failed to load example", err);
    }
  };

  const adjustZoom = useCallback((delta: number) => {
    setZoomLevel(prev => {
      const next = Math.min(Math.max(prev + delta, 1), 8);
      if (next === 1) setPanOffset({ x: 0, y: 0 });
      return next;
    });
  }, []);

  const resetView = useCallback(() => {
    if (animationFrameId.current) cancelAnimationFrame(animationFrameId.current);
    setZoomLevel(1);
    setPanOffset({ x: 0, y: 0 });
    setSliderPos(50);
    velocity.current = { x: 0, y: 0 };
  }, []);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      modalRef.current?.requestFullscreen().catch(err => {
        console.error(`Error attempting to enable full-screen mode: ${err.message}`);
      });
      setIsFullScreen(true);
    } else {
      document.exitFullscreen();
      setIsFullScreen(false);
    }
  };

  useEffect(() => {
    const onFsChange = () => setIsFullScreen(!!document.fullscreenElement);
    document.addEventListener('fullscreenchange', onFsChange);
    return () => document.removeEventListener('fullscreenchange', onFsChange);
  }, []);

  const startInertia = useCallback(() => {
    const step = () => {
      setPanOffset(prev => ({
        x: prev.x + velocity.current.x * 12,
        y: prev.y + velocity.current.y * 12
      }));
      velocity.current.x *= 0.92;
      velocity.current.y *= 0.92;

      if (Math.abs(velocity.current.x) > 0.05 || Math.abs(velocity.current.y) > 0.05) {
        animationFrameId.current = requestAnimationFrame(step);
      } else {
        velocity.current = { x: 0, y: 0 };
        animationFrameId.current = null;
      }
    };
    animationFrameId.current = requestAnimationFrame(step);
  }, []);

  const onMouseDown = (e: React.MouseEvent) => {
    if (zoomLevel > 1) {
      if (animationFrameId.current) cancelAnimationFrame(animationFrameId.current);
      setIsPanning(true);
      lastMousePos.current = { x: e.clientX, y: e.clientY };
      lastTimestamp.current = performance.now();
      velocity.current = { x: 0, y: 0 };
    }
  };

  const onMouseMove = (e: React.MouseEvent) => {
    if (isPanning && zoomLevel > 1) {
      const now = performance.now();
      const dt = now - lastTimestamp.current;
      const dx = e.clientX - lastMousePos.current.x;
      const dy = e.clientY - lastMousePos.current.y;

      if (dt > 0) velocity.current = { x: dx / dt, y: dy / dt };

      setPanOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
      lastMousePos.current = { x: e.clientX, y: e.clientY };
      lastTimestamp.current = now;
    }
  };

  const onMouseUp = () => {
    if (isPanning) {
      setIsPanning(false);
      startInertia();
    }
  };

  const onWheel = (e: React.WheelEvent) => {
    e.stopPropagation();
    const delta = e.deltaY > 0 ? -0.2 : 0.2;
    adjustZoom(delta);
  };

  const onImageDoubleClick = () => {
    if (zoomLevel > 1) resetView();
    else adjustZoom(1.5);
  };

  const closeOverlay = useCallback(() => {
    setSelectedIndex(null);
    resetView();
    if (document.fullscreenElement) document.exitFullscreen();
  }, [resetView]);

  const navigate = useCallback((dir: number) => {
    if (selectedIndex === null) return;
    const next = (selectedIndex + dir + images.length) % images.length;
    setSelectedIndex(next);
    resetView();
  }, [selectedIndex, images.length, resetView]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (selectedIndex === null) return;
      if (e.key === '+' || e.key === '=') adjustZoom(0.5);
      else if (e.key === '-' || e.key === '_') adjustZoom(-0.5);
      else if (e.key === '0') resetView();
      else if (e.key === 'f' || e.key === 'F') toggleFullScreen();
      else if (e.key === 'ArrowRight') isRtl ? navigate(-1) : navigate(1);
      else if (e.key === 'ArrowLeft') isRtl ? navigate(1) : navigate(-1);
      else if (e.key === 'Escape') closeOverlay();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [selectedIndex, adjustZoom, closeOverlay, navigate, resetView, isRtl]);

  const exportSingle = (img: ImageItem) => {
    if (!img.resultUrl) return;
    const finalPrefix = targetLabel.trim() || 'colorized';
    const link = document.createElement('a');
    link.href = img.resultUrl;
    link.download = `${finalPrefix}_${img.file.name}`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const exportAll = () => {
    const completedImages = images.filter(img => img.status === 'completed' && img.resultUrl);
    if (completedImages.length === 0) return;
    if (window.confirm(`${t.confirmDownload} (${completedImages.length} images)`)) {
      completedImages.forEach((img, idx) => {
        setTimeout(() => exportSingle(img), idx * 250);
      });
    }
  };

  const shareSingle = async (img: ImageItem) => {
    if (!img.resultUrl) return;
    try {
      if (navigator.share) {
        await navigator.share({ title: t.title, text: t.shareTitle, url: window.location.href });
      } else {
        await navigator.clipboard.writeText(window.location.href);
        alert(isRtl ? 'הקישור הועתק!' : 'Link copied to clipboard!');
      }
    } catch (err) { console.error('Sharing failed', err); }
  };

  const totalInBatch = images.length;
  const processedCount = images.filter(img => img.status === 'completed' || img.status === 'error').length;
  const progressPercent = totalInBatch > 0 ? Math.round((processedCount / totalInBatch) * 100) : 0;
  const currentlyProcessing = images.some(img => img.status === 'processing' || img.status === 'pending');

  return (
    <div className={`min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 font-sans ${isRtl ? 'rtl' : 'ltr'}`} dir={isRtl ? 'rtl' : 'ltr'}>
      <header className="sticky top-0 z-40 bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border-b border-slate-200 dark:border-slate-800">
        <div className="max-w-6xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-gradient-to-tr from-indigo-600 to-pink-500 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-500/20">
              <svg className="w-5 h-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
            </div>
            <h1 className="text-xl font-black tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-pink-500">{t.title}</h1>
          </div>
          <div className="flex items-center gap-4">
            {isOffline && (
              <span className="text-xs font-bold bg-amber-500/10 text-amber-600 dark:text-amber-400 px-2 py-1 rounded-full flex items-center gap-1">
                <span className="w-2 h-2 bg-amber-500 rounded-full animate-pulse"></span>
                {t.offlineReady}
              </span>
            )}
            <button onClick={() => setLang(lang === 'en' ? 'he' : 'en')} className="px-3 py-1 text-sm font-semibold rounded-full border border-slate-200 dark:border-slate-700 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors">
              {t.languageName}
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-6 py-12">
        <div className="text-center mb-12">
          <h2 className="text-4xl md:text-5xl font-extrabold mb-4 tracking-tight">{t.subtitle}</h2>
          <div className="flex flex-col items-center gap-4">
            <p className="text-slate-500 dark:text-slate-400 max-w-2xl text-lg">
              {lang === 'en' ? 'Effortlessly transform monochromatic images into full-color photos instantly.' : 'הפוך תמונות שחור-לבן לצבעוניות באופן מיידי.'}
            </p>
            <div className="flex items-center gap-3">
              <span className="text-sm font-bold opacity-50 uppercase tracking-widest">{t.tryExample}</span>
              <div className="flex gap-2">
                {EXAMPLE_IMAGES.map((ex, i) => (
                  <button 
                    key={i} 
                    onClick={() => loadExample(ex)}
                    className="w-12 h-12 rounded-xl overflow-hidden border-2 border-slate-200 dark:border-slate-800 hover:border-indigo-500 transition-all shadow-sm"
                  >
                    <img src={ex.url} alt="Example" className="w-full h-full object-cover" />
                  </button>
                ))}
              </div>
            </div>
          </div>
        </div>

        <AdPlaceholder label={t.adPlaceholder} />

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-1 space-y-6">
            <div className="bg-white dark:bg-slate-900 p-6 rounded-3xl shadow-xl border border-slate-200 dark:border-slate-800">
              <label className="block text-sm font-bold text-slate-700 dark:text-slate-300 mb-2">{t.targetFolder}</label>
              <input type="text" value={targetLabel} onChange={(e) => setTargetLabel(e.target.value)} placeholder={t.targetFolderPlaceholder} className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all" />
              <div className="mt-8 space-y-3">
                <button onClick={exportAll} disabled={images.filter(i => i.status === 'completed').length === 0} className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-300 dark:disabled:bg-slate-800 text-white font-bold rounded-2xl shadow-lg transition-all flex items-center justify-center gap-2">
                  <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                  {t.downloadAll}
                </button>
                <button onClick={() => setImages([])} className="w-full py-3 text-slate-500 dark:text-slate-400 text-sm font-semibold hover:text-red-500 transition-colors">{t.clearBtn}</button>
              </div>
            </div>
          </div>

          <div className="lg:col-span-2 space-y-6">
            <div 
              onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
              onDragEnter={(e) => { e.preventDefault(); setIsDragging(true); }}
              onDragLeave={(e) => { e.preventDefault(); setIsDragging(false); }}
              onDrop={(e) => { e.preventDefault(); setIsDragging(false); handleFiles(e.dataTransfer.files); }}
              onClick={() => fileInputRef.current?.click()}
              className={`relative group bg-white dark:bg-slate-900 border-2 border-dashed rounded-3xl p-12 text-center cursor-pointer transition-all ${isDragging ? 'border-indigo-500 scale-[1.01] bg-indigo-50/50' : 'border-slate-300 dark:border-slate-800 hover:border-indigo-500'}`}
            >
              {isDragging && <div className="absolute inset-0 z-10 bg-indigo-600/90 flex flex-col items-center justify-center text-white p-6 animate-in fade-in zoom-in-95 duration-200"><h3 className="text-3xl font-black">{t.dropNow}</h3></div>}
              <input type="file" multiple accept="image/*" className="hidden" ref={fileInputRef} onChange={(e) => handleFiles(e.target.files)} />
              <div className="w-16 h-16 bg-indigo-50 dark:bg-slate-800 rounded-full flex items-center justify-center mx-auto mb-4"><svg className="w-8 h-8 text-indigo-600" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg></div>
              <h3 className="text-xl font-bold mb-1">{t.dropzoneTitle}</h3>
              <p className="text-slate-500 text-sm">{t.dropzoneSub}</p>
            </div>

            {images.length > 0 && currentlyProcessing && (
              <div className="bg-white dark:bg-slate-900 p-4 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm animate-in slide-in-from-top duration-300">
                <div className="flex items-center justify-between mb-2">
                  <span className="text-sm font-bold text-indigo-600 dark:text-indigo-400">{t.processing}</span>
                  <span className="text-sm font-black">{progressPercent}%</span>
                </div>
                <div className="w-full h-3 bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
                  <div className="h-full bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500 transition-all duration-500 ease-out relative" style={{ width: `${progressPercent}%` }}>
                    <div className="absolute inset-0 bg-white/20 animate-[shimmer_2s_infinite] skew-x-12 translate-x-[-100%]"></div>
                  </div>
                </div>
              </div>
            )}

            {images.length > 0 && (
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
                {images.map((img, idx) => (
                  <ImageCard key={img.id} item={img} t={t} onRemove={(id) => setImages(prev => prev.filter(i => i.id !== id))} onSelect={() => setSelectedIndex(idx)} onShare={shareSingle} />
                ))}
              </div>
            )}
          </div>
        </div>
      </main>

      {selectedImage && (
        <div ref={modalRef} className="fixed inset-0 z-[60] flex flex-col bg-slate-950 animate-in fade-in duration-300 overflow-hidden select-none" onClick={closeOverlay}>
          <div className="h-20 px-6 flex items-center justify-between border-b border-white/10 bg-slate-900/50 backdrop-blur z-[70]" onClick={e => e.stopPropagation()}>
            <div className="flex items-center gap-4">
               <button onClick={closeOverlay} className="p-2 hover:bg-white/10 rounded-full transition-colors text-white" aria-label={t.close}>
                 <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
               </button>
               <div className="flex flex-col">
                 <span className="text-white font-bold text-sm sm:text-base truncate max-w-[120px] sm:max-w-xs">{selectedImage.file.name}</span>
                 <span className="text-indigo-400 text-[10px] uppercase tracking-widest font-black">
                   {t.imageCount.replace('{current}', String((selectedIndex || 0) + 1)).replace('{total}', String(images.length))}
                 </span>
               </div>
            </div>

            <div className="flex items-center gap-3">
              <div className="hidden sm:flex items-center gap-1 mr-4">
                 <button onClick={() => navigate(-1)} className="p-2 hover:bg-white/10 text-white rounded-lg"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg></button>
                 <button onClick={() => navigate(1)} className="p-2 hover:bg-white/10 text-white rounded-lg"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg></button>
              </div>
              <div className="hidden lg:flex items-center gap-3 bg-white/5 px-4 py-2 rounded-2xl border border-white/10">
                <input type="range" min="1" max="8" step="0.1" value={zoomLevel} onChange={(e) => {
                  const next = parseFloat(e.target.value);
                  setZoomLevel(next);
                  if (next === 1) setPanOffset({ x: 0, y: 0 });
                }} className="w-24 sm:w-32 accent-indigo-500 h-1 rounded-full cursor-pointer" />
              </div>
              <div className="flex items-center gap-2">
                <button onClick={toggleFullScreen} className="p-2.5 bg-white/5 hover:bg-white/15 text-white rounded-xl border border-white/10 transition-all">
                  {isFullScreen ? <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg> : <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" /></svg>}
                </button>
                <button onClick={resetView} className="hidden md:block px-4 py-2.5 bg-white/5 hover:bg-white/15 text-white/70 text-[10px] font-black rounded-xl border border-white/10 uppercase tracking-widest transition-all">{t.resetView}</button>
                <div className="w-px h-6 bg-white/20 mx-1"></div>
                <button onClick={() => exportSingle(selectedImage)} disabled={!selectedImage.resultUrl} className="flex items-center gap-2 px-5 py-2.5 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-700 text-white rounded-xl font-black text-xs uppercase tracking-tight transition-all">
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                  {t.export}
                </button>
              </div>
            </div>
          </div>

          <div 
            className={`flex-1 overflow-hidden bg-slate-950 cursor-move relative flex items-center justify-center ${isPanning ? 'cursor-grabbing' : ''}`} 
            onMouseDown={onMouseDown} onMouseMove={onMouseMove} onMouseUp={onMouseUp} onMouseLeave={onMouseUp}
            onWheel={onWheel} onDoubleClick={onImageDoubleClick} onClick={e => e.stopPropagation()}
          >
            <div 
              className="relative w-full max-w-4xl max-h-[80vh] aspect-auto flex items-center justify-center transition-transform duration-[50ms] ease-out will-change-transform"
              style={{ transform: `translate(${panOffset.x}px, ${panOffset.y}px) scale(${zoomLevel})` }}
            >
              {/* Comparison Slider Container */}
              <div className="relative w-full h-full flex items-center justify-center rounded-2xl overflow-hidden shadow-2xl border border-white/10 bg-black">
                {/* Before Image (Base) */}
                <img src={selectedImage.previewUrl} alt="Before" className="max-w-full max-h-[80vh] object-contain pointer-events-none" />

                {/* After Image (Clipped) */}
                {selectedImage.resultUrl && (
                  <div 
                    className="absolute inset-0 pointer-events-none overflow-hidden" 
                    style={{ width: `${sliderPos}%` }}
                  >
                    <img src={selectedImage.resultUrl} alt="After" className="absolute top-0 left-0 w-full h-full max-w-none object-contain pointer-events-none" style={{ width: 'calc(100% * ' + (100/sliderPos) + ')' }} />
                  </div>
                )}

                {/* Slider Handle UI */}
                {selectedImage.resultUrl && (
                  <>
                    <div 
                      className="absolute top-0 bottom-0 w-1 bg-white shadow-[0_0_15px_rgba(0,0,0,0.5)] z-10 cursor-col-resize pointer-events-auto"
                      style={{ left: `${sliderPos}%` }}
                      onMouseDown={(e) => {
                        e.stopPropagation();
                        const onMove = (moveEvent: MouseEvent) => {
                          const rect = e.currentTarget.parentElement?.getBoundingClientRect();
                          if (rect) {
                            const next = ((moveEvent.clientX - rect.left) / rect.width) * 100;
                            setSliderPos(Math.min(Math.max(next, 0), 100));
                          }
                        };
                        const onEnd = () => {
                          window.removeEventListener('mousemove', onMove);
                          window.removeEventListener('mouseup', onEnd);
                        };
                        window.addEventListener('mousemove', onMove);
                        window.addEventListener('mouseup', onEnd);
                      }}
                    >
                      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-10 h-10 bg-white rounded-full shadow-xl flex items-center justify-center ring-4 ring-black/20">
                        <svg className="w-6 h-6 text-slate-900" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M8 7l-5 5m0 0l5 5m-5-5h18m-5-10l5 5m0 0l-5 5" /></svg>
                      </div>
                    </div>
                    {/* Labels */}
                    <div className="absolute top-4 left-4 z-20 bg-black/60 backdrop-blur-md px-3 py-1 rounded-lg border border-white/20 text-[10px] font-black uppercase text-white tracking-widest">{t.original}</div>
                    <div className="absolute top-4 right-4 z-20 bg-indigo-600/80 backdrop-blur-md px-3 py-1 rounded-lg border border-white/20 text-[10px] font-black uppercase text-white tracking-widest">{t.result}</div>
                  </>
                )}

                {/* Loading State */}
                {!selectedImage.resultUrl && selectedImage.status === 'processing' && (
                  <div className="absolute inset-0 bg-black/40 backdrop-blur-sm flex flex-col items-center justify-center">
                    <div className="w-12 h-12 border-4 border-white/20 border-t-indigo-500 rounded-full animate-spin"></div>
                    <span className="mt-4 text-white text-xs font-bold uppercase tracking-widest">{t.processing}</span>
                  </div>
                )}
              </div>
            </div>
          </div>

          <div className="absolute bottom-6 left-1/2 -translate-x-1/2 pointer-events-none">
             <span className="text-white/40 text-[9px] font-bold uppercase tracking-[0.3em] bg-black/20 px-6 py-2.5 rounded-full backdrop-blur-md border border-white/5">
               {t.compareHint}
             </span>
          </div>
        </div>
      )}

      <footer className="py-12 border-t border-slate-200 dark:border-slate-800 text-center text-slate-400 text-sm">
        <p>© {new Date().getFullYear()} ChromaRestore AI. All Rights Reserved.</p>
        <p className="mt-2 opacity-50">{lang === 'en' ? 'Powered by Google Gemini Flash-Image' : 'מופעל ע"י Google Gemini Flash-Image'}</p>
      </footer>

      <style>{`
        @keyframes shimmer {
          0% { transform: translateX(-100%) skewX(-12deg); }
          100% { transform: translateX(200%) skewX(-12deg); }
        }
        input[type=range] { -webkit-appearance: none; background: rgba(255,255,255,0.1); }
        input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; height: 16px; width: 16px; border-radius: 50%; background: #6366f1; cursor: pointer; border: 2px solid white; box-shadow: 0 0 10px rgba(99, 102, 241, 0.5); }
        :fullscreen { background-color: #020617; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Language, ImageItem } from './types';
import { translations } from './i18n';
import { colorizeImage, fileToBase64 } from './services/geminiService';
import { ImageCard } from './components/ImageCard';
import { AdPlaceholder } from './components/AdPlaceholder';

const EXAMPLE_IMAGES = [
  { name: 'Landscape.jpg', url: 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?q=80&w=800&auto=format&fit=crop&grayscale=true' },
  { name: 'Portrait.jpg', url: 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?q=80&w=800&auto=format&fit=crop&grayscale=true' },
  { name: 'Vintage.jpg', url: 'https://images.unsplash.com/photo-1533158307587-828f0a76ef46?q=80&w=800&auto=format&fit=crop&grayscale=true' }
];

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('he');
  const [images, setImages] = useState<ImageItem[]>([]);
  const [targetLabel, setTargetLabel] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [isDragging, setIsDragging] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const [zoomLevel, setZoomLevel] = useState(1);
  const [panOffset, setPanOffset] = useState({ x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  const [isFullScreen, setIsFullScreen] = useState(false);
  const [sliderPos, setSliderPos] = useState(50);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const modalRef = useRef<HTMLDivElement>(null);
  const lastMousePos = useRef({ x: 0, y: 0 });
  const velocity = useRef({ x: 0, y: 0 });
  const lastTimestamp = useRef(0);
  const animationFrameId = useRef<number | null>(null);

  const t = translations[lang];
  const isRtl = lang === 'he';

  const selectedImage = selectedIndex !== null ? images[selectedIndex] : null;

  useEffect(() => {
    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const processNextPending = useCallback(async () => {
    const nextItem = images.find(img => img.status === 'pending');
    if (!nextItem || isProcessing) return;

    setIsProcessing(true);
    setImages(prev => prev.map(img => 
      img.id === nextItem.id ? { ...img, status: 'processing' } : img
    ));

    try {
      const base64 = await fileToBase64(nextItem.file);
      const resultUrl = await colorizeImage(base64, nextItem.file.type);
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'completed', resultUrl } : img
      ));
    } catch (err) {
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'error', error: String(err) } : img
      ));
    } finally {
      setIsProcessing(false);
    }
  }, [images, isProcessing]);

  useEffect(() => {
    processNextPending();
  }, [images, processNextPending]);

  const handleFiles = (files: FileList | null) => {
    if (!files) return;
    const newImages: ImageItem[] = Array.from(files).map(file => ({
      id: Math.random().toString(36).substr(2, 9),
      file,
      previewUrl: URL.createObjectURL(file),
      status: 'pending'
    }));
    setImages(prev => [...prev, ...newImages]);
  };

  const loadExample = async (example: typeof EXAMPLE_IMAGES[0]) => {
    try {
      const response = await fetch(example.url);
      const blob = await response.blob();
      const file = new File([blob], example.name, { type: 'image/jpeg' });
      const newImage: ImageItem = {
        id: Math.random().toString(36).substr(2, 9),
        file,
        previewUrl: URL.createObjectURL(file),
        status: 'pending'
      };
      setImages(prev => [...prev, newImage]);
    } catch (err) {
      console.error("Failed to load example", err);
    }
  };

  const adjustZoom = useCallback((delta: number) => {
    setZoomLevel(prev => {
      const next = Math.min(Math.max(prev + delta, 1), 8);
      if (next === 1) setPanOffset({ x: 0, y: 0 });
      return next;
    });
  }, []);

  const resetView = useCallback(() => {
    if (animationFrameId.current) cancelAnimationFrame(animationFrameId.current);
    setZoomLevel(1);
    setPanOffset({ x: 0, y: 0 });
    setSliderPos(50);
    velocity.current = { x: 0, y: 0 };
  }, []);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      modalRef.current?.requestFullscreen().catch(err => {
        console.error(`Error attempting to enable full-screen mode: ${err.message}`);
      });
      setIsFullScreen(true);
    } else {
      document.exitFullscreen();
      setIsFullScreen(false);
    }
  };

  useEffect(() => {
    const onFsChange = () => setIsFullScreen(!!document.fullscreenElement);
    document.addEventListener('fullscreenchange', onFsChange);
    return () => document.removeEventListener('fullscreenchange', onFsChange);
  }, []);

  const startInertia = useCallback(() => {
    const step = () => {
      setPanOffset(prev => ({
        x: prev.x + velocity.current.x * 12,
        y: prev.y + velocity.current.y * 12
      }));
      velocity.current.x *= 0.92;
      velocity.current.y *= 0.92;

      if (Math.abs(velocity.current.x) > 0.05 || Math.abs(velocity.current.y) > 0.05) {
        animationFrameId.current = requestAnimationFrame(step);
      } else {
        velocity.current = { x: 0, y: 0 };
        animationFrameId.current = null;
      }
    };
    animationFrameId.current = requestAnimationFrame(step);
  }, []);

  const onMouseDown = (e: React.MouseEvent) => {
    if (zoomLevel > 1) {
      if (animationFrameId.current) cancelAnimationFrame(animationFrameId.current);
      setIsPanning(true);
      lastMousePos.current = { x: e.clientX, y: e.clientY };
      lastTimestamp.current = performance.now();
      velocity.current = { x: 0, y: 0 };
    }
  };

  const onMouseMove = (e: React.MouseEvent) => {
    if (isPanning && zoomLevel > 1) {
      const now = performance.now();
      const dt = now - lastTimestamp.current;
      const dx = e.clientX - lastMousePos.current.x;
      const dy = e.clientY - lastMousePos.current.y;

      if (dt > 0) velocity.current = { x: dx / dt, y: dy / dt };

      setPanOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
      lastMousePos.current = { x: e.clientX, y: e.clientY };
      lastTimestamp.current = now;
    }
  };

  const onMouseUp = () => {
    if (isPanning) {
      setIsPanning(false);
      startInertia();
    }
  };

  const onWheel = (e: React.WheelEvent) => {
    e.stopPropagation();
    const delta = e.deltaY > 0 ? -0.2 : 0.2;
    adjustZoom(delta);
  };

  const onImageDoubleClick = () => {
    if (zoomLevel > 1) resetView();
    else adjustZoom(1.5);
  };

  const closeOverlay = useCallback(() => {
    setSelectedIndex(null);
    resetView();
    if (document.fullscreenElement) document.exitFullscreen();
  }, [resetView]);

  const navigate = useCallback((dir: number) => {
    if (selectedIndex === null) return;
    const next = (selectedIndex + dir + images.length) % images.length;
    setSelectedIndex(next);
    resetView();
  }, [selectedIndex, images.length, resetView]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (selectedIndex === null) return;
      if (e.key === '+' || e.key === '=') adjustZoom(0.5);
      else if (e.key === '-' || e.key === '_') adjustZoom(-0.5);
      else if (e.key === '0') resetView();
      else if (e.key === 'f' || e.key === 'F') toggleFullScreen();
      else if (e.key === 'ArrowRight') isRtl ? navigate(-1) : navigate(1);
      else if (e.key === 'ArrowLeft') isRtl ? navigate(1) : navigate(-1);
      else if (e.key === 'Escape') closeOverlay();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [selectedIndex, adjustZoom, closeOverlay, navigate, resetView, isRtl]);

  const exportSingle = (img: ImageItem) => {
    if (!img.resultUrl) return;
    const finalPrefix = targetLabel.trim() || 'colorized';
    const link = document.createElement('a');
    link.href = img.resultUrl;
    link.download = `${finalPrefix}_${img.file.name}`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const exportAll = () => {
    const completedImages = images.filter(img => img.status === 'completed' && img.resultUrl);
    if (completedImages.length === 0) return;
    if (window.confirm(`${t.confirmDownload} (${completedImages.length} images)`)) {
      completedImages.forEach((img, idx) => {
        setTimeout(() => exportSingle(img), idx * 250);
      });
    }
  };

  const shareSingle = async (img: ImageItem) => {
    if (!img.resultUrl) return;
    try {
      if (navigator.share) {
        await navigator.share({ 
          title: t.title, 
          text: t.shareTitle, 
          url: img.resultUrl // Share the colorized image data URL directly
        });
      } else {
        throw new Error('Share API not supported');
      }
    } catch (err) {
      console.warn("Sharing failed, falling back to clipboard", err);
      try {
        await navigator.clipboard.writeText(img.resultUrl);
        alert(isRtl ? 'קישור התמונה הועתק ללוח!' : 'Image link copied to clipboard!');
      } catch (copyErr) {
        console.error('Clipboard copy failed', copyErr);
      }
    }
  };

  const totalInBatch = images.length;
  const processedCount = images.filter(img => img.status === 'completed' || img.status === 'error').length;
  const progressPercent = totalInBatch > 0 ? Math.round((processedCount / totalInBatch) * 100) : 0;
  const currentlyProcessing = images.some(img => img.status === 'processing' || img.status === 'pending');

  return (
    <div className={`min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 font-sans ${isRtl ? 'rtl' : 'ltr'}`} dir={isRtl ? 'rtl' : 'ltr'}>
      <header className="sticky top-0 z-40 bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border-b border-slate-200 dark:border-slate-800">
        <div className="max-w-6xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-gradient-to-tr from-indigo-600 to-pink-500 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-500/20">
              <svg className="w-5 h-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
            </div>
            <h1 className="text-xl font-black tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-pink-500">{t.title}</h1>
          </div>
          <div className="flex items-center gap-4">
            {isOffline && (
              <span className="text-xs font-bold bg-amber-500/10 text-amber-600 dark:text-amber-400 px-2 py-1 rounded-full flex items-center gap-1">
                <span className="w-2 h-2 bg-amber-500 rounded-full animate-pulse"></span>
                {t.offlineReady}
              </span>
            )}
            <button onClick={() => setLang(lang === 'en' ? 'he' : 'en')} className="px-3 py-1 text-sm font-semibold rounded-full border border-slate-200 dark:border-slate-700 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors">
              {t.languageName}
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-6 py-12">
        <div className="text-center mb-12">
          <h2 className="text-4xl md:text-5xl font-extrabold mb-4 tracking-tight">{t.subtitle}</h2>
          <div className="flex flex-col items-center gap-4">
            <p className="text-slate-500 dark:text-slate-400 max-w-2xl text-lg">
              {lang === 'en' ? 'Effortlessly transform monochromatic images into full-color photos instantly.' : 'הפוך תמונות שחור-לבן לצבעוניות באופן מיידי.'}
            </p>
            <div className="flex items-center gap-3">
              <span className="text-sm font-bold opacity-50 uppercase tracking-widest">{t.tryExample}</span>
              <div className="flex gap-2">
                {EXAMPLE_IMAGES.map((ex, i) => (
                  <button 
                    key={i} 
                    onClick={() => loadExample(ex)}
                    className="w-12 h-12 rounded-xl overflow-hidden border-2 border-slate-200 dark:border-slate-800 hover:border-indigo-500 transition-all shadow-sm"
                  >
                    <img src={ex.url} alt="Example" className="w-full h-full object-cover" />
                  </button>
                ))}
              </div>
            </div>
          </div>
        </div>

        <AdPlaceholder label={t.adPlaceholder} />

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-1 space-y-6">
            <div className="bg-white dark:bg-slate-900 p-6 rounded-3xl shadow-xl border border-slate-200 dark:border-slate-800">
              <label className="block text-sm font-bold text-slate-700 dark:text-slate-300 mb-2">{t.targetFolder}</label>
              <input type="text" value={targetLabel} onChange={(e) => setTargetLabel(e.target.value)} placeholder={t.targetFolderPlaceholder} className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all" />
              <div className="mt-8 space-y-3">
                <button onClick={exportAll} disabled={images.filter(i => i.status === 'completed').length === 0} className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-300 dark:disabled:bg-slate-800 text-white font-bold rounded-2xl shadow-lg transition-all flex items-center justify-center gap-2">
                  <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                  {t.downloadAll}
                </button>
                <button onClick={() => setImages([])} className="w-full py-3 text-slate-500 dark:text-slate-400 text-sm font-semibold hover:text-red-500 transition-colors">{t.clearBtn}</button>
              </div>
            </div>
          </div>

          <div className="lg:col-span-2 space-y-6">
            <div 
              onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
              onDragEnter={(e) => { e.preventDefault(); setIsDragging(true); }}
              onDragLeave={(e) => { e.preventDefault(); setIsDragging(false); }}
              onDrop={(e) => { e.preventDefault(); setIsDragging(false); handleFiles(e.dataTransfer.files); }}
              onClick={() => fileInputRef.current?.click()}
              className={`relative group bg-white dark:bg-slate-900 border-2 border-dashed rounded-3xl p-12 text-center cursor-pointer transition-all ${isDragging ? 'border-indigo-500 scale-[1.01] bg-indigo-50/50' : 'border-slate-300 dark:border-slate-800 hover:border-indigo-500'}`}
            >
              {isDragging && <div className="absolute inset-0 z-10 bg-indigo-600/90 flex flex-col items-center justify-center text-white p-6 animate-in fade-in zoom-in-95 duration-200"><h3 className="text-3xl font-black">{t.dropNow}</h3></div>}
              <input type="file" multiple accept="image/*" className="hidden" ref={fileInputRef} onChange={(e) => handleFiles(e.target.files)} />
              <div className="w-16 h-16 bg-indigo-50 dark:bg-slate-800 rounded-full flex items-center justify-center mx-auto mb-4"><svg className="w-8 h-8 text-indigo-600" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg></div>
              <h3 className="text-xl font-bold mb-1">{t.dropzoneTitle}</h3>
              <p className="text-slate-500 text-sm">{t.dropzoneSub}</p>
            </div>

            {images.length > 0 && currentlyProcessing && (
              <div className="bg-white dark:bg-slate-900 p-4 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm animate-in slide-in-from-top duration-300">
                <div className="flex items-center justify-between mb-2">
                  <span className="text-sm font-bold text-indigo-600 dark:text-indigo-400">{t.processing}</span>
                  <span className="text-sm font-black">{progressPercent}%</span>
                </div>
                <div className="w-full h-3 bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
                  <div className="h-full bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500 transition-all duration-500 ease-out relative" style={{ width: `${progressPercent}%` }}>
                    <div className="absolute inset-0 bg-white/20 animate-[shimmer_2s_infinite] skew-x-12 translate-x-[-100%]"></div>
                  </div>
                </div>
              </div>
            )}

            {images.length > 0 && (
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
                {images.map((img, idx) => (
                  <ImageCard key={img.id} item={img} t={t} onRemove={(id) => setImages(prev => prev.filter(i => i.id !== id))} onSelect={() => setSelectedIndex(idx)} onShare={shareSingle} />
                ))}
              </div>
            )}
          </div>
        </div>
      </main>

      {selectedImage && (
        <div ref={modalRef} className="fixed inset-0 z-[60] flex flex-col bg-slate-950 animate-in fade-in duration-300 overflow-hidden select-none" onClick={closeOverlay}>
          <div className="h-20 px-6 flex items-center justify-between border-b border-white/10 bg-slate-900/50 backdrop-blur z-[70]" onClick={e => e.stopPropagation()}>
            <div className="flex items-center gap-4">
               <button onClick={closeOverlay} className="p-2 hover:bg-white/10 rounded-full transition-colors text-white" aria-label={t.close}>
                 <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
               </button>
               <div className="flex flex-col">
                 <span className="text-white font-bold text-sm sm:text-base truncate max-w-[120px] sm:max-w-xs">{selectedImage.file.name}</span>
                 <span className="text-indigo-400 text-[10px] uppercase tracking-widest font-black">
                   {t.imageCount.replace('{current}', String((selectedIndex || 0) + 1)).replace('{total}', String(images.length))}
                 </span>
               </div>
            </div>

            <div className="flex items-center gap-3">
              <div className="hidden sm:flex items-center gap-1 mr-4">
                 <button onClick={() => navigate(-1)} className="p-2 hover:bg-white/10 text-white rounded-lg"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg></button>
                 <button onClick={() => navigate(1)} className="p-2 hover:bg-white/10 text-white rounded-lg"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg></button>
              </div>
              <div className="hidden lg:flex items-center gap-3 bg-white/5 px-4 py-2 rounded-2xl border border-white/10">
                <input type="range" min="1" max="8" step="0.1" value={zoomLevel} onChange={(e) => {
                  const next = parseFloat(e.target.value);
                  setZoomLevel(next);
                  if (next === 1) setPanOffset({ x: 0, y: 0 });
                }} className="w-24 sm:w-32 accent-indigo-500 h-1 rounded-full cursor-pointer" />
              </div>
              <div className="flex items-center gap-2">
                <button onClick={toggleFullScreen} className="p-2.5 bg-white/5 hover:bg-white/15 text-white rounded-xl border border-white/10 transition-all">
                  {isFullScreen ? <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg> : <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" /></svg>}
                </button>
                <button onClick={resetView} className="hidden md:block px-4 py-2.5 bg-white/5 hover:bg-white/15 text-white/70 text-[10px] font-black rounded-xl border border-white/10 uppercase tracking-widest transition-all">{t.resetView}</button>
                <div className="w-px h-6 bg-white/20 mx-1"></div>
                <button onClick={() => exportSingle(selectedImage)} disabled={!selectedImage.resultUrl} className="flex items-center gap-2 px-5 py-2.5 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-700 text-white rounded-xl font-black text-xs uppercase tracking-tight transition-all">
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                  {t.export}
                </button>
              </div>
            </div>
          </div>

          <div 
            className={`flex-1 overflow-hidden bg-slate-950 cursor-move relative flex items-center justify-center ${isPanning ? 'cursor-grabbing' : ''}`} 
            onMouseDown={onMouseDown} onMouseMove={onMouseMove} onMouseUp={onMouseUp} onMouseLeave={onMouseUp}
            onWheel={onWheel} onDoubleClick={onImageDoubleClick} onClick={e => e.stopPropagation()}
          >
            <div 
              className="relative w-full max-w-4xl max-h-[80vh] aspect-auto flex items-center justify-center transition-transform duration-[50ms] ease-out will-change-transform"
              style={{ transform: `translate(${panOffset.x}px, ${panOffset.y}px) scale(${zoomLevel})` }}
            >
              {/* Comparison Slider Container */}
              <div className="relative w-full h-full flex items-center justify-center rounded-2xl overflow-hidden shadow-2xl border border-white/10 bg-black">
                {/* Before Image (Base) */}
                <img src={selectedImage.previewUrl} alt="Before" className="max-w-full max-h-[80vh] object-contain pointer-events-none" />

                {/* After Image (Clipped) */}
                {selectedImage.resultUrl && (
                  <div 
                    className="absolute inset-0 pointer-events-none overflow-hidden" 
                    style={{ width: `${sliderPos}%` }}
                  >
                    <img src={selectedImage.resultUrl} alt="After" className="absolute top-0 left-0 w-full h-full max-w-none object-contain pointer-events-none" style={{ width: 'calc(100% * ' + (100/sliderPos) + ')' }} />
                  </div>
                )}

                {/* Slider Handle UI */}
                {selectedImage.resultUrl && (
                  <>
                    <div 
                      className="absolute top-0 bottom-0 w-1 bg-white shadow-[0_0_15px_rgba(0,0,0,0.5)] z-10 cursor-col-resize pointer-events-auto"
                      style={{ left: `${sliderPos}%` }}
                      onMouseDown={(e) => {
                        e.stopPropagation();
                        const onMove = (moveEvent: MouseEvent) => {
                          const rect = e.currentTarget.parentElement?.getBoundingClientRect();
                          if (rect) {
                            const next = ((moveEvent.clientX - rect.left) / rect.width) * 100;
                            setSliderPos(Math.min(Math.max(next, 0), 100));
                          }
                        };
                        const onEnd = () => {
                          window.removeEventListener('mousemove', onMove);
                          window.removeEventListener('mouseup', onEnd);
                        };
                        window.addEventListener('mousemove', onMove);
                        window.addEventListener('mouseup', onEnd);
                      }}
                    >
                      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-10 h-10 bg-white rounded-full shadow-xl flex items-center justify-center ring-4 ring-black/20">
                        <svg className="w-6 h-6 text-slate-900" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M8 7l-5 5m0 0l5 5m-5-5h18m-5-10l5 5m0 0l-5 5" /></svg>
                      </div>
                    </div>
                    {/* Labels */}
                    <div className="absolute top-4 left-4 z-20 bg-black/60 backdrop-blur-md px-3 py-1 rounded-lg border border-white/20 text-[10px] font-black uppercase text-white tracking-widest">{t.original}</div>
                    <div className="absolute top-4 right-4 z-20 bg-indigo-600/80 backdrop-blur-md px-3 py-1 rounded-lg border border-white/20 text-[10px] font-black uppercase text-white tracking-widest">{t.result}</div>
                  </>
                )}

                {/* Loading State */}
                {!selectedImage.resultUrl && selectedImage.status === 'processing' && (
                  <div className="absolute inset-0 bg-black/40 backdrop-blur-sm flex flex-col items-center justify-center">
                    <div className="w-12 h-12 border-4 border-white/20 border-t-indigo-500 rounded-full animate-spin"></div>
                    <span className="mt-4 text-white text-xs font-bold uppercase tracking-widest">{t.processing}</span>
                  </div>
                )}
              </div>
            </div>
          </div>

          <div className="absolute bottom-6 left-1/2 -translate-x-1/2 pointer-events-none">
             <span className="text-white/40 text-[9px] font-bold uppercase tracking-[0.3em] bg-black/20 px-6 py-2.5 rounded-full backdrop-blur-md border border-white/5">
               {t.compareHint}
             </span>
          </div>
        </div>
      )}

      <footer className="py-12 border-t border-slate-200 dark:border-slate-800 text-center text-slate-400 text-sm">
        <p>© {new Date().getFullYear()} ChromaRestore AI. All Rights Reserved.</p>
        <p className="mt-2 opacity-50">{lang === 'en' ? 'Powered by Google Gemini Flash-Image' : 'מופעל ע"י Google Gemini Flash-Image'}</p>
      </footer>

      <style>{`
        @keyframes shimmer {
          0% { transform: translateX(-100%) skewX(-12deg); }
          100% { transform: translateX(200%) skewX(-12deg); }
        }
        input[type=range] { -webkit-appearance: none; background: rgba(255,255,255,0.1); }
        input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; height: 16px; width: 16px; border-radius: 50%; background: #6366f1; cursor: pointer; border: 2px solid white; box-shadow: 0 0 10px rgba(99, 102, 241, 0.5); }
        :fullscreen { background-color: #020617; }
      `}</style>
    </div>
  );
};

export default App;

export type Language = 'en' | 'he';

export interface ImageItem {
  id: string;
  file: File;
  previewUrl: string;
  status: 'pending' | 'processing' | 'completed' | 'error';
  resultUrl?: string;
  error?: string;
}

export interface Translation {
  title: string;
  subtitle: string;
  dropzoneTitle: string;
  dropzoneSub: string;
  colorizeBtn: string;
  clearBtn: string;
  downloadAll: string;
  processing: string;
  completed: string;
  error: string;
  targetFolder: string;
  targetFolderPlaceholder: string;
  languageName: string;
  offlineReady: string;
  adPlaceholder: string;
  confirmDownload: string;
  dropNow: string;
  close: string;
  zoomIn: string;
  zoomOut: string;
  original: string;
  result: string;
  export: string;
  share: string;
  shareTitle: string;
  fullScreen: string;
  resetView: string;
  zoomLevel: string;
  imageCount: string;
  tryExample: string;
}

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Language, ImageItem } from './types';
import { translations } from './i18n';
import { colorizeImage, fileToBase64 } from './services/geminiService';
import { ImageCard } from './components/ImageCard';
import { AdPlaceholder } from './components/AdPlaceholder';

const EXAMPLE_IMAGES = [
  { name: 'Landscape.jpg', url: 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?q=80&w=800&auto=format&fit=crop&grayscale=true' },
  { name: 'Portrait.jpg', url: 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?q=80&w=800&auto=format&fit=crop&grayscale=true' },
  { name: 'Vintage.jpg', url: 'https://images.unsplash.com/photo-1533158307587-828f0a76ef46?q=80&w=800&auto=format&fit=crop&grayscale=true' }
];

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('he');
  const [images, setImages] = useState<ImageItem[]>([]);
  const [targetLabel, setTargetLabel] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [isDragging, setIsDragging] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const [zoomLevel, setZoomLevel] = useState(1);
  const [panOffset, setPanOffset] = useState({ x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  const [isFullScreen, setIsFullScreen] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const modalRef = useRef<HTMLDivElement>(null);
  const lastMousePos = useRef({ x: 0, y: 0 });
  const velocity = useRef({ x: 0, y: 0 });
  const lastTimestamp = useRef(0);
  const animationFrameId = useRef<number | null>(null);

  const t = translations[lang];
  const isRtl = lang === 'he';

  const selectedImage = selectedIndex !== null ? images[selectedIndex] : null;

  useEffect(() => {
    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const processNextPending = useCallback(async () => {
    const nextItem = images.find(img => img.status === 'pending');
    if (!nextItem || isProcessing) return;

    setIsProcessing(true);
    setImages(prev => prev.map(img => 
      img.id === nextItem.id ? { ...img, status: 'processing' } : img
    ));

    try {
      const base64 = await fileToBase64(nextItem.file);
      const resultUrl = await colorizeImage(base64, nextItem.file.type);
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'completed', resultUrl } : img
      ));
    } catch (err) {
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'error', error: String(err) } : img
      ));
    } finally {
      setIsProcessing(false);
    }
  }, [images, isProcessing]);

  useEffect(() => {
    processNextPending();
  }, [images, processNextPending]);

  const handleFiles = (files: FileList | null) => {
    if (!files) return;
    const newImages: ImageItem[] = Array.from(files).map(file => ({
      id: Math.random().toString(36).substr(2, 9),
      file,
      previewUrl: URL.createObjectURL(file),
      status: 'pending'
    }));
    setImages(prev => [...prev, ...newImages]);
  };

  const loadExample = async (example: typeof EXAMPLE_IMAGES[0]) => {
    try {
      const response = await fetch(example.url);
      const blob = await response.blob();
      const file = new File([blob], example.name, { type: 'image/jpeg' });
      const newImage: ImageItem = {
        id: Math.random().toString(36).substr(2, 9),
        file,
        previewUrl: URL.createObjectURL(file),
        status: 'pending'
      };
      setImages(prev => [...prev, newImage]);
    } catch (err) {
      console.error("Failed to load example", err);
    }
  };

  const adjustZoom = useCallback((delta: number) => {
    setZoomLevel(prev => {
      const next = Math.min(Math.max(prev + delta, 1), 8);
      if (next === 1) setPanOffset({ x: 0, y: 0 });
      return next;
    });
  }, []);

  const resetView = useCallback(() => {
    if (animationFrameId.current) cancelAnimationFrame(animationFrameId.current);
    setZoomLevel(1);
    setPanOffset({ x: 0, y: 0 });
    velocity.current = { x: 0, y: 0 };
  }, []);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      modalRef.current?.requestFullscreen().catch(err => {
        console.error(`Error attempting to enable full-screen mode: ${err.message}`);
      });
      setIsFullScreen(true);
    } else {
      document.exitFullscreen();
      setIsFullScreen(false);
    }
  };

  useEffect(() => {
    const onFsChange = () => setIsFullScreen(!!document.fullscreenElement);
    document.addEventListener('fullscreenchange', onFsChange);
    return () => document.removeEventListener('fullscreenchange', onFsChange);
  }, []);

  const startInertia = useCallback(() => {
    const step = () => {
      setPanOffset(prev => ({
        x: prev.x + velocity.current.x * 12,
        y: prev.y + velocity.current.y * 12
      }));
      velocity.current.x *= 0.92;
      velocity.current.y *= 0.92;

      if (Math.abs(velocity.current.x) > 0.05 || Math.abs(velocity.current.y) > 0.05) {
        animationFrameId.current = requestAnimationFrame(step);
      } else {
        velocity.current = { x: 0, y: 0 };
        animationFrameId.current = null;
      }
    };
    animationFrameId.current = requestAnimationFrame(step);
  }, []);

  const onMouseDown = (e: React.MouseEvent) => {
    if (zoomLevel > 1) {
      if (animationFrameId.current) cancelAnimationFrame(animationFrameId.current);
      setIsPanning(true);
      lastMousePos.current = { x: e.clientX, y: e.clientY };
      lastTimestamp.current = performance.now();
      velocity.current = { x: 0, y: 0 };
    }
  };

  const onMouseMove = (e: React.MouseEvent) => {
    if (isPanning && zoomLevel > 1) {
      const now = performance.now();
      const dt = now - lastTimestamp.current;
      const dx = e.clientX - lastMousePos.current.x;
      const dy = e.clientY - lastMousePos.current.y;

      if (dt > 0) velocity.current = { x: dx / dt, y: dy / dt };

      setPanOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
      lastMousePos.current = { x: e.clientX, y: e.clientY };
      lastTimestamp.current = now;
    }
  };

  const onMouseUp = () => {
    if (isPanning) {
      setIsPanning(false);
      startInertia();
    }
  };

  const onWheel = (e: React.WheelEvent) => {
    e.stopPropagation();
    const delta = e.deltaY > 0 ? -0.2 : 0.2;
    adjustZoom(delta);
  };

  const onImageDoubleClick = () => {
    if (zoomLevel > 1) resetView();
    else adjustZoom(1.5);
  };

  const closeOverlay = useCallback(() => {
    setSelectedIndex(null);
    resetView();
    if (document.fullscreenElement) document.exitFullscreen();
  }, [resetView]);

  const navigate = useCallback((dir: number) => {
    if (selectedIndex === null) return;
    const next = (selectedIndex + dir + images.length) % images.length;
    setSelectedIndex(next);
    resetView();
  }, [selectedIndex, images.length, resetView]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (selectedIndex === null) return;
      if (e.key === '+' || e.key === '=') adjustZoom(0.5);
      else if (e.key === '-' || e.key === '_') adjustZoom(-0.5);
      else if (e.key === '0') resetView();
      else if (e.key === 'f' || e.key === 'F') toggleFullScreen();
      else if (e.key === 'ArrowRight') isRtl ? navigate(-1) : navigate(1);
      else if (e.key === 'ArrowLeft') isRtl ? navigate(1) : navigate(-1);
      else if (e.key === 'Escape') closeOverlay();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [selectedIndex, adjustZoom, closeOverlay, navigate, resetView, isRtl]);

  const exportSingle = (img: ImageItem) => {
    if (!img.resultUrl) return;
    const finalPrefix = targetLabel.trim() || 'colorized';
    const link = document.createElement('a');
    link.href = img.resultUrl;
    link.download = `${finalPrefix}_${img.file.name}`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const exportAll = () => {
    const completedImages = images.filter(img => img.status === 'completed' && img.resultUrl);
    if (completedImages.length === 0) return;
    if (window.confirm(`${t.confirmDownload} (${completedImages.length} images)`)) {
      completedImages.forEach((img, idx) => {
        setTimeout(() => exportSingle(img), idx * 250);
      });
    }
  };

  const shareSingle = async (img: ImageItem) => {
    if (!img.resultUrl) return;
    try {
      if (navigator.share) {
        await navigator.share({ 
          title: t.title, 
          text: t.shareTitle, 
          url: img.resultUrl 
        });
      } else {
        throw new Error('Share API not supported');
      }
    } catch (err) {
      console.warn("Sharing failed, falling back to clipboard", err);
      try {
        await navigator.clipboard.writeText(img.resultUrl);
        alert(isRtl ? 'קישור התמונה הועתק ללוח!' : 'Image link copied to clipboard!');
      } catch (copyErr) {
        console.error('Clipboard copy failed', copyErr);
      }
    }
  };

  const totalInBatch = images.length;
  const processedCount = images.filter(img => img.status === 'completed' || img.status === 'error').length;
  const progressPercent = totalInBatch > 0 ? Math.round((processedCount / totalInBatch) * 100) : 0;
  const currentlyProcessing = images.some(img => img.status === 'processing' || img.status === 'pending');

  return (
    <div className={`min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 font-sans ${isRtl ? 'rtl' : 'ltr'}`} dir={isRtl ? 'rtl' : 'ltr'}>
      <header className="sticky top-0 z-40 bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border-b border-slate-200 dark:border-slate-800">
        <div className="max-w-6xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-gradient-to-tr from-indigo-600 to-pink-500 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-500/20">
              <svg className="w-5 h-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
            </div>
            <h1 className="text-xl font-black tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-pink-500">{t.title}</h1>
          </div>
          <div className="flex items-center gap-4">
            {isOffline && (
              <span className="text-xs font-bold bg-amber-500/10 text-amber-600 dark:text-amber-400 px-2 py-1 rounded-full flex items-center gap-1">
                <span className="w-2 h-2 bg-amber-500 rounded-full animate-pulse"></span>
                {t.offlineReady}
              </span>
            )}
            <button onClick={() => setLang(lang === 'en' ? 'he' : 'en')} className="px-3 py-1 text-sm font-semibold rounded-full border border-slate-200 dark:border-slate-700 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors">
              {t.languageName}
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-6 py-12">
        <div className="text-center mb-12">
          <h2 className="text-4xl md:text-5xl font-extrabold mb-4 tracking-tight">{t.subtitle}</h2>
          <div className="flex flex-col items-center gap-4">
            <p className="text-slate-500 dark:text-slate-400 max-w-2xl text-lg">
              {lang === 'en' ? 'Effortlessly transform monochromatic images into full-color photos instantly.' : 'הפוך תמונות שחור-לבן לצבעוניות באופן מיידי.'}
            </p>
            <div className="flex items-center gap-3">
              <span className="text-sm font-bold opacity-50 uppercase tracking-widest">{t.tryExample}</span>
              <div className="flex gap-2">
                {EXAMPLE_IMAGES.map((ex, i) => (
                  <button 
                    key={i} 
                    onClick={() => loadExample(ex)}
                    className="w-12 h-12 rounded-xl overflow-hidden border-2 border-slate-200 dark:border-slate-800 hover:border-indigo-500 transition-all shadow-sm"
                  >
                    <img src={ex.url} alt="Example" className="w-full h-full object-cover" />
                  </button>
                ))}
              </div>
            </div>
          </div>
        </div>

        <AdPlaceholder label={t.adPlaceholder} />

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-1 space-y-6">
            <div className="bg-white dark:bg-slate-900 p-6 rounded-3xl shadow-xl border border-slate-200 dark:border-slate-800">
              <label className="block text-sm font-bold text-slate-700 dark:text-slate-300 mb-2">{t.targetFolder}</label>
              <input type="text" value={targetLabel} onChange={(e) => setTargetLabel(e.target.value)} placeholder={t.targetFolderPlaceholder} className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all" />
              <div className="mt-8 space-y-3">
                <button onClick={exportAll} disabled={images.filter(i => i.status === 'completed').length === 0} className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-300 dark:disabled:bg-slate-800 text-white font-bold rounded-2xl shadow-lg transition-all flex items-center justify-center gap-2">
                  <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                  {t.downloadAll}
                </button>
                <button onClick={() => setImages([])} className="w-full py-3 text-slate-500 dark:text-slate-400 text-sm font-semibold hover:text-red-500 transition-colors">{t.clearBtn}</button>
              </div>
            </div>
          </div>

          <div className="lg:col-span-2 space-y-6">
            <div 
              onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
              onDragEnter={(e) => { e.preventDefault(); setIsDragging(true); }}
              onDragLeave={(e) => { e.preventDefault(); setIsDragging(false); }}
              onDrop={(e) => { e.preventDefault(); setIsDragging(false); handleFiles(e.dataTransfer.files); }}
              onClick={() => fileInputRef.current?.click()}
              className={`relative group bg-white dark:bg-slate-900 border-2 border-dashed rounded-3xl p-12 text-center cursor-pointer transition-all ${isDragging ? 'border-indigo-500 scale-[1.01] bg-indigo-50/50' : 'border-slate-300 dark:border-slate-800 hover:border-indigo-500'}`}
            >
              {isDragging && <div className="absolute inset-0 z-10 bg-indigo-600/90 flex flex-col items-center justify-center text-white p-6 animate-in fade-in zoom-in-95 duration-200"><h3 className="text-3xl font-black">{t.dropNow}</h3></div>}
              <input type="file" multiple accept="image/*" className="hidden" ref={fileInputRef} onChange={(e) => handleFiles(e.target.files)} />
              <div className="w-16 h-16 bg-indigo-50 dark:bg-slate-800 rounded-full flex items-center justify-center mx-auto mb-4"><svg className="w-8 h-8 text-indigo-600" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg></div>
              <h3 className="text-xl font-bold mb-1">{t.dropzoneTitle}</h3>
              <p className="text-slate-500 text-sm">{t.dropzoneSub}</p>
            </div>

            {images.length > 0 && currentlyProcessing && (
              <div className="bg-white dark:bg-slate-900 p-4 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm animate-in slide-in-from-top duration-300">
                <div className="flex items-center justify-between mb-2">
                  <span className="text-sm font-bold text-indigo-600 dark:text-indigo-400">{t.processing}</span>
                  <span className="text-sm font-black">{progressPercent}%</span>
                </div>
                <div className="w-full h-3 bg-slate-100 dark:bg-slate-800 rounded-full overflow-hidden">
                  <div className="h-full bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500 transition-all duration-500 ease-out relative" style={{ width: `${progressPercent}%` }}>
                    <div className="absolute inset-0 bg-white/20 animate-[shimmer_2s_infinite] skew-x-12 translate-x-[-100%]"></div>
                  </div>
                </div>
              </div>
            )}

            {images.length > 0 && (
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
                {images.map((img, idx) => (
                  <ImageCard key={img.id} item={img} t={t} onRemove={(id) => setImages(prev => prev.filter(i => i.id !== id))} onSelect={() => setSelectedIndex(idx)} onShare={shareSingle} />
                ))}
              </div>
            )}
          </div>
        </div>
      </main>

      {selectedImage && (
        <div ref={modalRef} className="fixed inset-0 z-[60] flex flex-col bg-slate-950 animate-in fade-in duration-300 overflow-hidden select-none" onClick={closeOverlay}>
          <div className="h-20 px-6 flex items-center justify-between border-b border-white/10 bg-slate-900/50 backdrop-blur z-[70]" onClick={e => e.stopPropagation()}>
            <div className="flex items-center gap-4">
               <button onClick={closeOverlay} className="p-2 hover:bg-white/10 rounded-full transition-colors text-white" aria-label={t.close}>
                 <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
               </button>
               <div className="flex flex-col">
                 <span className="text-white font-bold text-sm sm:text-base truncate max-w-[120px] sm:max-w-xs">{selectedImage.file.name}</span>
                 <span className="text-indigo-400 text-[10px] uppercase tracking-widest font-black">
                   {t.imageCount.replace('{current}', String((selectedIndex || 0) + 1)).replace('{total}', String(images.length))}
                 </span>
               </div>
            </div>

            <div className="flex items-center gap-3">
              <div className="hidden sm:flex items-center gap-1 mr-4">
                 <button onClick={() => navigate(-1)} className="p-2 hover:bg-white/10 text-white rounded-lg"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg></button>
                 <button onClick={() => navigate(1)} className="p-2 hover:bg-white/10 text-white rounded-lg"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg></button>
              </div>
              <div className="hidden lg:flex items-center gap-3 bg-white/5 px-4 py-2 rounded-2xl border border-white/10">
                <input type="range" min="1" max="8" step="0.1" value={zoomLevel} onChange={(e) => {
                  const next = parseFloat(e.target.value);
                  setZoomLevel(next);
                  if (next === 1) setPanOffset({ x: 0, y: 0 });
                }} className="w-24 sm:w-32 accent-indigo-500 h-1 rounded-full cursor-pointer" />
              </div>
              <div className="flex items-center gap-2">
                <button onClick={toggleFullScreen} className="p-2.5 bg-white/5 hover:bg-white/15 text-white rounded-xl border border-white/10 transition-all">
                  {isFullScreen ? <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg> : <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" /></svg>}
                </button>
                <button onClick={resetView} className="hidden md:block px-4 py-2.5 bg-white/5 hover:bg-white/15 text-white/70 text-[10px] font-black rounded-xl border border-white/10 uppercase tracking-widest transition-all">{t.resetView}</button>
                <div className="w-px h-6 bg-white/20 mx-1"></div>
                <button onClick={() => exportSingle(selectedImage)} disabled={!selectedImage.resultUrl} className="flex items-center gap-2 px-5 py-2.5 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-700 text-white rounded-xl font-black text-xs uppercase tracking-tight transition-all">
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                  {t.export}
                </button>
              </div>
            </div>
          </div>

          {/* Simple Side-by-Side View */}
          <div 
            className={`flex-1 overflow-hidden bg-slate-950 cursor-move relative flex items-center justify-center ${isPanning ? 'cursor-grabbing' : ''}`} 
            onMouseDown={onMouseDown} onMouseMove={onMouseMove} onMouseUp={onMouseUp} onMouseLeave={onMouseUp}
            onWheel={onWheel} onDoubleClick={onImageDoubleClick} onClick={e => e.stopPropagation()}
          >
            <div 
              className="flex flex-col lg:flex-row gap-4 h-full w-full max-w-7xl items-center justify-center p-8 transition-transform duration-[50ms] ease-out will-change-transform"
              style={{ transform: `translate(${panOffset.x}px, ${panOffset.y}px) scale(${zoomLevel})` }}
            >
              {/* Original Image */}
              <div className="relative w-full lg:w-1/2 aspect-auto bg-black/40 rounded-2xl overflow-hidden shadow-2xl border border-white/10 ring-1 ring-white/5 flex items-center justify-center min-h-[30vh]">
                <img src={selectedImage.previewUrl} alt="Original" className="max-w-full max-h-full object-contain pointer-events-none" />
                <div className="absolute top-4 left-4 bg-black/60 backdrop-blur-md px-3 py-1.5 rounded-xl border border-white/20 shadow-lg"><span className="text-white text-[10px] font-black uppercase tracking-widest">{t.original}</span></div>
              </div>

              {/* Colorized Image */}
              <div className="relative w-full lg:w-1/2 aspect-auto bg-black/40 rounded-2xl overflow-hidden shadow-2xl border border-white/10 ring-1 ring-white/5 flex items-center justify-center min-h-[30vh]">
                {selectedImage.resultUrl ? (
                  <img src={selectedImage.resultUrl} alt="Result" className="max-w-full max-h-full object-contain animate-in fade-in duration-700 pointer-events-none" />
                ) : (
                  <div className="h-full w-full flex flex-col items-center justify-center bg-slate-900/50">
                    <div className="w-12 h-12 border-[6px] border-indigo-500/20 border-t-indigo-500 rounded-full animate-spin"></div>
                    <span className="mt-4 text-white/40 text-xs font-bold uppercase tracking-widest">{t.processing}</span>
                  </div>
                )}
                <div className="absolute top-4 left-4 bg-indigo-600/80 backdrop-blur-md px-3 py-1.5 rounded-xl border border-white/20 shadow-lg"><span className="text-white text-[10px] font-black uppercase tracking-widest">{t.result}</span></div>
              </div>
            </div>
          </div>

          <div className="absolute bottom-6 left-1/2 -translate-x-1/2 pointer-events-none">
             <span className="text-white/40 text-[9px] font-bold uppercase tracking-[0.3em] bg-black/20 px-6 py-2.5 rounded-full backdrop-blur-md border border-white/5">
               {isRtl ? 'גרור להזזה • לחיצה כפולה לזום • גלגלת לשינוי גודל' : 'Drag to pan • Double click to zoom • Scroll to zoom'}
             </span>
          </div>
        </div>
      )}

      <footer className="py-12 border-t border-slate-200 dark:border-slate-800 text-center text-slate-400 text-sm">
        <p>© {new Date().getFullYear()} ChromaRestore AI. All Rights Reserved.</p>
        <p className="mt-2 opacity-50">{lang === 'en' ? 'Powered by Google Gemini Flash-Image' : 'מופעל ע"י Google Gemini Flash-Image'}</p>
      </footer>

      <style>{`
        @keyframes shimmer {
          0% { transform: translateX(-100%) skewX(-12deg); }
          100% { transform: translateX(200%) skewX(-12deg); }
        }
        input[type=range] { -webkit-appearance: none; background: rgba(255,255,255,0.1); }
        input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; height: 16px; width: 16px; border-radius: 50%; background: #6366f1; cursor: pointer; border: 2px solid white; box-shadow: 0 0 10px rgba(99, 102, 241, 0.5); }
        :fullscreen { background-color: #020617; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Language, ImageItem } from './types';
import { translations } from './i18n';
import { colorizeImage, fileToBase64 } from './services/geminiService';
import { ImageCard } from './components/ImageCard';
import { AdPlaceholder } from './components/AdPlaceholder';

const EXAMPLE_IMAGES = [
  { name: 'Landscape.jpg', url: 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?q=80&w=800&auto=format&fit=crop&grayscale=true' },
  { name: 'Portrait.jpg', url: 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?q=80&w=800&auto=format&fit=crop&grayscale=true' },
  { name: 'Vintage.jpg', url: 'https://images.unsplash.com/photo-1533158307587-828f0a76ef46?q=80&w=800&auto=format&fit=crop&grayscale=true' }
];

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('he');
  const [images, setImages] = useState<ImageItem[]>([]);
  const [targetLabel, setTargetLabel] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [isDragging, setIsDragging] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const [zoomLevel, setZoomLevel] = useState(1);
  const [panOffset, setPanOffset] = useState({ x: 0, y: 0 });
  const [isPanning, setIsPanning] = useState(false);
  const [isFullScreen, setIsFullScreen] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const modalRef = useRef<HTMLDivElement>(null);
  const lastMousePos = useRef({ x: 0, y: 0 });
  const velocity = useRef({ x: 0, y: 0 });
  const lastTimestamp = useRef(0);
  const animationFrameId = useRef<number | null>(null);

  const t = translations[lang];
  const isRtl = lang === 'he';

  const selectedImage = selectedIndex !== null ? images[selectedIndex] : null;

  useEffect(() => {
    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  const processNextPending = useCallback(async () => {
    const nextItem = images.find(img => img.status === 'pending');
    if (!nextItem || isProcessing) return;

    setIsProcessing(true);
    setImages(prev => prev.map(img => 
      img.id === nextItem.id ? { ...img, status: 'processing' } : img
    ));

    try {
      const base64 = await fileToBase64(nextItem.file);
      const resultUrl = await colorizeImage(base64, nextItem.file.type);
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'completed', resultUrl } : img
      ));
    } catch (err) {
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'error', error: String(err) } : img
      ));
    } finally {
      setIsProcessing(false);
    }
  }, [images, isProcessing]);

  useEffect(() => {
    processNextPending();
  }, [images, processNextPending]);

  const handleFiles = (files: FileList | null) => {
    if (!files) return;
    const newImages: ImageItem[] = Array.from(files).map(file => ({
      id: Math.random().toString(36).substr(2, 9),
      file,
      previewUrl: URL.createObjectURL(file),
      status: 'pending'
    }));
    setImages(prev => [...prev, ...newImages]);
  };

  const loadExample = async (example: typeof EXAMPLE_IMAGES[0]) => {
    try {
      const response = await fetch(example.url);
      const blob = await response.blob();
      const file = new File([blob], example.name, { type: 'image/jpeg' });
      const newImage: ImageItem = {
        id: Math.random().toString(36).substr(2, 9),
        file,
        previewUrl: URL.createObjectURL(file),
        status: 'pending'
      };
      setImages(prev => [...prev, newImage]);
    } catch (err) {
      console.error("Failed to load example", err);
    }
  };

  const adjustZoom = useCallback((delta: number) => {
    setZoomLevel(prev => {
      const next = Math.min(Math.max(prev + delta, 1), 8);
      if (next === 1) setPanOffset({ x: 0, y: 0 });
      return next;
    });
  }, []);

  const resetView = useCallback(() => {
    if (animationFrameId.current) cancelAnimationFrame(animationFrameId.current);
    setZoomLevel(1);
    setPanOffset({ x: 0, y: 0 });
    velocity.current = { x: 0, y: 0 };
  }, []);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      modalRef.current?.requestFullscreen().catch(err => {
        console.error(`Error attempting to enable full-screen mode: ${err.message}`);
      });
      setIsFullScreen(true);
    } else {
      document.exitFullscreen();
      setIsFullScreen(false);
    }
  };

  useEffect(() => {
    const onFsChange = () => setIsFullScreen(!!document.fullscreenElement);
    document.addEventListener('fullscreenchange', onFsChange);
    return () => document.removeEventListener('fullscreenchange', onFsChange);
  }, []);

  const startInertia = useCallback(() => {
    const step = () => {
      setPanOffset(prev => ({
        x: prev.x + velocity.current.x * 12,
        y: prev.y + velocity.current.y * 12
      }));
      velocity.current.x *= 0.92;
      velocity.current.y *= 0.92;

      if (Math.abs(velocity.current.x) > 0.05 || Math.abs(velocity.current.y) > 0.05) {
        animationFrameId.current = requestAnimationFrame(step);
      } else {
        velocity.current = { x: 0, y: 0 };
        animationFrameId.current = null;
      }
    };
    animationFrameId.current = requestAnimationFrame(step);
  }, []);

  const onMouseDown = (e: React.MouseEvent) => {
    if (zoomLevel > 1) {
      if (animationFrameId.current) cancelAnimationFrame(animationFrameId.current);
      setIsPanning(true);
      lastMousePos.current = { x: e.clientX, y: e.clientY };
      lastTimestamp.current = performance.now();
      velocity.current = { x: 0, y: 0 };
    }
  };

  const onMouseMove = (e: React.MouseEvent) => {
    if (isPanning && zoomLevel > 1) {
      const now = performance.now();
      const dt = now - lastTimestamp.current;
      const dx = e.clientX - lastMousePos.current.x;
      const dy = e.clientY - lastMousePos.current.y;

      if (dt > 0) velocity.current = { x: dx / dt, y: dy / dt };

      setPanOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
      lastMousePos.current = { x: e.clientX, y: e.clientY };
      lastTimestamp.current = now;
    }
  };

  const onMouseUp = () => {
    if (isPanning) {
      setIsPanning(false);
      startInertia();
    }
  };

  const onWheel = (e: React.WheelEvent) => {
    e.stopPropagation();
    const delta = e.deltaY > 0 ? -0.2 : 0.2;
    adjustZoom(delta);
  };

  const onImageDoubleClick = () => {
    if (zoomLevel > 1) resetView();
    else adjustZoom(1.5);
  };

  const closeOverlay = useCallback(() => {
    setSelectedIndex(null);
    resetView();
    if (document.fullscreenElement) document.exitFullscreen();
  }, [resetView]);

  const navigate = useCallback((dir: number) => {
    if (selectedIndex === null) return;
    const next = (selectedIndex + dir + images.length) % images.length;
    setSelectedIndex(next);
    resetView();
  }, [selectedIndex, images.length, resetView]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (selectedIndex === null) return;

      const isZoomIn = e.key === '+' || e.key === '=' || e.code === 'NumpadAdd';
      const isZoomOut = e.key === '-' || e.key === '_' || e.code === 'NumpadSubtract';
      const isReset = e.key === '0' || e.code === 'Digit0' || e.code === 'Numpad0';

      if (isZoomIn) {
        e.preventDefault();
        adjustZoom(0.5);
      } else if (isZoomOut) {
        e.preventDefault();
        adjustZoom(-0.5);
      } else if (isReset) {
        e.preventDefault();
        resetView();
      } else if (e.key === 'f' || e.key === 'F') {
        e.preventDefault();
        toggleFullScreen();
      } else if (e.key === 'ArrowRight') {
        e.preventDefault();
        isRtl ? navigate(-1) : navigate(1);
      } else if (e.key === 'ArrowLeft') {
        e.preventDefault();
        isRtl ? navigate(1) : navigate(-1);
      } else if (e.key === 'Escape') {
        e.preventDefault();
        closeOverlay();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [selectedIndex, adjustZoom, closeOverlay, navigate, resetView, isRtl]);

  const exportSingle = (img: ImageItem) => {
    if (!img.resultUrl) return;
    const finalPrefix = targetLabel.trim() || 'colorized';
    const link = document.createElement('a');
    link.href = img.resultUrl;
    link.download = `${finalPrefix}_${img.file.name}`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const exportAll = () => {
    const completedImages = images.filter(img => img.status === 'completed' && img.resultUrl);
    if (completedImages.length === 0) return;
    if (window.confirm(`${t.confirmDownload} (${completedImages.length} images)`)) {
      completedImages.forEach((img, idx) => {
        setTimeout(() => exportSingle(img), idx * 250);
      });
    }
  };

  const shareSingle = async (img: ImageItem) => {
    if (!img.resultUrl) return;
    try {
      if (navigator.share) {
        await navigator.share({ 
          title: t.title, 
          text: t.shareTitle, 
          url: img.resultUrl 
        });
      } else {
        throw new Error('Share API not supported');
      }
    } catch (err) {
      console.warn("Sharing failed, falling back to clipboard", err);
      try {
        await navigator.clipboard.writeText(img.resultUrl);
        alert(isRtl ? 'קישור התמונה הועתק ללוח!' : 'Image link copied to clipboard!');
      } catch (copyErr) {
        console.error('Clipboard copy failed', copyErr);
      }
    }
  };

  const totalInBatch = images.length;
  const processedCount = images.filter(img => img.status === 'completed' || img.status === 'error').length;
  const progressPercent = totalInBatch > 0 ? Math.round((processedCount / totalInBatch) * 100) : 0;
  const currentlyProcessing = images.some(img => img.status === 'processing' || img.status === 'pending');

  return (
    <div className={`min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 font-sans ${isRtl ? 'rtl' : 'ltr'}`} dir={isRtl ? 'rtl' : 'ltr'}>
      <header className="sticky top-0 z-40 bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border-b border-slate-200 dark:border-slate-800">
        <div className="max-w-6xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-gradient-to-tr from-indigo-600 to-pink-500 rounded-lg flex items-center justify-center shadow-lg shadow-indigo-500/20">
              <svg className="w-5 h-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
            </div>
            <h1 className="text-xl font-black tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-pink-500">{t.title}</h1>
          </div>
          <div className="flex items-center gap-4">
            {isOffline && (
              <span className="text-xs font-bold bg-amber-500/10 text-amber-600 dark:text-amber-400 px-2 py-1 rounded-full flex items-center gap-1">
                <span className="w-2 h-2 bg-amber-500 rounded-full animate-pulse"></span>
                {t.offlineReady}
              </span>
            )}
            <button onClick={() => setLang(lang === 'en' ? 'he' : 'en')} className="px-3 py-1 text-sm font-semibold rounded-full border border-slate-200 dark:border-slate-700 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors">
              {t.languageName}
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-6 py-12">
        <div className="text-center mb-12">
          <h2 className="text-4xl md:text-5xl font-extrabold mb-4 tracking-tight">{t.subtitle}</h2>
