              onClick={() => fileInputRef.current?.click()}
              className={`group border-2 border-dashed rounded-[2rem] p-12 text-center cursor-pointer transition-all duration-300 ${isDragging ? 'drag-pulsing' : 'border-slate-200 dark:border-slate-800 hover:border-indigo-400 bg-white dark:bg-slate-900'}`}
