              <div className={`w-14 h-14 bg-indigo-50 dark:bg-indigo-500/10 rounded-2xl flex items-center justify-center mx-auto mb-6 transition-transform group-hover:scale-110 ${isDragging ? 'scale-125' : ''}`}>
