import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Language, ImageItem } from './types';
import { translations } from './i18n';
import { processImageLocally, fileToBase64 } from './services/geminiService';
import { ImageCard } from './components/ImageCard';
import { AdPlaceholder } from './components/AdPlaceholder';

const AUTOCOMPLETE_SUGGESTIONS = ['Personal Photos', 'Family Heritage', 'Travel 2024', 'Work Projects', 'Client Deliverables'];

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('en');
  const [images, setImages] = useState<ImageItem[]>([]);
  const [targetLabel, setTargetLabel] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const [zoomLevel, setZoomLevel] = useState(1);
  const [panOffset, setPanOffset] = useState({ x: 0, y: 0 });

  const fileInputRef = useRef<HTMLInputElement>(null);
  const t = translations[lang];
  const isRtl = lang === 'he';

  const filteredImages = images.filter(img => 
    img.file.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const processNextPending = useCallback(async () => {
    const nextItem = images.find(img => img.status === 'pending');
    if (!nextItem || isProcessing) return;

    setIsProcessing(true);
    setImages(prev => prev.map(img => 
      img.id === nextItem.id ? { ...img, status: 'processing' } : img
    ));

    try {
      const base64 = await fileToBase64(nextItem.file);
      const resultUrl = await processImageLocally(base64, nextItem.file.type);
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'completed', resultUrl } : img
      ));
    } catch (err) {
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'error', error: String(err) } : img
      ));
    } finally {
      setIsProcessing(false);
    }
  }, [images, isProcessing]);

  useEffect(() => {
    processNextPending();
  }, [images, processNextPending]);

  const handleFiles = (files: FileList | null) => {
    if (!files) return;
    const newImages: ImageItem[] = Array.from(files).map(file => ({
      id: Math.random().toString(36).substr(2, 9),
      file,
      previewUrl: URL.createObjectURL(file),
      status: 'pending'
    }));
    setImages(prev => [...prev, ...newImages]);
  };

  const resetView = useCallback(() => {
    setZoomLevel(1);
    setPanOffset({ x: 0, y: 0 });
  }, []);

  const exportSingle = (img: ImageItem) => {
    if (!img.resultUrl) return;
    const prefix = targetLabel.trim() || 'colorized';
    const link = document.createElement('a');
    link.href = img.resultUrl;
    link.download = `${prefix}_${img.file.name}`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const exportFiltered = () => {
    if (filteredImages.length === 0) return;
    const prefix = targetLabel || 'export';
    filteredImages.forEach((img, idx) => {
      if (img.resultUrl) {
        setTimeout(() => {
          const link = document.createElement('a');
          link.href = img.resultUrl!;
          link.download = `${prefix}_${img.file.name}`;
          link.click();
        }, idx * 200);
      }
    });
  };

  return (
    <div className={`min-h-screen dark bg-slate-950 text-slate-100 font-sans lang-${lang} ${isRtl ? 'rtl' : 'ltr'}`} dir={isRtl ? 'rtl' : 'ltr'}>
      <header className="sticky top-0 z-40 bg-slate-900/80 backdrop-blur-xl border-b border-slate-800">
        <div className="max-w-6xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <span className="text-2xl">🎨</span>
            <h1 className="text-lg font-black tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-indigo-400 to-indigo-200">{t.title}</h1>
          </div>

          <div className="flex items-center gap-3">
            <select 
              value={lang} 
              onChange={(e) => setLang(e.target.value as Language)}
              className="bg-slate-800 border border-slate-700 rounded-xl px-3 py-1.5 text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-500 transition-all cursor-pointer text-white"
            >
              <option value="en">English</option>
              <option value="he">עברית</option>
              <option value="zh">中文</option>
              <option value="hi">हिन्दी</option>
              <option value="de">Deutsch</option>
              <option value="es">Español</option>
              <option value="fr">Français</option>
            </select>
          </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-6 py-12">
        <div className="text-center mb-12">
          <h2 className="text-3xl md:text-5xl font-extrabold mb-4 tracking-tight text-white">{t.subtitle}</h2>
          <p className="text-slate-400 max-w-xl mx-auto text-sm md:text-base font-medium">{t.offlineReady}</p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
          <aside className="lg:col-span-1 space-y-6">
            <div className="bg-slate-900 p-6 rounded-3xl shadow-xl border border-slate-800">
              <label className="block text-xs font-black uppercase tracking-widest text-slate-500 mb-3">{t.targetFolder}</label>
              <div className="relative">
                <input 
                  type="text" 
                  list="labels-list"
                  value={targetLabel} 
                  onChange={(e) => setTargetLabel(e.target.value)}
                  onDrop={(e) => { e.preventDefault(); setTargetLabel(e.dataTransfer.getData('text')); }}
                  placeholder={t.targetFolderPlaceholder} 
                  className="w-full pl-4 pr-10 py-3 bg-slate-950 border border-slate-800 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all text-sm font-medium text-white" 
                />
                <datalist id="labels-list">
                  {AUTOCOMPLETE_SUGGESTIONS.map(s => <option key={s} value={s} />)}
                </datalist>
                {targetLabel && (
                  <button onClick={() => setTargetLabel('')} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 hover:text-rose-500">
                    <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" /></svg>
                  </button>
                )}
              </div>
              <div className="mt-8 space-y-3">
                <button onClick={exportFiltered} disabled={filteredImages.length === 0} className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-800 text-white font-bold rounded-2xl shadow-lg shadow-indigo-500/10 transition-all flex items-center justify-center gap-2 text-sm">
                  {t.downloadAll}
                </button>
                <button onClick={() => setImages([])} className="w-full py-3 text-slate-500 hover:text-rose-500 text-xs font-bold uppercase tracking-widest transition-colors">{t.clearBtn}</button>
              </div>
            </div>

            <AdPlaceholder label={t.adPlaceholder} />
          </aside>

          <section className="lg:col-span-3 space-y-6">
            <div 
              onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
              onDragLeave={() => setIsDragging(false)}
              onDrop={(e) => { e.preventDefault(); setIsDragging(false); handleFiles(e.dataTransfer.files); }}
              onClick={() => fileInputRef.current?.click()}
              className={`group border-2 border-dashed rounded-[2rem] p-12 text-center cursor-pointer transition-all duration-300 ${isDragging ? 'drag-pulsing' : 'border-slate-800 hover:border-indigo-500 bg-slate-900'}`}
            >
              <input type="file" multiple accept="image/*" className="hidden" ref={fileInputRef} onChange={(e) => handleFiles(e.target.files)} />
              <div className={`w-14 h-14 bg-indigo-500/10 rounded-2xl flex items-center justify-center mx-auto mb-6 transition-transform group-hover:scale-110 ${isDragging ? 'scale-125' : ''}`}>
                <svg className="w-7 h-7 text-indigo-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>
              </div>
              <h3 className={`text-xl font-black mb-1 transition-all ${isDragging ? 'text-indigo-400 scale-110' : 'text-white'}`}>{t.dropzoneTitle}</h3>
              <p className="text-slate-500 text-xs font-bold uppercase tracking-widest">{t.dropzoneSub}</p>
            </div>

            {images.length > 0 && (
              <div className="flex flex-col md:flex-row gap-4 items-center">
                <div className="relative flex-1 w-full">
                  <input 
                    type="text" 
                    value={searchQuery} 
                    onChange={(e) => setSearchQuery(e.target.value)}
                    placeholder={t.searchPlaceholder}
                    className="w-full pl-11 pr-4 py-3 bg-slate-900 border border-slate-800 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm text-white" 
                  />
                  <svg className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 text-slate-600" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                </div>
                {searchQuery && (
                  <button onClick={exportFiltered} className="px-6 py-3 bg-indigo-500/10 text-indigo-400 rounded-2xl text-xs font-black uppercase tracking-widest hover:bg-indigo-500/20 transition-all">
                    {t.exportSearch}
                  </button>
                )}
              </div>
            )}

            <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-3 xl:grid-cols-4 gap-4 min-h-[400px]">
              {filteredImages.length > 0 ? (
                filteredImages.map((img, idx) => (
                  <ImageCard 
                    key={img.id} 
                    item={img} 
                    t={t} 
                    onRemove={(id) => setImages(prev => prev.filter(i => i.id !== id))} 
                    onSelect={() => setSelectedIndex(idx)} 
                    onShare={() => {}} 
                  />
                ))
              ) : searchQuery && (
                <div className="col-span-full flex flex-col items-center justify-center py-20 text-slate-700">
                  <span className="text-4xl mb-4">🔍</span>
                  <p className="text-xs font-black uppercase tracking-widest">{t.noResults}</p>
                </div>
              )}
            </div>
          </section>
        </div>
      </main>

      {selectedIndex !== null && images[selectedIndex] && (
        <div className="fixed inset-0 z-50 flex flex-col bg-slate-950 animate-in fade-in duration-300" onClick={() => setSelectedIndex(null)}>
          <div className="h-16 px-6 flex items-center justify-between bg-slate-900/50 backdrop-blur border-b border-white/5" onClick={e => e.stopPropagation()}>
            <span className="text-white text-xs font-bold truncate max-w-xs">{images[selectedIndex].file.name}</span>
            <div className="flex items-center gap-2">
              <button 
                onClick={(e) => { e.stopPropagation(); exportSingle(images[selectedIndex!]); }} 
                className="px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl text-[10px] font-black uppercase tracking-widest transition-all flex items-center gap-2"
              >
                <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                {t.export}
              </button>
              <button onClick={() => setSelectedIndex(null)} className="p-2 hover:bg-white/10 rounded-full text-white">
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>
          </div>
          <div className="flex-1 flex items-center justify-center p-8 overflow-hidden" onClick={e => e.stopPropagation()}>
            <img 
              src={images[selectedIndex].previewUrl} 
              alt="Preview" 
              className="max-w-full max-h-full object-contain rounded-2xl shadow-2xl transition-transform" 
              style={{ transform: `scale(${zoomLevel}) translate(${panOffset.x}px, ${panOffset.y}px)` }}
