            >
              <input type="file" multiple accept="image/*" className="hidden" ref={fileInputRef} onChange={(e) => handleFiles(e.target.files)} />
              <div className={`w-14 h-14 bg-indigo-500/10 rounded-2xl flex items-center justify-center mx-auto mb-6 transition-all group-hover:scale-110 ${isDragging ? 'scale-125 drag-content-pulsing' : ''}`}>
                <svg className="w-7 h-7 text-indigo-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>
              </div>
              <div className={isDragging ? 'drag-content-pulsing' : ''}>
                <h3 className={`text-xl font-black mb-1 transition-all ${isDragging ? 'text-indigo-400' : 'text-white'}`}>{t.dropzoneTitle}</h3>
                <p className="text-slate-500 text-xs font-bold uppercase tracking-widest">{t.dropzoneSub}</p>
              </div>
            </div>

            {images.length > 0 && (
              <div className="flex flex-col md:flex-row gap-4 items-center">
                <div className="relative flex-1 w-full">
                  <input 
                    type="text" 
                    value={searchQuery} 
                    onChange={(e) => setSearchQuery(e.target.value)}
                    placeholder={t.searchPlaceholder}
                    className="w-full pl-11 pr-4 py-3 bg-slate-900 border border-slate-800 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm text-white" 
                  />
                  <svg className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 text-slate-600" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                </div>
                {searchQuery && (
                  <button onClick={exportFiltered} className="px-6 py-3 bg-indigo-500/10 text-indigo-400 rounded-2xl text-xs font-black uppercase tracking-widest hover:bg-indigo-500/20 transition-all">
                    {t.exportSearch}
                  </button>
                )}
              </div>
            )}

            <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-3 xl:grid-cols-4 gap-4 min-h-[400px]">
              {filteredImages.length > 0 ? (
                filteredImages.map((img, idx) => (
                  <ImageCard 
                    key={img.id} 
                    item={img} 
                    t={t} 
                    onRemove={(id) => setImages(prev => prev.filter(i => i.id !== id))} 
                    onSelect={() => { setSelectedIndex(images.indexOf(img)); setShowOriginalInModal(false); }} 
                    onShare={() => {}} 
                  />
                ))
              ) : searchQuery && (
                <div className="col-span-full flex flex-col items-center justify-center py-20 text-slate-700">
                  <span className="text-4xl mb-4">🔍</span>
                  <p className="text-xs font-black uppercase tracking-widest">{t.noResults}</p>
                </div>
              )}
            </div>
          </section>
        </div>
      </main>

      {/* Enhanced Modal */}
      {selectedIndex !== null && images[selectedIndex] && (
        <div ref={modalRef} className="fixed inset-0 z-50 flex flex-col bg-slate-950 animate-in fade-in duration-300 overflow-hidden" onClick={() => setSelectedIndex(null)}>
          <div className="h-16 px-6 flex items-center justify-between bg-slate-900/50 backdrop-blur border-b border-white/5" onClick={e => e.stopPropagation()}>
            <div className="flex items-center gap-4">
              <span className="text-white text-xs font-bold truncate max-w-[120px] sm:max-w-xs">{images[selectedIndex].file.name}</span>
              <button 
                onClick={(e) => { e.stopPropagation(); toggleFullScreen(); }} 
                className="p-2 hover:bg-white/10 rounded-xl text-white transition-colors"
                title={t.fullScreen}
              >
                {isFullScreen ? (
                  <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                ) : (
                  <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" /></svg>
                )}
              </button>
            </div>

            <div className="flex items-center gap-2">
              {images[selectedIndex].resultUrl && (
                <button 
                  onClick={(e) => { e.stopPropagation(); setShowOriginalInModal(!showOriginalInModal); }} 
                  className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${showOriginalInModal ? 'bg-indigo-600 text-white' : 'bg-slate-800 text-slate-400'}`}
                >
                  {showOriginalInModal ? t.result : t.original}
                </button>
              )}
              <button 
                onClick={(e) => { e.stopPropagation(); exportSingle(images[selectedIndex!]); }} 
                disabled={!images[selectedIndex].resultUrl}
                className="px-4 py-2 bg-indigo-600 hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed text-white rounded-xl text-[10px] font-black uppercase tracking-widest transition-all flex items-center gap-2"
              >
                <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                {t.export}
              </button>
              <button onClick={() => setSelectedIndex(null)} className="p-2 hover:bg-white/10 rounded-full text-white">
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>
          </div>

          <div 
            className="flex-1 flex items-center justify-center p-8 overflow-hidden cursor-move" 
            onClick={e => e.stopPropagation()}
            onMouseMove={(e) => {
              if (e.buttons === 1 && zoomLevel > 1) {
                setPanOffset(prev => ({ x: prev.x + e.movementX, y: prev.y + e.movementY }));
              }
            }}
          >
            <div 
              className="relative transition-transform duration-75 ease-out"
              style={{ transform: `scale(${zoomLevel}) translate(${panOffset.x / zoomLevel}px, ${panOffset.y / zoomLevel}px)` }}
            >
              <img 
                src={showOriginalInModal || !images[selectedIndex].resultUrl ? images[selectedIndex].previewUrl : images[selectedIndex].resultUrl} 
                alt="Image" 
                className="max-w-full max-h-[70vh] object-contain rounded-2xl shadow-2xl pointer-events-none transition-all duration-300" 
              />
              {images[selectedIndex].status === 'processing' && (
                <div className="absolute inset-0 flex items-center justify-center bg-black/40 backdrop-blur-sm rounded-2xl">
                   <div className="w-12 h-12 border-4 border-indigo-500/20 border-t-indigo-500 rounded-full animate-spin"></div>
                </div>
              )}
            </div>
          </div>

          <div className="h-24 bg-slate-900/80 backdrop-blur-md flex flex-col items-center justify-center px-6 border-t border-white/5" onClick={e => e.stopPropagation()}>
            <div className="flex items-center gap-4 w-full max-w-md">
              <button onClick={() => setZoomLevel(prev => Math.max(prev - 0.2, 1))} className="p-2 text-white/70 hover:text-white">
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20 12H4" /></svg>
              </button>
              <div className="flex-1 relative flex items-center">
                <input 
                  type="range" 
                  min="1" 
                  max="5" 
                  step="0.1" 
                  value={zoomLevel} 
                  onChange={(e) => {
                    const val = parseFloat(e.target.value);
                    setZoomLevel(val);
                    if (val === 1) setPanOffset({ x: 0, y: 0 });
                  }}
                  className="w-full h-1.5 bg-white/10 rounded-lg appearance-none cursor-pointer accent-indigo-500"
                />
              </div>
              <button onClick={() => setZoomLevel(prev => Math.min(prev + 0.2, 5))} className="p-2 text-white/70 hover:text-white">
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6v6m0 0v6m0-6h6m-6 0H6" /></svg>
              </button>
            </div>
            <div className="mt-2 flex gap-4">
              <span className="text-[10px] font-black uppercase tracking-widest text-white/40">{t.zoomLevel}: {zoomLevel.toFixed(1)}x</span>
              <button onClick={resetView} className="text-[10px] font-black uppercase tracking-widest text-indigo-400 hover:text-indigo-300 transition-colors">
                {t.resetView}
              </button>
            </div>
          </div>
        </div>
      )}

      <footer className="py-12 border-t border-slate-800 text-center opacity-70">
        <p className="text-[10px] font-black uppercase tracking-[0.3em] mb-2">(C) Noam Gold AI 2026</p>
        <div className="flex items-center justify-center gap-2">
          <span className="text-[10px] font-bold text-slate-500">Send Feedback:</span>
          <a href="mailto:goldnoamai@gmail.com" className="text-[10px] font-black text-indigo-400 hover:text-indigo-300 transition-colors">goldnoamai@gmail.com</a>
        </div>
      </footer>
    </div>
  );
};

