  result: string;
  export: string;
  share: string;
  shareTitle: string;
  shareSuccess: string;
  fullScreen: string;
  resetView: string;
  zoomLevel: string;
  zoomIn: string;
  zoomOut: string;
  remove: string;
  search: string;
  imageCount: string;
  tryExample: string;
  searchPlaceholder: string;
