const CACHE_NAME = 'chroma-restore-v2';
const ASSETS = [
  './',
  './index.html',
  './index.css',
  './manifest.json',
  'https://cdnjs.cloudflare.com/ajax/libs/tailwindcss/2.2.19/tailwind.min.css'
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => cache.addAll(ASSETS))
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) => Promise.all(
      keys.map((key) => {
        if (key !== CACHE_NAME) return caches.delete(key);
      })
    ))
  );
});

self.addEventListener('fetch', (event) => {
  event.respondWith(
    caches.match(event.request).then((cached) => {
      return cached || fetch(event.request).catch(() => {
        if (event.request.mode === 'navigate') {
          return caches.match('./index.html');
        }
      });
    })
  );
});

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Language, ImageItem } from './types';
import { translations } from './i18n';
import { processImageWithGemini, fileToBase64 } from './services/geminiService';
import { ImageCard } from './components/ImageCard';
import { AdPlaceholder } from './components/AdPlaceholder';

const INITIAL_SUGGESTIONS = ['Personal Photos', 'Family Heritage', 'Travel 2024', 'Work Projects', 'Client Deliverables'];

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('en');
  const [images, setImages] = useState<ImageItem[]>([]);
  const [targetLabel, setTargetLabel] = useState('');
  const [usedLabels, setUsedLabels] = useState<string[]>(INITIAL_SUGGESTIONS);
  const [searchQuery, setSearchQuery] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const [zoomLevel, setZoomLevel] = useState(1);
  const [panOffset, setPanOffset] = useState({ x: 0, y: 0 });
  const [isFullScreen, setIsFullScreen] = useState(false);
  const [showOriginalInModal, setShowOriginalInModal] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const modalRef = useRef<HTMLDivElement>(null);
  const t = translations[lang];
  const isRtl = lang === 'he';

  const filteredImages = images.filter(img => 
    img.file.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const processNextPending = useCallback(async () => {
    const nextItem = images.find(img => img.status === 'pending');
    if (!nextItem || isProcessing) return;

    setIsProcessing(true);
    setImages(prev => prev.map(img => 
      img.id === nextItem.id ? { ...img, status: 'processing' } : img
    ));

    try {
      const base64 = await fileToBase64(nextItem.file);
      const resultUrl = await processImageWithGemini(base64, nextItem.file.type);
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'completed', resultUrl, destination: targetLabel } : img
      ));

      if (targetLabel.trim() && !usedLabels.includes(targetLabel.trim())) {
        setUsedLabels(prev => [targetLabel.trim(), ...prev].slice(0, 15));
      }
    } catch (err) {
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'error', error: String(err) } : img
      ));
    } finally {
      setIsProcessing(false);
    }
  }, [images, isProcessing, targetLabel, usedLabels]);

  useEffect(() => {
    processNextPending();
  }, [images, processNextPending]);

  const handleFiles = (files: FileList | null) => {
    if (!files) return;
    const newImages: ImageItem[] = Array.from(files).map(file => ({
      id: Math.random().toString(36).substr(2, 9),
      file,
      previewUrl: URL.createObjectURL(file),
      status: 'pending'
    }));
    setImages(prev => [...prev, ...newImages]);
  };

  const handleShare = (item: ImageItem) => {
    const url = item.resultUrl || item.previewUrl;
    navigator.clipboard.writeText(url).then(() => {
      alert(t.shareSuccess);
    });
  };

  const resetView = useCallback(() => {
    setZoomLevel(1);
    setPanOffset({ x: 0, y: 0 });
  }, []);

  const toggleFullScreen = useCallback(() => {
    if (!document.fullscreenElement) {
      modalRef.current?.requestFullscreen().catch(err => {
        console.error(`Error attempting to enable full-screen mode: ${err.message}`);
      });
      setIsFullScreen(true);
    } else {
      document.exitFullscreen();
      setIsFullScreen(false);
    }
  }, []);

  useEffect(() => {
    const onFsChange = () => setIsFullScreen(!!document.fullscreenElement);
    document.addEventListener('fullscreenchange', onFsChange);
    return () => document.removeEventListener('fullscreenchange', onFsChange);
  }, []);

  const handlePickFolder = async () => {
    if ('showDirectoryPicker' in window) {
      try {
        const handle = await (window as any).showDirectoryPicker();
        setTargetLabel(handle.name);
      } catch (e) {
        console.debug('Folder picker cancelled or failed', e);
      }
    } else {
      alert('Your browser does not support folder picking. Please type the name manually.');
    }
  };

  const exportSingle = (img: ImageItem) => {
    if (!img.resultUrl) return;
    const prefix = targetLabel.trim() || 'colorized';
    const link = document.createElement('a');
    link.href = img.resultUrl;
    link.download = `${prefix}_${img.file.name}`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const exportFiltered = () => {
    if (filteredImages.length === 0) return;
    const prefix = targetLabel || 'export';
    filteredImages.forEach((img, idx) => {
      if (img.resultUrl) {
        setTimeout(() => {
          const link = document.createElement('a');
          link.href = img.resultUrl!;
          link.download = `${prefix}_${img.file.name}`;
          link.click();
        }, idx * 200);
      }
    });
  };

  const handleKeyDown = useCallback((e: KeyboardEvent) => {
    if (selectedIndex === null) return;
    if (e.key === 'f' || e.key === 'F') { e.preventDefault(); toggleFullScreen(); }
    else if (e.key === '+' || e.key === '=') { e.preventDefault(); setZoomLevel(prev => Math.min(prev + 0.2, 5)); }
    else if (e.key === '-' || e.key === '_') { e.preventDefault(); setZoomLevel(prev => Math.max(prev - 0.2, 1)); }
    else if (e.key === '0') { e.preventDefault(); resetView(); }
    else if (e.key === 'Escape') {
      if (document.fullscreenElement) document.exitFullscreen();
      else setSelectedIndex(null);
    }
  }, [selectedIndex, toggleFullScreen, resetView]);

  useEffect(() => {
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleKeyDown]);

  return (
    <div className={`min-h-screen dark bg-slate-950 text-slate-100 font-sans lang-${lang} ${isRtl ? 'rtl' : 'ltr'}`} dir={isRtl ? 'rtl' : 'ltr'}>
      <header className="sticky top-0 z-40 bg-slate-900/90 backdrop-blur-xl border-b border-slate-800 shadow-2xl">
        <div className="max-w-6xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <span className="text-2xl drop-shadow-[0_0_10px_rgba(99,102,241,0.5)]" title={t.title}>🎨</span>
            <h1 className="text-lg font-black tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-indigo-400 to-indigo-200">{t.title}</h1>
          </div>
          <div className="flex items-center gap-3">
            <select 
              value={lang} 
              onChange={(e) => setLang(e.target.value as Language)}
              title={t.languageSelect}
              aria-label={t.languageSelect}
              className="bg-slate-800 border border-slate-700 rounded-xl px-3 py-1.5 text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-500 transition-all cursor-pointer text-slate-100"
            >
              <option value="en">English</option>
              <option value="he">עברית</option>
              <option value="zh">中文</option>
              <option value="hi">हिन्दी</option>
              <option value="de">Deutsch</option>
              <option value="es">Español</option>
              <option value="fr">Français</option>
            </select>
          </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-6 py-12">
        <div className="text-center mb-12">
          <h2 className="text-3xl md:text-5xl font-extrabold mb-4 tracking-tight text-white">{t.subtitle}</h2>
          <div className="flex items-center justify-center gap-2">
            <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
            <p className="text-slate-400 max-w-xl text-sm font-medium">{t.offlineReady}</p>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
          <aside className="lg:col-span-1 space-y-6">
            <div className="bg-slate-900 p-6 rounded-[2.5rem] shadow-2xl border border-slate-800">
              <label className="block text-[10px] font-black uppercase tracking-[0.2em] text-slate-500 mb-3 ml-1">{t.targetFolder}</label>
              <div 
                className="relative group"
                onDragOver={(e) => { e.preventDefault(); }}
                onDrop={(e) => { 
                  e.preventDefault(); 
                  const files = e.dataTransfer.items;
                  if (files && files[0] && files[0].kind === 'file') {
                    const entry = (files[0] as any).webkitGetAsEntry();
                    if (entry && entry.isDirectory) {
                      setTargetLabel(entry.name);
                    }
                  }
                }}
              >
                <input 
                  type="text" 
                  list="labels-list"
                  value={targetLabel} 
                  onChange={(e) => setTargetLabel(e.target.value)}
                  placeholder={t.targetFolderPlaceholder} 
                  className="w-full pl-4 pr-10 py-3.5 bg-slate-950 border border-slate-800 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all text-sm font-medium text-white placeholder:text-slate-700" 
                />
                <datalist id="labels-list">
                  {usedLabels.map(s => <option key={s} value={s} />)}
                </datalist>
                <button 
                  onClick={handlePickFolder}
                  title={t.pickFolder}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-600 hover:text-indigo-400 transition-colors"
                >
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z" /></svg>
                </button>
              </div>
              <div className="mt-8 space-y-3">
                <button 
                  onClick={exportFiltered} 
                  disabled={filteredImages.length === 0} 
                  className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-800 disabled:text-slate-500 disabled:opacity-50 text-white font-bold rounded-2xl shadow-xl transition-all flex items-center justify-center gap-2 text-sm"
                >
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                  {t.downloadAll}
                </button>
                <button 
                  onClick={() => setImages([])} 
                  className="w-full py-3 text-slate-500 hover:text-rose-400 text-[10px] font-black uppercase tracking-[0.2em] transition-colors"
                >
                  {t.clearBtn}
                </button>
              </div>
            </div>
            <AdPlaceholder label={t.adPlaceholder} />
          </aside>

          <section className="lg:col-span-3 space-y-6">
            <div 
              onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
              onDragLeave={() => setIsDragging(false)}
              onDrop={(e) => { e.preventDefault(); setIsDragging(false); handleFiles(e.dataTransfer.files); }}
              onClick={() => fileInputRef.current?.click()}
              className={`group border-2 border-dashed rounded-[3rem] p-14 text-center cursor-pointer transition-all duration-500 ${isDragging ? 'drag-pulsing' : 'border-slate-800 hover:border-indigo-500/50 bg-slate-900/50 hover:bg-slate-900'}`}
            >
              <input type="file" multiple accept="image/*" className="hidden" ref={fileInputRef} onChange={(e) => handleFiles(e.target.files)} />
              <div className={`w-16 h-16 bg-indigo-500/10 rounded-[1.5rem] flex items-center justify-center mx-auto mb-6 transition-all group-hover:scale-110 ${isDragging ? 'scale-125 drag-content-pulsing' : ''}`}>
                <svg className="w-8 h-8 text-indigo-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>
              </div>
              <h3 className="text-2xl font-black mb-1 text-white">{t.dropzoneTitle}</h3>
              <p className="text-slate-500 text-[10px] font-black uppercase tracking-[0.2em]">{t.dropzoneSub}</p>
            </div>

            {images.length > 0 && (
              <div className="relative">
                <input 
                  type="text" 
                  value={searchQuery} 
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder={t.searchPlaceholder}
                  className="w-full pl-11 pr-4 py-4 bg-slate-900 border border-slate-800 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm text-white" 
                />
                <svg className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 text-slate-600" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
              </div>
            )}

            <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-3 xl:grid-cols-4 gap-6">
              {filteredImages.map((img) => (
                <ImageCard 
                  key={img.id} 
                  item={img} 
                  t={t} 
                  onRemove={(id) => setImages(prev => prev.filter(i => i.id !== id))} 
                  onSelect={() => { setSelectedIndex(images.indexOf(img)); setShowOriginalInModal(false); }} 
                  onShare={handleShare} 
                />
              ))}
            </div>
          </section>
        </div>
      </main>

      {selectedIndex !== null && images[selectedIndex] && (
        <div ref={modalRef} className="fixed inset-0 z-50 flex flex-col bg-slate-950/95 backdrop-blur-3xl animate-in fade-in duration-500 overflow-hidden" onClick={() => setSelectedIndex(null)}>
          {/* Header Bar - Floating and Translucent */}
          <div className="absolute top-0 left-0 right-0 z-50 h-16 px-6 flex items-center justify-between bg-slate-900/40 backdrop-blur-md border-b border-white/5 transition-opacity hover:opacity-100 opacity-90" onClick={e => e.stopPropagation()}>
            <div className="flex items-center gap-3 truncate">
               <span className="text-white text-[10px] font-black uppercase tracking-wider truncate bg-slate-950/60 px-3 py-1.5 rounded-lg border border-white/10">{images[selectedIndex].file.name}</span>
               {isFullScreen && <span className="text-[10px] font-bold text-indigo-400 animate-pulse">FULLSCREEN MODE</span>}
            </div>
            <div className="flex items-center gap-3">
              {images[selectedIndex].resultUrl && (
                <button 
                  onClick={(e) => { e.stopPropagation(); setShowOriginalInModal(!showOriginalInModal); }} 
                  className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-[0.1em] transition-all border ${showOriginalInModal ? 'bg-indigo-600 text-white border-indigo-400' : 'bg-slate-800/80 text-slate-300 border-white/10 hover:bg-slate-700'}`}
                >
                  {showOriginalInModal ? t.result : t.original}
                </button>
              )}
              <button 
                onClick={(e) => { e.stopPropagation(); exportSingle(images[selectedIndex!]); }} 
                className="px-4 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl text-[10px] font-black uppercase tracking-[0.1em] disabled:opacity-50 transition-colors border border-indigo-400 shadow-lg"
                disabled={!images[selectedIndex].resultUrl}
              >
                {t.export}
              </button>
              <div className="w-px h-6 bg-white/10 mx-1"></div>
              <button onClick={() => setSelectedIndex(null)} className="p-2 text-slate-300 hover:text-rose-400 transition-colors">
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>
          </div>

          {/* Main Viewport */}
          <div className="flex-1 flex items-center justify-center p-4 md:p-12 overflow-hidden" onClick={e => e.stopPropagation()}>
            <div className="relative transition-transform duration-200 ease-out" style={{ transform: `scale(${zoomLevel}) translate(${panOffset.x / zoomLevel}px, ${panOffset.y / zoomLevel}px)` }}>
              <img 
                src={showOriginalInModal || !images[selectedIndex].resultUrl ? images[selectedIndex].previewUrl : images[selectedIndex].resultUrl} 
                alt="Preview" 
                className="max-w-full max-h-[85vh] object-contain rounded-2xl md:rounded-[2rem] shadow-[0_35px_60px_-15px_rgba(0,0,0,0.6)] border border-white/5" 
              />
            </div>
          </div>

          {/* Controls Island - Adapts for Fullscreen */}
          <div className={`absolute bottom-8 left-1/2 -translate-x-1/2 z-50 flex flex-col items-center gap-4 transition-all ${isFullScreen ? 'scale-110 drop-shadow-[0_0_30px_rgba(0,0,0,0.8)]' : ''}`} onClick={e => e.stopPropagation()}>
            <div className="bg-slate-900/70 backdrop-blur-xl border border-white/10 rounded-[2rem] px-6 py-4 flex items-center gap-6 shadow-2xl min-w-[320px] max-w-[90vw]">
              <button 
                onClick={() => setZoomLevel(prev => Math.max(prev - 0.2, 1))} 
                className="p-3 bg-slate-800/80 hover:bg-indigo-600/20 text-slate-300 hover:text-indigo-400 rounded-2xl border border-white/5 transition-all"
                title={t.zoomOut}
              >
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M20 12H4" /></svg>
              </button>

              <div className="flex-1 flex flex-col items-center gap-1">
                 <input 
                   type="range" 
                   min="1" 
                   max="5" 
                   step="0.05" 
                   value={zoomLevel} 
                   onChange={(e) => setZoomLevel(parseFloat(e.target.value))} 
                   className="w-full accent-indigo-500 h-1.5 rounded-full cursor-pointer opacity-80 hover:opacity-100 transition-opacity" 
                 />
                 <span className="text-[8px] font-black text-slate-500 uppercase tracking-widest">{t.zoomLevel}: {Math.round(zoomLevel * 100)}%</span>
              </div>

              <button 
                onClick={() => setZoomLevel(prev => Math.min(prev + 0.2, 5))} 
                className="p-3 bg-slate-800/80 hover:bg-indigo-600/20 text-slate-300 hover:text-indigo-400 rounded-2xl border border-white/5 transition-all"
                title={t.zoomIn}
              >
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 6v6m0 0v6m0-6h6m-6 0H6" /></svg>
              </button>

              <div className="w-px h-8 bg-white/10 hidden sm:block"></div>

              <button 
                onClick={toggleFullScreen}
                className={`p-3 rounded-2xl border border-white/5 transition-all hidden sm:block ${isFullScreen ? 'bg-indigo-600/40 text-indigo-200 border-indigo-500/30' : 'bg-slate-800/80 text-slate-300 hover:bg-slate-700'}`}
                title={t.fullScreen}
              >
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  {isFullScreen 
                    ? <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" />
                    : <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" />
                  }
                </svg>
              </button>
            </div>

            <button 
              onClick={resetView} 
              className="px-4 py-2 bg-slate-950/60 backdrop-blur-md border border-white/5 rounded-full text-[9px] font-black uppercase tracking-widest text-indigo-400 hover:text-indigo-300 transition-colors shadow-xl"
            >
              {t.resetView}
            </button>
          </div>
        </div>
      )}

      <footer className="py-16 text-center opacity-40">
        <p className="text-[10px] font-black uppercase tracking-[0.5em] mb-3">Restoration Engine powered by Gemini 2.5</p>
        <p className="text-[10px] font-black uppercase tracking-[0.3em] mb-4 text-indigo-400">(C) Noam Gold AI 2026</p>
      </footer>
    </div>
  );
};

export default App;

import React from 'react';
import { ImageItem, Translation } from '../types';

interface ImageCardProps {
  item: ImageItem;
  t: Translation;
  onRemove: (id: string) => void;
  onSelect: (item: ImageItem) => void;
  onShare: (item: ImageItem) => void;
}

export const ImageCard: React.FC<ImageCardProps> = ({ item, t, onRemove, onSelect, onShare }) => {
  const statusColors = {
    pending: 'bg-slate-600',
    processing: 'bg-indigo-400 animate-pulse',
    completed: 'bg-emerald-500',
    error: 'bg-rose-500'
  };

  const statusLabel = t[item.status as keyof Translation] || item.status;
  const errorTooltip = item.error ? `${t.error}: ${item.error}` : t.error;

  return (
    <div className="relative group bg-slate-900 rounded-2xl overflow-hidden shadow-sm hover:shadow-2xl hover:shadow-indigo-500/10 border border-slate-800 transition-all duration-300 ease-out hover:scale-[1.02]">
      <div 
        className="aspect-square relative overflow-hidden bg-slate-950 cursor-pointer"
        onClick={() => onSelect(item)}
      >
        <img 
          src={item.previewUrl} 
          alt={item.file.name} 
          className={`w-full h-full object-cover transition-all duration-700 ${item.status === 'processing' ? 'scale-110 blur-md opacity-40' : 'scale-100 blur-0'}`}
        />

        {item.status === 'processing' && (
          <div className="absolute inset-0 flex items-center justify-center bg-indigo-950/20 backdrop-blur-[2px]">
            <div className="w-10 h-10 border-4 border-indigo-500/20 border-t-indigo-500 rounded-full animate-spin"></div>
          </div>
        )}

        {/* Status Dot Badge (Top Corner) */}
        <div 
          className={`absolute top-3 right-3 w-3 h-3 rounded-full border-2 border-slate-900 shadow-xl z-20 ${statusColors[item.status]}`} 
          title={item.status === 'error' ? errorTooltip : statusLabel} 
        />

        {item.status === 'error' && (
          <div className="absolute inset-0 flex items-center justify-center bg-rose-500/20 backdrop-blur-[1px] p-4 text-center">
            <span 
              className="text-rose-400 text-[10px] font-black uppercase tracking-widest bg-slate-950/80 px-2 py-1 rounded-md shadow-lg cursor-help"
              title={errorTooltip}
            >
              {t.error}
            </span>
          </div>
        )}
      </div>

      <div className="p-3 flex items-center justify-between bg-slate-900">
        <div className="flex items-center gap-2 truncate max-w-[65%]">
          {/* Small Status Dot Badge next to filename */}
          <div 
            className={`w-2 h-2 rounded-full flex-shrink-0 ${statusColors[item.status]}`} 
            title={item.status === 'error' ? errorTooltip : statusLabel}
          />
          <p className="text-[10px] font-bold text-slate-400 truncate tracking-tight">
            {item.file.name}
          </p>
        </div>
        <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
          <button 
            onClick={(e) => { e.stopPropagation(); onShare(item); }} 
            className="p-1.5 hover:bg-indigo-500/20 text-indigo-400 rounded-lg transition-all"
            title={t.share}
            aria-label={t.share}
          >
            <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z" /></svg>
          </button>
          <button 
            onClick={(e) => { e.stopPropagation(); onRemove(item.id); }} 
            className="p-1.5 hover:bg-rose-500/20 text-rose-500 rounded-lg transition-all"
            title={t.remove}
            aria-label={t.remove}
          >
            <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Language, ImageItem } from './types';
import { translations } from './i18n';
import { processImageWithGemini, fileToBase64 } from './services/geminiService';
import { ImageCard } from './components/ImageCard';
import { AdPlaceholder } from './components/AdPlaceholder';

const INITIAL_SUGGESTIONS = ['Personal Photos', 'Family Heritage', 'Travel 2024', 'Work Projects', 'Client Deliverables'];

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('en');
  const [images, setImages] = useState<ImageItem[]>([]);
  const [targetLabel, setTargetLabel] = useState('');
  const [usedLabels, setUsedLabels] = useState<string[]>(INITIAL_SUGGESTIONS);
  const [searchQuery, setSearchQuery] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const [zoomLevel, setZoomLevel] = useState(1);
  const [panOffset, setPanOffset] = useState({ x: 0, y: 0 });
  const [isFullScreen, setIsFullScreen] = useState(false);
  const [showOriginalInModal, setShowOriginalInModal] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const modalRef = useRef<HTMLDivElement>(null);
  const t = translations[lang];
  const isRtl = lang === 'he';

  const filteredImages = images.filter(img => 
    img.file.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const processNextPending = useCallback(async () => {
    const nextItem = images.find(img => img.status === 'pending');
    if (!nextItem || isProcessing) return;

    setIsProcessing(true);
    setImages(prev => prev.map(img => 
      img.id === nextItem.id ? { ...img, status: 'processing', error: undefined } : img
    ));

    try {
      const base64 = await fileToBase64(nextItem.file);
      const resultUrl = await processImageWithGemini(base64, nextItem.file.type);
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'completed', resultUrl, destination: targetLabel } : img
      ));

      if (targetLabel.trim() && !usedLabels.includes(targetLabel.trim())) {
        setUsedLabels(prev => [targetLabel.trim(), ...prev].slice(0, 15));
      }
    } catch (err: any) {
      const errorMessage = err?.message || String(err);
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'error', error: errorMessage } : img
      ));
    } finally {
      setIsProcessing(false);
    }
  }, [images, isProcessing, targetLabel, usedLabels]);

  useEffect(() => {
    processNextPending();
  }, [images, processNextPending]);

  const handleFiles = (files: FileList | null) => {
    if (!files) return;
    const newImages: ImageItem[] = Array.from(files).map(file => ({
      id: Math.random().toString(36).substr(2, 9),
      file,
      previewUrl: URL.createObjectURL(file),
      status: 'pending'
    }));
    setImages(prev => [...prev, ...newImages]);
  };

  const handleShare = (item: ImageItem) => {
    const url = item.resultUrl || item.previewUrl;
    navigator.clipboard.writeText(url).then(() => {
      alert(t.shareSuccess);
    });
  };

  const resetView = useCallback(() => {
    setZoomLevel(1);
    setPanOffset({ x: 0, y: 0 });
  }, []);

  const handleWheel = useCallback((e: React.WheelEvent) => {
    if (selectedIndex === null) return;
    const delta = e.deltaY > 0 ? -0.1 : 0.1;
    setZoomLevel(prev => Math.min(Math.max(prev + delta, 1), 5));
  }, [selectedIndex]);

  const toggleFullScreen = useCallback(() => {
    if (!document.fullscreenElement) {
      modalRef.current?.requestFullscreen().catch(err => {
        console.error(`Error attempting to enable full-screen mode: ${err.message}`);
      });
      setIsFullScreen(true);
    } else {
      document.exitFullscreen();
      setIsFullScreen(false);
    }
  }, []);

  useEffect(() => {
    const onFsChange = () => setIsFullScreen(!!document.fullscreenElement);
    document.addEventListener('fullscreenchange', onFsChange);
    return () => document.removeEventListener('fullscreenchange', onFsChange);
  }, []);

  const handlePickFolder = async () => {
    if ('showDirectoryPicker' in window) {
      try {
        const handle = await (window as any).showDirectoryPicker();
        setTargetLabel(handle.name);
      } catch (e) {
        console.debug('Folder picker cancelled or failed', e);
      }
    } else {
      alert('Your browser does not support folder picking. Please type the name manually.');
    }
  };

  const exportSingle = (img: ImageItem) => {
    if (!img.resultUrl) return;
    const prefix = targetLabel.trim() || 'colorized';
    const link = document.createElement('a');
    link.href = img.resultUrl;
    link.download = `${prefix}_${img.file.name}`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const exportFiltered = () => {
    if (filteredImages.length === 0) return;
    const prefix = targetLabel || 'export';
    filteredImages.forEach((img, idx) => {
      if (img.resultUrl) {
        setTimeout(() => {
          const link = document.createElement('a');
          link.href = img.resultUrl!;
          link.download = `${prefix}_${img.file.name}`;
          link.click();
        }, idx * 200);
      }
    });
  };

  const handleKeyDown = useCallback((e: KeyboardEvent) => {
    if (selectedIndex === null) return;
    if (e.key === 'f' || e.key === 'F') { e.preventDefault(); toggleFullScreen(); }
    else if (e.key === '+' || e.key === '=') { e.preventDefault(); setZoomLevel(prev => Math.min(prev + 0.2, 5)); }
    else if (e.key === '-' || e.key === '_') { e.preventDefault(); setZoomLevel(prev => Math.max(prev - 0.2, 1)); }
    else if (e.key === '0') { e.preventDefault(); resetView(); }
    else if (e.key === 'Escape') {
      if (document.fullscreenElement) document.exitFullscreen();
      else setSelectedIndex(null);
    }
  }, [selectedIndex, toggleFullScreen, resetView]);

  useEffect(() => {
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleKeyDown]);

  return (
    <div className={`min-h-screen dark bg-slate-950 text-slate-100 font-sans lang-${lang} ${isRtl ? 'rtl' : 'ltr'}`} dir={isRtl ? 'rtl' : 'ltr'}>
      <header className="sticky top-0 z-40 bg-slate-900/90 backdrop-blur-xl border-b border-slate-800 shadow-2xl">
        <div className="max-w-6xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <span className="text-2xl drop-shadow-[0_0_10px_rgba(99,102,241,0.5)]" title={t.title}>🎨</span>
            <h1 className="text-lg font-black tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-indigo-400 to-indigo-200">{t.title}</h1>
          </div>
          <div className="flex items-center gap-3">
            <select 
              value={lang} 
              onChange={(e) => setLang(e.target.value as Language)}
              title={t.languageSelect}
              aria-label={t.languageSelect}
              className="bg-slate-800 border border-slate-700 rounded-xl px-3 py-1.5 text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-500 transition-all cursor-pointer text-slate-100"
            >
              <option value="en">English</option>
              <option value="he">עברית</option>
              <option value="zh">中文</option>
              <option value="hi">हिन्दी</option>
              <option value="de">Deutsch</option>
              <option value="es">Español</option>
              <option value="fr">Français</option>
            </select>
          </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-6 py-12">
        <div className="text-center mb-12">
          <h2 className="text-3xl md:text-5xl font-extrabold mb-4 tracking-tight text-white">{t.subtitle}</h2>
          <div className="flex items-center justify-center gap-2">
            <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
            <p className="text-slate-400 max-w-xl text-sm font-medium">{t.offlineReady}</p>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
          <aside className="lg:col-span-1 space-y-6">
            <div className="bg-slate-900 p-6 rounded-[2.5rem] shadow-2xl border border-slate-800">
              <label className="block text-[10px] font-black uppercase tracking-[0.2em] text-slate-500 mb-3 ml-1">{t.targetFolder}</label>
              <div 
                className="relative group"
                onDragOver={(e) => { e.preventDefault(); }}
                onDrop={(e) => { 
                  e.preventDefault(); 
                  const files = e.dataTransfer.items;
                  if (files && files[0] && files[0].kind === 'file') {
                    const entry = (files[0] as any).webkitGetAsEntry();
                    if (entry && entry.isDirectory) {
                      setTargetLabel(entry.name);
                    }
                  }
                }}
              >
                <input 
                  type="text" 
                  list="labels-list"
                  value={targetLabel} 
                  onChange={(e) => setTargetLabel(e.target.value)}
                  placeholder={t.targetFolderPlaceholder} 
                  className="w-full pl-4 pr-10 py-3.5 bg-slate-950 border border-slate-800 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all text-sm font-medium text-white placeholder:text-slate-700" 
                />
                <datalist id="labels-list">
                  {usedLabels.map(s => <option key={s} value={s} />)}
                </datalist>
                <button 
                  onClick={handlePickFolder}
                  title={t.pickFolder}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-600 hover:text-indigo-400 transition-colors"
                >
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z" /></svg>
                </button>
              </div>
              <div className="mt-8 space-y-3">
                <button 
                  onClick={exportFiltered} 
                  disabled={filteredImages.length === 0} 
                  className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-800 disabled:text-slate-500 disabled:opacity-50 text-white font-bold rounded-2xl shadow-xl transition-all flex items-center justify-center gap-2 text-sm"
                  title={t.downloadAll}
                >
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                  {t.downloadAll}
                </button>
                <button 
                  onClick={() => setImages([])} 
                  className="w-full py-3 text-slate-500 hover:text-rose-400 text-[10px] font-black uppercase tracking-[0.2em] transition-colors"
                  title={t.clearBtn}
                >
                  {t.clearBtn}
                </button>
              </div>
            </div>
            <AdPlaceholder label={t.adPlaceholder} />
          </aside>

          <section className="lg:col-span-3 space-y-6">
            <div 
              onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
              onDragLeave={() => setIsDragging(false)}
              onDrop={(e) => { e.preventDefault(); setIsDragging(false); handleFiles(e.dataTransfer.files); }}
              onClick={() => fileInputRef.current?.click()}
              className={`group border-2 border-dashed rounded-[3rem] p-14 text-center cursor-pointer transition-all duration-500 ${isDragging ? 'drag-pulsing' : 'border-slate-800 hover:border-indigo-500/50 bg-slate-900/50 hover:bg-slate-900'}`}
              title={t.dropzoneTitle}
            >
              <input type="file" multiple accept="image/*" className="hidden" ref={fileInputRef} onChange={(e) => handleFiles(e.target.files)} />
              <div className={`w-16 h-16 bg-indigo-500/10 rounded-[1.5rem] flex items-center justify-center mx-auto mb-6 transition-all group-hover:scale-110 ${isDragging ? 'scale-125 drag-content-pulsing' : ''}`}>
                <svg className="w-8 h-8 text-indigo-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>
              </div>
              <h3 className="text-2xl font-black mb-1 text-white">{t.dropzoneTitle}</h3>
              <p className="text-slate-500 text-[10px] font-black uppercase tracking-[0.2em]">{t.dropzoneSub}</p>
            </div>

            {images.length > 0 && (
              <div className="relative">
                <input 
                  type="text" 
                  value={searchQuery} 
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder={t.searchPlaceholder}
                  className="w-full pl-11 pr-4 py-4 bg-slate-900 border border-slate-800 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm text-white" 
                  title={t.search}
                />
                <svg className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 text-slate-600" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
              </div>
            )}

            <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-3 xl:grid-cols-4 gap-6">
              {filteredImages.map((img) => (
                <ImageCard 
                  key={img.id} 
                  item={img} 
                  t={t} 
                  onRemove={(id) => setImages(prev => prev.filter(i => i.id !== id))} 
                  onSelect={() => { setSelectedIndex(images.indexOf(img)); setShowOriginalInModal(false); resetView(); }} 
                  onShare={handleShare} 
                />
              ))}
            </div>
          </section>
        </div>
      </main>

      {selectedIndex !== null && images[selectedIndex] && (
        <div 
          ref={modalRef} 
          className="fixed inset-0 z-50 flex flex-col bg-slate-950/95 backdrop-blur-3xl animate-in fade-in duration-500 overflow-hidden" 
          onClick={() => setSelectedIndex(null)}
          onWheel={handleWheel}
        >
          {/* Header Bar - Floating and Translucent */}
          <div className="absolute top-0 left-0 right-0 z-50 h-16 px-6 flex items-center justify-between bg-slate-900/40 backdrop-blur-md border-b border-white/5 transition-opacity hover:opacity-100 opacity-90" onClick={e => e.stopPropagation()}>
            <div className="flex items-center gap-3 truncate">
               <span className="text-white text-[10px] font-black uppercase tracking-wider truncate bg-slate-950/60 px-3 py-1.5 rounded-lg border border-white/10">{images[selectedIndex].file.name}</span>
               {isFullScreen && <span className="text-[10px] font-bold text-indigo-400 animate-pulse">FULLSCREEN MODE</span>}
               {images[selectedIndex].status === 'error' && <span className="text-[10px] font-bold text-rose-400 bg-rose-500/10 px-2 py-1 rounded border border-rose-500/20" title={images[selectedIndex].error}>{t.error}</span>}
            </div>
            <div className="flex items-center gap-3">
              {images[selectedIndex].resultUrl && (
                <button 
                  onClick={(e) => { e.stopPropagation(); setShowOriginalInModal(!showOriginalInModal); }} 
                  className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-[0.1em] transition-all border ${showOriginalInModal ? 'bg-indigo-600 text-white border-indigo-400' : 'bg-slate-800/80 text-slate-300 border-white/10 hover:bg-slate-700'}`}
                  title={showOriginalInModal ? t.result : t.original}
                >
                  {showOriginalInModal ? t.result : t.original}
                </button>
              )}
              <button 
                onClick={(e) => { e.stopPropagation(); exportSingle(images[selectedIndex!]); }} 
                className="px-4 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl text-[10px] font-black uppercase tracking-[0.1em] disabled:opacity-50 transition-colors border border-indigo-400 shadow-lg"
                disabled={!images[selectedIndex].resultUrl}
                title={t.export}
              >
                {t.export}
              </button>
              <div className="w-px h-6 bg-white/10 mx-1"></div>
              <button 
                onClick={() => setSelectedIndex(null)} 
                className="p-2 text-slate-300 hover:text-rose-400 transition-colors"
                title={t.close}
              >
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>
          </div>

          {/* Main Viewport */}
          <div className="flex-1 flex items-center justify-center p-4 md:p-12 overflow-hidden" onClick={e => e.stopPropagation()}>
            <div className="relative transition-transform duration-200 ease-out cursor-zoom-in" style={{ transform: `scale(${zoomLevel}) translate(${panOffset.x / zoomLevel}px, ${panOffset.y / zoomLevel}px)` }}>
              <img 
                src={showOriginalInModal || !images[selectedIndex].resultUrl ? images[selectedIndex].previewUrl : images[selectedIndex].resultUrl} 
                alt="Preview" 
                className="max-w-full max-h-[85vh] object-contain rounded-2xl md:rounded-[2rem] shadow-[0_35px_60px_-15px_rgba(0,0,0,0.6)] border border-white/5" 
              />
              {images[selectedIndex].status === 'error' && (
                <div className="absolute inset-0 flex flex-col items-center justify-center bg-rose-950/40 backdrop-blur-sm rounded-2xl md:rounded-[2rem] p-6 text-center">
                   <div className="w-16 h-16 bg-rose-500/20 rounded-full flex items-center justify-center mb-4 border border-rose-500/40">
                      <svg className="w-8 h-8 text-rose-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                   </div>
                   <h4 className="text-xl font-black text-rose-400 mb-2 uppercase tracking-widest">{t.error}</h4>
                   <p className="text-slate-200 text-sm max-w-md bg-slate-900/80 p-4 rounded-xl border border-white/5 shadow-2xl font-mono break-words">
                     {images[selectedIndex].error || "An unknown error occurred during colorization."}
                   </p>
                </div>
              )}
            </div>
          </div>

          {/* Controls Island - Adapts for Fullscreen */}
          <div className={`absolute bottom-8 left-1/2 -translate-x-1/2 z-50 flex flex-col items-center gap-4 transition-all ${isFullScreen ? 'scale-110 drop-shadow-[0_0_30px_rgba(0,0,0,0.8)]' : ''}`} onClick={e => e.stopPropagation()}>
            <div className="bg-slate-900/70 backdrop-blur-xl border border-white/10 rounded-[2rem] px-6 py-4 flex items-center gap-6 shadow-2xl min-w-[320px] max-w-[90vw]">
              <button 
                onClick={() => setZoomLevel(prev => Math.max(prev - 0.2, 1))} 
                className="p-3 bg-slate-800/80 hover:bg-indigo-600/20 text-slate-300 hover:text-indigo-400 rounded-2xl border border-white/5 transition-all"
                title={t.zoomOut}
              >
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M20 12H4" /></svg>
              </button>

              <div className="flex-1 flex flex-col items-center gap-1">
                 <input 
                   type="range" 
                   min="1" 
                   max="5" 
                   step="0.05" 
                   value={zoomLevel} 
                   onChange={(e) => setZoomLevel(parseFloat(e.target.value))} 
                   className="w-full accent-indigo-500 h-1.5 rounded-full cursor-pointer opacity-80 hover:opacity-100 transition-opacity" 
                   title={t.zoomLevel}
                 />
                 <span className="text-[8px] font-black text-slate-500 uppercase tracking-widest">{t.zoomLevel}: {Math.round(zoomLevel * 100)}%</span>
              </div>

              <button 
                onClick={() => setZoomLevel(prev => Math.min(prev + 0.2, 5))} 
                className="p-3 bg-slate-800/80 hover:bg-indigo-600/20 text-slate-300 hover:text-indigo-400 rounded-2xl border border-white/5 transition-all"
                title={t.zoomIn}
              >
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 6v6m0 0v6m0-6h6m-6 0H6" /></svg>
              </button>

              <div className="w-px h-8 bg-white/10 hidden sm:block"></div>

              <button 
                onClick={toggleFullScreen}
                className={`p-3 rounded-2xl border border-white/5 transition-all hidden sm:block ${isFullScreen ? 'bg-indigo-600/40 text-indigo-200 border-indigo-500/30' : 'bg-slate-800/80 text-slate-300 hover:bg-slate-700'}`}
                title={t.fullScreen}
              >
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  {isFullScreen 
                    ? <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" />
                    : <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" />
                  }
                </svg>
              </button>
            </div>

            <button 
              onClick={resetView} 
              className="px-4 py-2 bg-slate-950/60 backdrop-blur-md border border-white/5 rounded-full text-[9px] font-black uppercase tracking-widest text-indigo-400 hover:text-indigo-300 transition-colors shadow-xl"
              title={t.resetView}
            >
              {t.resetView}
            </button>
          </div>
        </div>
      )}

      <footer className="py-16 text-center opacity-40">
        <p className="text-[10px] font-black uppercase tracking-[0.5em] mb-3">Restoration Engine powered by Gemini 2.5</p>
        <p className="text-[10px] font-black uppercase tracking-[0.3em] mb-4 text-indigo-400">(C) Noam Gold AI 2026</p>
      </footer>
    </div>
  );
};

export default App;

import React from 'react';
import { ImageItem, Translation } from '../types';

interface ImageCardProps {
  item: ImageItem;
  t: Translation;
  onRemove: (id: string) => void;
  onSelect: (item: ImageItem) => void;
  onShare: (item: ImageItem) => void;
}

export const ImageCard: React.FC<ImageCardProps> = ({ item, t, onRemove, onSelect, onShare }) => {
  const statusColors = {
    pending: 'bg-slate-600',
    processing: 'bg-indigo-400 animate-pulse',
    completed: 'bg-emerald-500',
    error: 'bg-rose-500'
  };

  const statusLabel = t[item.status as keyof Translation] || item.status;
  const errorTooltip = item.error ? `${t.error}: ${item.error}` : t.error;

  return (
    <div className="relative group bg-slate-900 rounded-2xl overflow-hidden shadow-sm hover:shadow-2xl hover:shadow-indigo-500/10 border border-slate-800 transition-all duration-300 ease-out hover:scale-[1.02]">
      <div 
        className="aspect-square relative overflow-hidden bg-slate-950 cursor-pointer"
        onClick={() => onSelect(item)}
      >
        <img 
          src={item.previewUrl} 
          alt={item.file.name} 
          className={`w-full h-full object-cover transition-all duration-700 ${item.status === 'processing' ? 'scale-110 blur-md opacity-40' : 'scale-100 blur-0'}`}
        />

        {item.status === 'processing' && (
          <div className="absolute inset-0 flex items-center justify-center bg-indigo-950/20 backdrop-blur-[2px]">
            <div className="w-10 h-10 border-4 border-indigo-500/20 border-t-indigo-500 rounded-full animate-spin"></div>
          </div>
        )}

        {/* Status Dot Badge (Top Corner) */}
        <div 
          className={`absolute top-3 right-3 w-3 h-3 rounded-full border-2 border-slate-900 shadow-xl z-20 ${statusColors[item.status]}`} 
          title={item.status === 'error' ? errorTooltip : statusLabel} 
        />

        {item.status === 'error' && (
          <div className="absolute inset-0 flex items-center justify-center bg-rose-500/20 backdrop-blur-[1px] p-4 text-center">
            <span 
              className="text-rose-400 text-[10px] font-black uppercase tracking-widest bg-slate-950/80 px-2 py-1 rounded-md shadow-lg cursor-help"
              title={errorTooltip}
            >
              {t.error}
            </span>
          </div>
        )}
      </div>

      <div className="p-3 flex items-center justify-between bg-slate-900">
        <div className="flex items-center gap-2 truncate max-w-[65%]">
          {/* Small Status Dot Badge next to filename */}
          <div 
            className={`w-2 h-2 rounded-full flex-shrink-0 ${statusColors[item.status]}`} 
            title={item.status === 'error' ? errorTooltip : statusLabel}
          />
          <p className="text-[10px] font-bold text-slate-400 truncate tracking-tight">
            {item.file.name}
          </p>
        </div>
        <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
          <button 
            onClick={(e) => { e.stopPropagation(); onShare(item); }} 
            className="p-1.5 hover:bg-indigo-500/20 text-indigo-400 rounded-lg transition-all"
            title={t.share}
            aria-label={t.share}
          >
            <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z" /></svg>
          </button>
          <button 
            onClick={(e) => { e.stopPropagation(); onRemove(item.id); }} 
            className="p-1.5 hover:bg-rose-500/20 text-rose-500 rounded-lg transition-all"
            title={t.remove}
            aria-label={t.remove}
          >
            <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Language, ImageItem } from './types';
import { translations } from './i18n';
import { processImageWithGemini, fileToBase64 } from './services/geminiService';
import { ImageCard } from './components/ImageCard';
import { AdPlaceholder } from './components/AdPlaceholder';

const INITIAL_SUGGESTIONS = ['Personal Photos', 'Family Heritage', 'Travel 2024', 'Work Projects', 'Client Deliverables'];

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('en');
  const [images, setImages] = useState<ImageItem[]>([]);
  const [targetLabel, setTargetLabel] = useState('');
  const [usedLabels, setUsedLabels] = useState<string[]>(INITIAL_SUGGESTIONS);
  const [searchQuery, setSearchQuery] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const [zoomLevel, setZoomLevel] = useState(1);
  const [panOffset, setPanOffset] = useState({ x: 0, y: 0 });
  const [isFullScreen, setIsFullScreen] = useState(false);
  const [showOriginalInModal, setShowOriginalInModal] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const modalRef = useRef<HTMLDivElement>(null);
  const t = translations[lang];
  const isRtl = lang === 'he';

  const filteredImages = images.filter(img => 
    img.file.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const processNextPending = useCallback(async () => {
    const nextItem = images.find(img => img.status === 'pending');
    if (!nextItem || isProcessing) return;

    setIsProcessing(true);
    setImages(prev => prev.map(img => 
      img.id === nextItem.id ? { ...img, status: 'processing', error: undefined } : img
    ));

    try {
      const base64 = await fileToBase64(nextItem.file);
      const resultUrl = await processImageWithGemini(base64, nextItem.file.type);
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'completed', resultUrl, destination: targetLabel } : img
      ));

      if (targetLabel.trim() && !usedLabels.includes(targetLabel.trim())) {
        setUsedLabels(prev => [targetLabel.trim(), ...prev].slice(0, 15));
      }
    } catch (err: any) {
      const errorMessage = err?.message || String(err);
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'error', error: errorMessage } : img
      ));
    } finally {
      setIsProcessing(false);
    }
  }, [images, isProcessing, targetLabel, usedLabels]);

  useEffect(() => {
    processNextPending();
  }, [images, processNextPending]);

  const handleFiles = (files: FileList | null) => {
    if (!files) return;
    const newImages: ImageItem[] = Array.from(files).map(file => ({
      id: Math.random().toString(36).substr(2, 9),
      file,
      previewUrl: URL.createObjectURL(file),
      status: 'pending'
    }));
    setImages(prev => [...prev, ...newImages]);
  };

  const handleShare = (item: ImageItem) => {
    const url = item.resultUrl || item.previewUrl;
    navigator.clipboard.writeText(url).then(() => {
      alert(t.shareSuccess);
    });
  };

  const resetView = useCallback(() => {
    setZoomLevel(1);
    setPanOffset({ x: 0, y: 0 });
  }, []);

  const handleWheel = useCallback((e: React.WheelEvent) => {
    if (selectedIndex === null) return;
    // Normalize delta for different browsers/mice
    const delta = e.deltaY > 0 ? -0.15 : 0.15;
    setZoomLevel(prev => Math.min(Math.max(prev + delta, 1), 6));
  }, [selectedIndex]);

  const toggleFullScreen = useCallback(() => {
    if (!document.fullscreenElement) {
      modalRef.current?.requestFullscreen().catch(err => {
        console.error(`Error attempting to enable full-screen mode: ${err.message}`);
      });
      setIsFullScreen(true);
    } else {
      document.exitFullscreen();
      setIsFullScreen(false);
    }
  }, []);

  useEffect(() => {
    const onFsChange = () => setIsFullScreen(!!document.fullscreenElement);
    document.addEventListener('fullscreenchange', onFsChange);
    return () => document.removeEventListener('fullscreenchange', onFsChange);
  }, []);

  const handlePickFolder = async () => {
    if ('showDirectoryPicker' in window) {
      try {
        const handle = await (window as any).showDirectoryPicker();
        setTargetLabel(handle.name);
      } catch (e) {
        console.debug('Folder picker cancelled or failed', e);
      }
    } else {
      alert('Your browser does not support folder picking. Please type the name manually.');
    }
  };

  const exportSingle = (img: ImageItem) => {
    if (!img.resultUrl) return;
    const prefix = targetLabel.trim() || 'colorized';
    const link = document.createElement('a');
    link.href = img.resultUrl;
    link.download = `${prefix}_${img.file.name}`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const exportFiltered = () => {
    if (filteredImages.length === 0) return;
    const prefix = targetLabel || 'export';
    filteredImages.forEach((img, idx) => {
      if (img.resultUrl) {
        setTimeout(() => {
          const link = document.createElement('a');
          link.href = img.resultUrl!;
          link.download = `${prefix}_${img.file.name}`;
          link.click();
        }, idx * 200);
      }
    });
  };

  const handleKeyDown = useCallback((e: KeyboardEvent) => {
    if (selectedIndex === null) return;
    if (e.key === 'f' || e.key === 'F') { e.preventDefault(); toggleFullScreen(); }
    else if (e.key === '+' || e.key === '=') { e.preventDefault(); setZoomLevel(prev => Math.min(prev + 0.2, 5)); }
    else if (e.key === '-' || e.key === '_') { e.preventDefault(); setZoomLevel(prev => Math.max(prev - 0.2, 1)); }
    else if (e.key === '0') { e.preventDefault(); resetView(); }
    else if (e.key === 'Escape') {
      if (document.fullscreenElement) document.exitFullscreen();
      else setSelectedIndex(null);
    }
  }, [selectedIndex, toggleFullScreen, resetView]);

  useEffect(() => {
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleKeyDown]);

  return (
    <div className={`min-h-screen dark bg-slate-950 text-slate-100 font-sans lang-${lang} ${isRtl ? 'rtl' : 'ltr'}`} dir={isRtl ? 'rtl' : 'ltr'}>
      <header className="sticky top-0 z-40 bg-slate-900/90 backdrop-blur-xl border-b border-slate-800 shadow-2xl">
        <div className="max-w-6xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <span className="text-2xl drop-shadow-[0_0_10px_rgba(99,102,241,0.5)]" title={t.title}>🎨</span>
            <h1 className="text-lg font-black tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-indigo-400 to-indigo-200">{t.title}</h1>
          </div>
          <div className="flex items-center gap-3">
            <select 
              value={lang} 
              onChange={(e) => setLang(e.target.value as Language)}
              title={t.languageSelect}
              aria-label={t.languageSelect}
              className="bg-slate-800 border border-slate-700 rounded-xl px-3 py-1.5 text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-500 transition-all cursor-pointer text-slate-100"
            >
              <option value="en">English</option>
              <option value="he">עברית</option>
              <option value="zh">中文</option>
              <option value="hi">हिन्दी</option>
              <option value="de">Deutsch</option>
              <option value="es">Español</option>
              <option value="fr">Français</option>
            </select>
          </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-6 py-12">
        <div className="text-center mb-12">
          <h2 className="text-3xl md:text-5xl font-extrabold mb-4 tracking-tight text-white">{t.subtitle}</h2>
          <div className="flex items-center justify-center gap-2">
            <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
            <p className="text-slate-400 max-w-xl text-sm font-medium">{t.offlineReady}</p>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
          <aside className="lg:col-span-1 space-y-6">
            <div className="bg-slate-900 p-6 rounded-[2.5rem] shadow-2xl border border-slate-800">
              <label className="block text-[10px] font-black uppercase tracking-[0.2em] text-slate-500 mb-3 ml-1">{t.targetFolder}</label>
              <div 
                className="relative group"
                onDragOver={(e) => { e.preventDefault(); }}
                onDrop={(e) => { 
                  e.preventDefault(); 
                  const files = e.dataTransfer.items;
                  if (files && files[0] && files[0].kind === 'file') {
                    const entry = (files[0] as any).webkitGetAsEntry();
                    if (entry && entry.isDirectory) {
                      setTargetLabel(entry.name);
                    }
                  }
                }}
              >
                <input 
                  type="text" 
                  list="labels-list"
                  value={targetLabel} 
                  onChange={(e) => setTargetLabel(e.target.value)}
                  placeholder={t.targetFolderPlaceholder} 
                  className="w-full pl-4 pr-10 py-3.5 bg-slate-950 border border-slate-800 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all text-sm font-medium text-white placeholder:text-slate-700" 
                />
                <datalist id="labels-list">
                  {usedLabels.map(s => <option key={s} value={s} />)}
                </datalist>
                <button 
                  onClick={handlePickFolder}
                  title={t.pickFolder}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-600 hover:text-indigo-400 transition-colors"
                >
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z" /></svg>
                </button>
              </div>
              <div className="mt-8 space-y-3">
                <button 
                  onClick={exportFiltered} 
                  disabled={filteredImages.length === 0} 
                  className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-800 disabled:text-slate-500 disabled:opacity-50 text-white font-bold rounded-2xl shadow-xl transition-all flex items-center justify-center gap-2 text-sm"
                  title={t.downloadAll}
                >
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                  {t.downloadAll}
                </button>
                <button 
                  onClick={() => setImages([])} 
                  className="w-full py-3 text-slate-500 hover:text-rose-400 text-[10px] font-black uppercase tracking-[0.2em] transition-colors"
                  title={t.clearBtn}
                >
                  {t.clearBtn}
                </button>
              </div>
            </div>
            <AdPlaceholder label={t.adPlaceholder} />
          </aside>

          <section className="lg:col-span-3 space-y-6">
            <div 
              onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
              onDragLeave={() => setIsDragging(false)}
              onDrop={(e) => { e.preventDefault(); setIsDragging(false); handleFiles(e.dataTransfer.files); }}
              onClick={() => fileInputRef.current?.click()}
              className={`group border-2 border-dashed rounded-[3rem] p-14 text-center cursor-pointer transition-all duration-500 ${isDragging ? 'drag-pulsing' : 'border-slate-800 hover:border-indigo-500/50 bg-slate-900/50 hover:bg-slate-900'}`}
              title={t.dropzoneTitle}
            >
              <input type="file" multiple accept="image/*" className="hidden" ref={fileInputRef} onChange={(e) => handleFiles(e.target.files)} />
              <div className={`w-16 h-16 bg-indigo-500/10 rounded-[1.5rem] flex items-center justify-center mx-auto mb-6 transition-all group-hover:scale-110 ${isDragging ? 'scale-125 drag-content-pulsing' : ''}`}>
                <svg className="w-8 h-8 text-indigo-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>
              </div>
              <h3 className="text-2xl font-black mb-1 text-white">{t.dropzoneTitle}</h3>
              <p className="text-slate-500 text-[10px] font-black uppercase tracking-[0.2em]">{t.dropzoneSub}</p>
            </div>

            {images.length > 0 && (
              <div className="relative">
                <input 
                  type="text" 
                  value={searchQuery} 
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder={t.searchPlaceholder}
                  className="w-full pl-11 pr-4 py-4 bg-slate-900 border border-slate-800 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm text-white" 
                  title={t.search}
                />
                <svg className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 text-slate-600" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
              </div>
            )}

            <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-3 xl:grid-cols-4 gap-6">
              {filteredImages.map((img) => (
                <ImageCard 
                  key={img.id} 
                  item={img} 
                  t={t} 
                  onRemove={(id) => setImages(prev => prev.filter(i => i.id !== id))} 
                  onSelect={() => { setSelectedIndex(images.indexOf(img)); setShowOriginalInModal(false); resetView(); }} 
                  onShare={handleShare} 
                />
              ))}
            </div>
          </section>
        </div>
      </main>

      {selectedIndex !== null && images[selectedIndex] && (
        <div 
          ref={modalRef} 
          className="fixed inset-0 z-50 flex flex-col bg-slate-950/95 backdrop-blur-3xl animate-in fade-in duration-500 overflow-hidden" 
          onClick={() => setSelectedIndex(null)}
          onWheel={handleWheel}
        >
          {/* Header Bar - Floating and Translucent */}
          <div className="absolute top-0 left-0 right-0 z-50 h-16 px-6 flex items-center justify-between bg-slate-900/40 backdrop-blur-md border-b border-white/5 transition-opacity hover:opacity-100 opacity-90" onClick={e => e.stopPropagation()}>
            <div className="flex items-center gap-3 truncate">
               <span className="text-white text-[10px] font-black uppercase tracking-wider truncate bg-slate-950/60 px-3 py-1.5 rounded-lg border border-white/10">{images[selectedIndex].file.name}</span>
               {isFullScreen && <span className="text-[10px] font-bold text-indigo-400 animate-pulse">FULLSCREEN MODE</span>}
               {images[selectedIndex].status === 'error' && <span className="text-[10px] font-bold text-rose-400 bg-rose-500/10 px-2 py-1 rounded border border-rose-500/20" title={images[selectedIndex].error}>{t.error}</span>}
            </div>
            <div className="flex items-center gap-3">
              {images[selectedIndex].resultUrl && (
                <button 
                  onClick={(e) => { e.stopPropagation(); setShowOriginalInModal(!showOriginalInModal); }} 
                  className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-[0.1em] transition-all border ${showOriginalInModal ? 'bg-indigo-600 text-white border-indigo-400' : 'bg-slate-800/80 text-slate-300 border-white/10 hover:bg-slate-700'}`}
                  title={showOriginalInModal ? t.result : t.original}
                >
                  {showOriginalInModal ? t.result : t.original}
                </button>
              )}
              <button 
                onClick={(e) => { e.stopPropagation(); exportSingle(images[selectedIndex!]); }} 
                className="px-4 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl text-[10px] font-black uppercase tracking-[0.1em] disabled:opacity-50 transition-colors border border-indigo-400 shadow-lg"
                disabled={!images[selectedIndex].resultUrl}
                title={t.export}
              >
                {t.export}
              </button>
              <div className="w-px h-6 bg-white/10 mx-1"></div>
              <button 
                onClick={() => setSelectedIndex(null)} 
                className="p-2 text-slate-300 hover:text-rose-400 transition-colors"
                title={t.close}
              >
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>
          </div>

          {/* Main Viewport */}
          <div className="flex-1 flex items-center justify-center p-4 md:p-12 overflow-hidden" onClick={e => e.stopPropagation()}>
            <div className="relative transition-transform duration-200 ease-out cursor-zoom-in" style={{ transform: `scale(${zoomLevel}) translate(${panOffset.x / zoomLevel}px, ${panOffset.y / zoomLevel}px)` }}>
              <img 
                src={showOriginalInModal || !images[selectedIndex].resultUrl ? images[selectedIndex].previewUrl : images[selectedIndex].resultUrl} 
                alt="Preview" 
                className="max-w-full max-h-[85vh] object-contain rounded-2xl md:rounded-[2rem] shadow-[0_35px_60px_-15px_rgba(0,0,0,0.6)] border border-white/5" 
              />
              {images[selectedIndex].status === 'error' && (
                <div className="absolute inset-0 flex flex-col items-center justify-center bg-rose-950/40 backdrop-blur-sm rounded-2xl md:rounded-[2rem] p-6 text-center">
                   <div className="w-16 h-16 bg-rose-500/20 rounded-full flex items-center justify-center mb-4 border border-rose-500/40">
                      <svg className="w-8 h-8 text-rose-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                   </div>
                   <h4 className="text-xl font-black text-rose-400 mb-2 uppercase tracking-widest">{t.error}</h4>
                   <p className="text-slate-200 text-sm max-w-md bg-slate-900/80 p-4 rounded-xl border border-white/5 shadow-2xl font-mono break-words">
                     {images[selectedIndex].error || "An unknown error occurred during colorization."}
                   </p>
                </div>
              )}
            </div>
          </div>

          {/* Controls Island - Adapts for Fullscreen */}
          <div className={`absolute bottom-8 left-1/2 -translate-x-1/2 z-50 flex flex-col items-center gap-4 transition-all ${isFullScreen ? 'scale-110 drop-shadow-[0_0_30px_rgba(0,0,0,0.8)]' : ''}`} onClick={e => e.stopPropagation()}>
            <div className="bg-slate-900/70 backdrop-blur-xl border border-white/10 rounded-[2rem] px-6 py-4 flex items-center gap-6 shadow-2xl min-w-[320px] max-w-[90vw]">
              <button 
                onClick={() => setZoomLevel(prev => Math.max(prev - 0.2, 1))} 
                className="p-3 bg-slate-800/80 hover:bg-indigo-600/20 text-slate-300 hover:text-indigo-400 rounded-2xl border border-white/5 transition-all"
                title={t.zoomOut}
              >
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M20 12H4" /></svg>
              </button>

              <div className="flex-1 flex flex-col items-center gap-1">
                 <input 
                   type="range" 
                   min="1" 
                   max="5" 
                   step="0.05" 
                   value={zoomLevel} 
                   onChange={(e) => setZoomLevel(parseFloat(e.target.value))} 
                   className="w-full accent-indigo-500 h-1.5 rounded-full cursor-pointer opacity-80 hover:opacity-100 transition-opacity" 
                   title={t.zoomLevel}
                 />
                 <span className="text-[8px] font-black text-slate-500 uppercase tracking-widest">{t.zoomLevel}: {Math.round(zoomLevel * 100)}%</span>
              </div>

              <button 
                onClick={() => setZoomLevel(prev => Math.min(prev + 0.2, 5))} 
                className="p-3 bg-slate-800/80 hover:bg-indigo-600/20 text-slate-300 hover:text-indigo-400 rounded-2xl border border-white/5 transition-all"
                title={t.zoomIn}
              >
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 6v6m0 0v6m0-6h6m-6 0H6" /></svg>
              </button>

              <div className="w-px h-8 bg-white/10 hidden sm:block"></div>

              <button 
                onClick={toggleFullScreen}
                className={`p-3 rounded-2xl border border-white/5 transition-all hidden sm:block ${isFullScreen ? 'bg-indigo-600/40 text-indigo-200 border-indigo-500/30' : 'bg-slate-800/80 text-slate-300 hover:bg-slate-700'}`}
                title={t.fullScreen}
              >
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  {isFullScreen 
                    ? <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" />
                    : <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" />
                  }
                </svg>
              </button>
            </div>

            <button 
              onClick={resetView} 
              className="px-4 py-2 bg-slate-950/60 backdrop-blur-md border border-white/5 rounded-full text-[9px] font-black uppercase tracking-widest text-indigo-400 hover:text-indigo-300 transition-colors shadow-xl"
              title={t.resetView}
            >
              {t.resetView}
            </button>
          </div>
        </div>
      )}

      <footer className="py-16 text-center opacity-40">
        <p className="text-[10px] font-black uppercase tracking-[0.5em] mb-3">Restoration Engine powered by Gemini 2.5</p>
        <p className="text-[10px] font-black uppercase tracking-[0.3em] mb-4 text-indigo-400">(C) Noam Gold AI 2026</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Language, ImageItem } from './types';
import { translations } from './i18n';
import { processImageWithGemini, fileToBase64 } from './services/geminiService';
import { ImageCard } from './components/ImageCard';
import { AdPlaceholder } from './components/AdPlaceholder';

const INITIAL_SUGGESTIONS = ['Personal Photos', 'Family Heritage', 'Travel 2024', 'Work Projects', 'Client Deliverables'];

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('en');
  const [images, setImages] = useState<ImageItem[]>([]);
  const [targetLabel, setTargetLabel] = useState('');
  const [usedLabels, setUsedLabels] = useState<string[]>(INITIAL_SUGGESTIONS);
  const [searchQuery, setSearchQuery] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const [zoomLevel, setZoomLevel] = useState(1);
  const [panOffset, setPanOffset] = useState({ x: 0, y: 0 });
  const [isFullScreen, setIsFullScreen] = useState(false);
  const [showOriginalInModal, setShowOriginalInModal] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const modalRef = useRef<HTMLDivElement>(null);
  const t = translations[lang];
  const isRtl = lang === 'he';

  const filteredImages = images.filter(img => 
    img.file.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const processNextPending = useCallback(async () => {
    const nextItem = images.find(img => img.status === 'pending');
    if (!nextItem || isProcessing) return;

    setIsProcessing(true);
    setImages(prev => prev.map(img => 
      img.id === nextItem.id ? { ...img, status: 'processing', error: undefined } : img
    ));

    try {
      const base64 = await fileToBase64(nextItem.file);
      const resultUrl = await processImageWithGemini(base64, nextItem.file.type);
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'completed', resultUrl, destination: targetLabel } : img
      ));

      if (targetLabel.trim() && !usedLabels.includes(targetLabel.trim())) {
        setUsedLabels(prev => [targetLabel.trim(), ...prev].slice(0, 15));
      }
    } catch (err: any) {
      const errorMessage = err?.message || String(err);
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'error', error: errorMessage } : img
      ));
    } finally {
      setIsProcessing(false);
    }
  }, [images, isProcessing, targetLabel, usedLabels]);

  useEffect(() => {
    processNextPending();
  }, [images, processNextPending]);

  const handleFiles = (files: FileList | null) => {
    if (!files) return;
    const newImages: ImageItem[] = Array.from(files).map(file => ({
      id: Math.random().toString(36).substr(2, 9),
      file,
      previewUrl: URL.createObjectURL(file),
      status: 'pending'
    }));
    setImages(prev => [...prev, ...newImages]);
  };

  const handleShare = (item: ImageItem) => {
    const url = item.resultUrl || item.previewUrl;
    navigator.clipboard.writeText(url).then(() => {
      alert(t.shareSuccess);
    });
  };

  const resetView = useCallback(() => {
    setZoomLevel(1);
    setPanOffset({ x: 0, y: 0 });
  }, []);

  const handleWheel = useCallback((e: React.WheelEvent) => {
    if (selectedIndex === null) return;
    // Normalized smooth wheel zoom
    const delta = -e.deltaY;
    const factor = 0.001; // Sensitivity
    setZoomLevel(prev => Math.min(Math.max(prev + delta * factor * prev, 1), 8));
  }, [selectedIndex]);

  const toggleFullScreen = useCallback(() => {
    if (!document.fullscreenElement) {
      modalRef.current?.requestFullscreen().catch(err => {
        console.error(`Fullscreen failed: ${err.message}`);
      });
      setIsFullScreen(true);
    } else {
      document.exitFullscreen();
      setIsFullScreen(false);
    }
  }, []);

  useEffect(() => {
    const onFsChange = () => setIsFullScreen(!!document.fullscreenElement);
    document.addEventListener('fullscreenchange', onFsChange);
    return () => document.removeEventListener('fullscreenchange', onFsChange);
  }, []);

  const handlePickFolder = async () => {
    if ('showDirectoryPicker' in window) {
      try {
        const handle = await (window as any).showDirectoryPicker();
        setTargetLabel(handle.name);
      } catch (e) {
        console.debug('Folder picker cancelled', e);
      }
    } else {
      alert('Manual folder typing is required on this browser.');
    }
  };

  const exportSingle = (img: ImageItem) => {
    if (!img.resultUrl) return;
    const prefix = targetLabel.trim() || 'colorized';
    const link = document.createElement('a');
    link.href = img.resultUrl;
    link.download = `${prefix}_${img.file.name}`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const exportFiltered = () => {
    if (filteredImages.length === 0) return;
    const prefix = targetLabel || 'export';
    filteredImages.forEach((img, idx) => {
      if (img.resultUrl) {
        setTimeout(() => {
          const link = document.createElement('a');
          link.href = img.resultUrl!;
          link.download = `${prefix}_${img.file.name}`;
          link.click();
        }, idx * 150);
      }
    });
  };

  const handleKeyDown = useCallback((e: KeyboardEvent) => {
    if (selectedIndex === null) return;
    if (e.key === 'f' || e.key === 'F') { e.preventDefault(); toggleFullScreen(); }
    else if (e.key === '+' || e.key === '=') { e.preventDefault(); setZoomLevel(prev => Math.min(prev + 0.2, 8)); }
    else if (e.key === '-' || e.key === '_') { e.preventDefault(); setZoomLevel(prev => Math.max(prev - 0.2, 1)); }
    else if (e.key === '0') { e.preventDefault(); resetView(); }
    else if (e.key === 'Escape') {
      if (document.fullscreenElement) document.exitFullscreen();
      else setSelectedIndex(null);
    }
  }, [selectedIndex, toggleFullScreen, resetView]);

  useEffect(() => {
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleKeyDown]);

  return (
    <div className={`min-h-screen dark bg-slate-950 text-slate-100 font-sans lang-${lang} ${isRtl ? 'rtl' : 'ltr'}`} dir={isRtl ? 'rtl' : 'ltr'}>
      <header className="sticky top-0 z-40 bg-slate-900/90 backdrop-blur-xl border-b border-slate-800 shadow-2xl">
        <div className="max-w-6xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <span className="text-2xl drop-shadow-[0_0_10px_rgba(99,102,241,0.5)]" title={t.title}>🎨</span>
            <h1 className="text-lg font-black tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-indigo-400 to-indigo-200">{t.title}</h1>
          </div>
          <div className="flex items-center gap-3">
            <select 
              value={lang} 
              onChange={(e) => setLang(e.target.value as Language)}
              title={t.languageSelect}
              className="bg-slate-800 border border-slate-700 rounded-xl px-3 py-1.5 text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-500 transition-all cursor-pointer text-slate-100"
            >
              <option value="en">English</option>
              <option value="he">עברית</option>
              <option value="zh">中文</option>
              <option value="hi">हिन्दी</option>
              <option value="de">Deutsch</option>
              <option value="es">Español</option>
              <option value="fr">Français</option>
            </select>
          </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-6 py-12">
        <div className="text-center mb-12">
          <h2 className="text-3xl md:text-5xl font-extrabold mb-4 tracking-tight text-white">{t.subtitle}</h2>
          <div className="flex items-center justify-center gap-2">
            <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
            <p className="text-slate-400 max-w-xl text-sm font-medium">{t.offlineReady}</p>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
          <aside className="lg:col-span-1 space-y-6">
            <div className="bg-slate-900 p-6 rounded-[2.5rem] shadow-2xl border border-slate-800">
              <label className="block text-[10px] font-black uppercase tracking-[0.2em] text-slate-500 mb-3 ml-1">{t.targetFolder}</label>
              <div className="relative group">
                <input 
                  type="text" 
                  list="labels-list"
                  value={targetLabel} 
                  onChange={(e) => setTargetLabel(e.target.value)}
                  placeholder={t.targetFolderPlaceholder} 
                  className="w-full pl-4 pr-10 py-3.5 bg-slate-950 border border-slate-800 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all text-sm font-medium text-white placeholder:text-slate-700" 
                  title={t.targetFolder}
                />
                <datalist id="labels-list">
                  {usedLabels.map(s => <option key={s} value={s} />)}
                </datalist>
                <button 
                  onClick={handlePickFolder}
                  title={t.pickFolder}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-600 hover:text-indigo-400 transition-colors"
                >
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z" /></svg>
                </button>
              </div>
              <div className="mt-8 space-y-3">
                <button 
                  onClick={exportFiltered} 
                  disabled={filteredImages.length === 0} 
                  className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-800 disabled:text-slate-500 disabled:opacity-50 text-white font-bold rounded-2xl shadow-xl transition-all flex items-center justify-center gap-2 text-sm"
                  title={t.downloadAll}
                >
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                  {t.downloadAll}
                </button>
                <button 
                  onClick={() => setImages([])} 
                  className="w-full py-3 text-slate-500 hover:text-rose-400 text-[10px] font-black uppercase tracking-[0.2em] transition-colors"
                  title={t.clearBtn}
                >
                  {t.clearBtn}
                </button>
              </div>
            </div>
            <AdPlaceholder label={t.adPlaceholder} />
          </aside>

          <section className="lg:col-span-3 space-y-6">
            <div 
              onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
              onDragLeave={() => setIsDragging(false)}
              onDrop={(e) => { e.preventDefault(); setIsDragging(false); handleFiles(e.dataTransfer.files); }}
              onClick={() => fileInputRef.current?.click()}
              className={`group border-2 border-dashed rounded-[3rem] p-14 text-center cursor-pointer transition-all duration-500 ${isDragging ? 'drag-pulsing' : 'border-slate-800 hover:border-indigo-500/50 bg-slate-900/50 hover:bg-slate-900'}`}
              title={t.dropzoneTitle}
            >
              <input type="file" multiple accept="image/*" className="hidden" ref={fileInputRef} onChange={(e) => handleFiles(e.target.files)} />
              <div className={`w-16 h-16 bg-indigo-500/10 rounded-[1.5rem] flex items-center justify-center mx-auto mb-6 transition-all group-hover:scale-110 ${isDragging ? 'scale-125 drag-content-pulsing' : ''}`}>
                <svg className="w-8 h-8 text-indigo-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>
              </div>
              <h3 className="text-2xl font-black mb-1 text-white">{t.dropzoneTitle}</h3>
              <p className="text-slate-500 text-[10px] font-black uppercase tracking-[0.2em]">{t.dropzoneSub}</p>
            </div>

            {images.length > 0 && (
              <div className="relative">
                <input 
                  type="text" 
                  value={searchQuery} 
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder={t.searchPlaceholder}
                  className="w-full pl-11 pr-4 py-4 bg-slate-900 border border-slate-800 rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm text-white" 
                  title={t.search}
                />
                <svg className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 text-slate-600" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
              </div>
            )}

            <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-3 xl:grid-cols-4 gap-6">
              {filteredImages.map((img) => (
                <ImageCard 
                  key={img.id} 
                  item={img} 
                  t={t} 
                  onRemove={(id) => setImages(prev => prev.filter(i => i.id !== id))} 
                  onSelect={(item) => { setSelectedIndex(images.indexOf(item)); setShowOriginalInModal(false); resetView(); }} 
                  onShare={handleShare} 
                />
              ))}
            </div>
          </section>
        </div>
      </main>

      {selectedIndex !== null && images[selectedIndex] && (
        <div 
          ref={modalRef} 
          className="fixed inset-0 z-50 flex flex-col bg-slate-950/98 backdrop-blur-3xl animate-in fade-in duration-300 overflow-hidden" 
          onClick={() => setSelectedIndex(null)}
          onWheel={handleWheel}
        >
          {/* Header Bar - Distinct & Sticky */}
          <div className={`absolute top-0 left-0 right-0 z-50 h-16 px-6 flex items-center justify-between border-b border-white/5 transition-all ${isFullScreen ? 'bg-slate-900/30 opacity-40 hover:opacity-100' : 'bg-slate-900/90 backdrop-blur-xl'}`} onClick={e => e.stopPropagation()}>
            <div className="flex items-center gap-3 truncate">
               <span className="text-white text-[10px] font-black uppercase tracking-wider truncate bg-slate-950/60 px-3 py-1.5 rounded-lg border border-white/10">{images[selectedIndex].file.name}</span>
               {isFullScreen && <span className="text-[10px] font-bold text-indigo-400 animate-pulse tracking-widest bg-indigo-500/10 px-2 py-1 rounded">LIVE FULLSCREEN</span>}
            </div>
            <div className="flex items-center gap-3">
              {images[selectedIndex].resultUrl && (
                <button 
                  onClick={(e) => { e.stopPropagation(); setShowOriginalInModal(!showOriginalInModal); }} 
                  className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-[0.1em] transition-all border ${showOriginalInModal ? 'bg-indigo-600 text-white border-indigo-400' : 'bg-slate-800/80 text-slate-300 border-white/10 hover:bg-slate-700'}`}
                  title={showOriginalInModal ? t.result : t.original}
                >
                  {showOriginalInModal ? t.result : t.original}
                </button>
              )}
              <button 
                onClick={(e) => { e.stopPropagation(); exportSingle(images[selectedIndex!]); }} 
                className="px-4 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl text-[10px] font-black uppercase tracking-[0.1em] disabled:opacity-50 transition-colors border border-indigo-400 shadow-lg"
                disabled={!images[selectedIndex].resultUrl}
                title={t.export}
              >
                {t.export}
              </button>
              <div className="w-px h-6 bg-white/10 mx-1"></div>
              <button 
                onClick={() => setSelectedIndex(null)} 
                className="p-2 text-slate-300 hover:text-rose-400 transition-colors"
                title={t.close}
              >
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>
          </div>

          {/* Main Viewport */}
          <div className="flex-1 flex items-center justify-center p-4 md:p-12 overflow-hidden" onClick={e => e.stopPropagation()}>
            <div className="relative transition-transform duration-100 ease-out" style={{ transform: `scale(${zoomLevel}) translate(${panOffset.x / zoomLevel}px, ${panOffset.y / zoomLevel}px)` }}>
              <img 
                src={showOriginalInModal || !images[selectedIndex].resultUrl ? images[selectedIndex].previewUrl : images[selectedIndex].resultUrl} 
                alt="Restored Preview" 
                className="max-w-full max-h-[85vh] object-contain rounded-2xl md:rounded-[2rem] shadow-[0_50px_100px_-20px_rgba(0,0,0,0.8)] border border-white/5" 
              />
              {images[selectedIndex].status === 'error' && (
                <div className="absolute inset-0 flex flex-col items-center justify-center bg-rose-950/60 backdrop-blur-md rounded-2xl md:rounded-[2rem] p-8 text-center border-2 border-rose-500/20">
                   <div className="w-20 h-20 bg-rose-500/30 rounded-full flex items-center justify-center mb-6 border border-rose-500/50 shadow-2xl animate-bounce">
                      <svg className="w-10 h-10 text-rose-300" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                   </div>
                   <h4 className="text-2xl font-black text-rose-300 mb-3 uppercase tracking-widest drop-shadow-lg">{t.error}</h4>
                   <p className="text-slate-100 text-sm max-w-lg bg-black/60 p-6 rounded-2xl border border-white/10 shadow-3xl font-mono leading-relaxed backdrop-blur-lg">
                     {images[selectedIndex].error || "A processing error occurred. Please check your internet or try a different image format."}
                   </p>
                </div>
              )}
            </div>
          </div>

          {/* Controls Island - Adapts for Fullscreen Accessibility */}
          <div className={`absolute bottom-8 left-1/2 -translate-x-1/2 z-50 flex flex-col items-center gap-5 transition-all duration-500 ${isFullScreen ? 'bottom-12 scale-110' : ''}`} onClick={e => e.stopPropagation()}>
            <div className={`flex items-center gap-6 px-8 py-5 rounded-[2.5rem] border shadow-3xl transition-all duration-500 ${isFullScreen ? 'bg-indigo-950/50 border-indigo-500/30 backdrop-blur-2xl ring-4 ring-indigo-500/10' : 'bg-slate-900/80 border-white/10 backdrop-blur-xl'}`}>
              <button 
                onClick={() => setZoomLevel(prev => Math.max(prev - 0.25, 1))} 
                className="p-4 bg-slate-800/80 hover:bg-indigo-600 text-slate-300 hover:text-white rounded-2xl border border-white/5 transition-all shadow-lg active:scale-90"
                title={t.zoomOut}
              >
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M20 12H4" /></svg>
              </button>

              <div className="flex flex-col items-center gap-2 min-w-[140px]">
                 <input 
                   type="range" 
                   min="1" 
                   max="8" 
                   step="0.01" 
                   value={zoomLevel} 
                   onChange={(e) => setZoomLevel(parseFloat(e.target.value))} 
                   className="w-full accent-indigo-400 h-2 rounded-full cursor-pointer hover:accent-indigo-300 transition-all shadow-inner" 
                   title={t.zoomLevel}
                 />
                 <span className="text-[10px] font-black text-indigo-200 uppercase tracking-widest drop-shadow-md">{t.zoomLevel}: {Math.round(zoomLevel * 100)}%</span>
              </div>

              <button 
                onClick={() => setZoomLevel(prev => Math.min(prev + 0.25, 8))} 
                className="p-4 bg-slate-800/80 hover:bg-indigo-600 text-slate-300 hover:text-white rounded-2xl border border-white/5 transition-all shadow-lg active:scale-90"
                title={t.zoomIn}
              >
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 6v6m0 0v6m0-6h6m-6 0H6" /></svg>
              </button>

              <div className="w-px h-10 bg-white/10 hidden sm:block"></div>

              <button 
                onClick={toggleFullScreen}
                className={`p-4 rounded-2xl border transition-all hidden sm:block shadow-lg active:scale-95 ${isFullScreen ? 'bg-indigo-600 text-white border-indigo-400 ring-2 ring-white/20' : 'bg-slate-800/80 border-white/10 text-slate-300 hover:bg-slate-700'}`}
                title={t.fullScreen}
              >
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  {isFullScreen 
                    ? <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" />
                    : <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" />
                  }
                </svg>
              </button>
            </div>

            <button 
              onClick={resetView} 
              className={`px-6 py-2.5 rounded-full text-[10px] font-black uppercase tracking-[0.2em] transition-all shadow-2xl border ${isFullScreen ? 'bg-indigo-600/60 text-white border-white/20 backdrop-blur-lg' : 'bg-slate-950/80 text-indigo-400 border-white/5 hover:text-indigo-200'}`}
              title={t.resetView}
            >
              {t.resetView}
            </button>
          </div>
        </div>
      )}

      <footer className="py-16 text-center opacity-30">
        <p className="text-[10px] font-black uppercase tracking-[0.5em] mb-3">Powered by Gemini 2.5 Restoration Engine</p>
        <p className="text-[10px] font-black uppercase tracking-[0.3em] text-indigo-400">© 2026 ChromaRestore Pro Systems</p>
      </footer>
    </div>
  );
};

export default App;

@import url('https://cdnjs.cloudflare.com/ajax/libs/tailwindcss/2.2.19/tailwind.min.css');

:root { 
  --primary: #6366f1; 
  --transition-speed: 0.3s;
}

/* Base Theme Variables */
.dark {
  --bg-app: #020617;
  --bg-header: rgba(15, 23, 42, 0.9);
  --bg-card: #0f172a;
  --bg-input: #020617;
  --text-main: #f1f5f9;
  --text-muted: #94a3b8;
  --border-main: #1e293b;
  --shadow-main: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

.light {
  --bg-app: #f8fafc;
  --bg-header: rgba(255, 255, 255, 0.9);
  --bg-card: #ffffff;
  --bg-input: #ffffff;
  --text-main: #0f172a;
  --text-muted: #475569;
  --border-main: #e2e8f0;
  --shadow-main: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
}

body {
  font-family: 'Plus Jakarta Sans', sans-serif;
  transition: background-color var(--transition-speed), color var(--transition-speed);
  overflow-x: hidden;
}

/* RTL Support */
[dir="rtl"] { font-family: 'Heebo', sans-serif; }
.lang-zh { font-family: 'Noto Sans SC', sans-serif; }
.lang-hi { font-family: 'Noto Sans Devanagari', sans-serif; }

/* Theme Utility Overrides */
.theme-bg-app { background-color: var(--bg-app); }
.theme-bg-card { background-color: var(--bg-card); }
.theme-text-main { color: var(--text-main); }
.theme-text-muted { color: var(--text-muted); }
.theme-border { border-color: var(--border-main); }

/* Animations */
@keyframes pulse-border {
  0%, 100% { border-color: rgba(99, 102, 241, 0.4); border-width: 2px; box-shadow: 0 0 0 0 rgba(99, 102, 241, 0); }
  50% { border-color: rgba(99, 102, 241, 1); border-width: 2px; box-shadow: 0 0 20px 0 rgba(99, 102, 241, 0.2); }
}

@keyframes pulse-content {
  0%, 100% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.02); opacity: 0.8; }
}

@keyframes shimmer {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(100%); }
}

.drag-pulsing {
  animation: pulse-border 1.5s infinite ease-in-out;
  background-color: rgba(99, 102, 241, 0.08) !important;
}

.drag-content-pulsing { animation: pulse-content 1.5s infinite ease-in-out; }

.shimmer-effect::after {
  content: "";
  position: absolute;
  top: 0; left: 0; width: 100%; height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.1), transparent);
  animation: shimmer 2s infinite;
}

/* Scrollbar */
::-webkit-scrollbar { width: 10px; }
::-webkit-scrollbar-track { background: var(--bg-app); }
::-webkit-scrollbar-thumb { background: var(--border-main); border-radius: 5px; }
::-webkit-scrollbar-thumb:hover { background: var(--text-muted); }

.backdrop-blur-xl { backdrop-filter: blur(24px); }
.backdrop-blur-3xl { backdrop-filter: blur(64px); }

/* Theme Transition Helper */
* {
  transition: background-color var(--transition-speed) ease, border-color var(--transition-speed) ease, color var(--transition-speed) ease, box-shadow var(--transition-speed) ease;
}

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Language, ImageItem } from './types';
import { translations } from './i18n';
import { processImageWithGemini, fileToBase64 } from './services/geminiService';
import { ImageCard } from './components/ImageCard';
import { AdPlaceholder } from './components/AdPlaceholder';

const INITIAL_SUGGESTIONS = ['Personal Photos', 'Family Heritage', 'Travel 2024', 'Work Projects', 'Client Deliverables'];

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('en');
  const [theme, setTheme] = useState<'dark' | 'light'>(() => {
    return (localStorage.getItem('chroma-theme') as 'dark' | 'light') || 'dark';
  });
  const [images, setImages] = useState<ImageItem[]>([]);
  const [targetLabel, setTargetLabel] = useState('');
  const [usedLabels, setUsedLabels] = useState<string[]>(INITIAL_SUGGESTIONS);
  const [searchQuery, setSearchQuery] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const [zoomLevel, setZoomLevel] = useState(1);
  const [panOffset, setPanOffset] = useState({ x: 0, y: 0 });
  const [isFullScreen, setIsFullScreen] = useState(false);
  const [showOriginalInModal, setShowOriginalInModal] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const modalRef = useRef<HTMLDivElement>(null);
  const t = translations[lang];
  const isRtl = lang === 'he';

  useEffect(() => {
    localStorage.setItem('chroma-theme', theme);
    document.documentElement.className = theme;
  }, [theme]);

  const filteredImages = images.filter(img => 
    img.file.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const processNextPending = useCallback(async () => {
    const nextItem = images.find(img => img.status === 'pending');
    if (!nextItem || isProcessing) return;

    setIsProcessing(true);
    setImages(prev => prev.map(img => 
      img.id === nextItem.id ? { ...img, status: 'processing', error: undefined } : img
    ));

    try {
      const base64 = await fileToBase64(nextItem.file);
      const resultUrl = await processImageWithGemini(base64, nextItem.file.type);
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'completed', resultUrl, destination: targetLabel } : img
      ));

      if (targetLabel.trim() && !usedLabels.includes(targetLabel.trim())) {
        setUsedLabels(prev => [targetLabel.trim(), ...prev].slice(0, 15));
      }
    } catch (err: any) {
      const errorMessage = err?.message || String(err);
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'error', error: errorMessage } : img
      ));
    } finally {
      setIsProcessing(false);
    }
  }, [images, isProcessing, targetLabel, usedLabels]);

  useEffect(() => {
    processNextPending();
  }, [images, processNextPending]);

  const handleFiles = (files: FileList | null) => {
    if (!files) return;
    const newImages: ImageItem[] = Array.from(files).map(file => ({
      id: Math.random().toString(36).substr(2, 9),
      file,
      previewUrl: URL.createObjectURL(file),
      status: 'pending'
    }));
    setImages(prev => [...prev, ...newImages]);
  };

  const handleShare = (item: ImageItem) => {
    const url = item.resultUrl || item.previewUrl;
    navigator.clipboard.writeText(url).then(() => {
      alert(t.shareSuccess);
    });
  };

  const resetView = useCallback(() => {
    setZoomLevel(1);
    setPanOffset({ x: 0, y: 0 });
  }, []);

  const handleWheel = useCallback((e: React.WheelEvent) => {
    if (selectedIndex === null) return;
    const delta = -e.deltaY;
    const factor = 0.001;
    setZoomLevel(prev => Math.min(Math.max(prev + delta * factor * prev, 1), 8));
  }, [selectedIndex]);

  const toggleFullScreen = useCallback(() => {
    if (!document.fullscreenElement) {
      modalRef.current?.requestFullscreen().catch(err => {
        console.error(`Fullscreen failed: ${err.message}`);
      });
      setIsFullScreen(true);
    } else {
      document.exitFullscreen();
      setIsFullScreen(false);
    }
  }, []);

  const toggleTheme = () => setTheme(prev => prev === 'dark' ? 'light' : 'dark');

  useEffect(() => {
    const onFsChange = () => setIsFullScreen(!!document.fullscreenElement);
    document.addEventListener('fullscreenchange', onFsChange);
    return () => document.removeEventListener('fullscreenchange', onFsChange);
  }, []);

  const handlePickFolder = async () => {
    if ('showDirectoryPicker' in window) {
      try {
        const handle = await (window as any).showDirectoryPicker();
        setTargetLabel(handle.name);
      } catch (e) {
        console.debug('Folder picker cancelled', e);
      }
    } else {
      alert('Manual folder typing is required on this browser.');
    }
  };

  const exportSingle = (img: ImageItem) => {
    if (!img.resultUrl) return;
    const prefix = targetLabel.trim() || 'colorized';
    const link = document.createElement('a');
    link.href = img.resultUrl;
    link.download = `${prefix}_${img.file.name}`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const exportFiltered = () => {
    if (filteredImages.length === 0) return;
    const prefix = targetLabel || 'export';
    filteredImages.forEach((img, idx) => {
      if (img.resultUrl) {
        setTimeout(() => {
          const link = document.createElement('a');
          link.href = img.resultUrl!;
          link.download = `${prefix}_${img.file.name}`;
          link.click();
        }, idx * 150);
      }
    });
  };

  const handleKeyDown = useCallback((e: KeyboardEvent) => {
    if (selectedIndex === null) return;
    if (e.key === 'f' || e.key === 'F') { e.preventDefault(); toggleFullScreen(); }
    else if (e.key === '+' || e.key === '=') { e.preventDefault(); setZoomLevel(prev => Math.min(prev + 0.2, 8)); }
    else if (e.key === '-' || e.key === '_') { e.preventDefault(); setZoomLevel(prev => Math.max(prev - 0.2, 1)); }
    else if (e.key === '0') { e.preventDefault(); resetView(); }
    else if (e.key === 'Escape') {
      if (document.fullscreenElement) document.exitFullscreen();
      else setSelectedIndex(null);
    }
  }, [selectedIndex, toggleFullScreen, resetView]);

  useEffect(() => {
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleKeyDown]);

  return (
    <div className={`min-h-screen ${theme} theme-bg-app theme-text-main font-sans lang-${lang} ${isRtl ? 'rtl' : 'ltr'}`} dir={isRtl ? 'rtl' : 'ltr'}>
      <header className={`sticky top-0 z-40 backdrop-blur-xl border-b theme-border shadow-2xl ${theme === 'dark' ? 'bg-slate-900/90' : 'bg-white/90'}`}>
        <div className="max-w-6xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <span className="text-2xl drop-shadow-[0_0_10px_rgba(99,102,241,0.5)]" title={t.title}>🎨</span>
            <h1 className="text-lg font-black tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-indigo-500 to-indigo-300">{t.title}</h1>
          </div>
          <div className="flex items-center gap-3">
            <button 
              onClick={toggleTheme}
              className={`p-2 rounded-xl transition-all border theme-border ${theme === 'dark' ? 'bg-slate-800 text-yellow-400 hover:bg-slate-700' : 'bg-slate-100 text-slate-700 hover:bg-slate-200'}`}
              title={theme === 'dark' ? 'Switch to Light Mode' : 'Switch to Dark Mode'}
            >
              {theme === 'dark' ? (
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m9-9h-1M4 9H3m15.364-6.364l-.707.707M6.343 17.657l-.707.707m12.728 0l-.707-.707M6.343 6.343l-.707-.707M12 8a4 4 0 100 8 4 4 0 000-8z" /></svg>
              ) : (
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" /></svg>
              )}
            </button>
            <select 
              value={lang} 
              onChange={(e) => setLang(e.target.value as Language)}
              title={t.languageSelect}
              className={`border theme-border rounded-xl px-3 py-1.5 text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-500 transition-all cursor-pointer ${theme === 'dark' ? 'bg-slate-800 text-slate-100' : 'bg-slate-100 text-slate-900'}`}
            >
              <option value="en">English</option>
              <option value="he">עברית</option>
              <option value="zh">中文</option>
              <option value="hi">हिन्दी</option>
              <option value="de">Deutsch</option>
              <option value="es">Español</option>
              <option value="fr">Français</option>
            </select>
          </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-6 py-12">
        <div className="text-center mb-12">
          <h2 className="text-3xl md:text-5xl font-extrabold mb-4 tracking-tight theme-text-main">{t.subtitle}</h2>
          <div className="flex items-center justify-center gap-2">
            <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
            <p className="theme-text-muted max-w-xl text-sm font-medium">{t.offlineReady}</p>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
          <aside className="lg:col-span-1 space-y-6">
            <div className={`p-6 rounded-[2.5rem] shadow-2xl border theme-border theme-bg-card`}>
              <label className="block text-[10px] font-black uppercase tracking-[0.2em] theme-text-muted mb-3 ml-1">{t.targetFolder}</label>
              <div className="relative group">
                <input 
                  type="text" 
                  list="labels-list"
                  value={targetLabel} 
                  onChange={(e) => setTargetLabel(e.target.value)}
                  placeholder={t.targetFolderPlaceholder} 
                  className={`w-full pl-4 pr-10 py-3.5 border theme-border rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all text-sm font-medium theme-text-main ${theme === 'dark' ? 'bg-slate-950 placeholder:text-slate-700' : 'bg-slate-50 placeholder:text-slate-400'}`} 
                  title={t.targetFolder}
                />
                <datalist id="labels-list">
                  {usedLabels.map(s => <option key={s} value={s} />)}
                </datalist>
                <button 
                  onClick={handlePickFolder}
                  title={t.pickFolder}
                  className="absolute right-3 top-1/2 -translate-y-1/2 theme-text-muted hover:text-indigo-400 transition-colors"
                >
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z" /></svg>
                </button>
              </div>
              <div className="mt-8 space-y-3">
                <button 
                  onClick={exportFiltered} 
                  disabled={filteredImages.length === 0} 
                  className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-800 disabled:text-slate-500 disabled:opacity-50 text-white font-bold rounded-2xl shadow-xl transition-all flex items-center justify-center gap-2 text-sm"
                  title={t.downloadAll}
                >
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                  {t.downloadAll}
                </button>
                <button 
                  onClick={() => setImages([])} 
                  className="w-full py-3 theme-text-muted hover:text-rose-400 text-[10px] font-black uppercase tracking-[0.2em] transition-colors"
                  title={t.clearBtn}
                >
                  {t.clearBtn}
                </button>
              </div>
            </div>
            <AdPlaceholder label={t.adPlaceholder} />
          </aside>

          <section className="lg:col-span-3 space-y-6">
            <div 
              onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
              onDragLeave={() => setIsDragging(false)}
              onDrop={(e) => { e.preventDefault(); setIsDragging(false); handleFiles(e.dataTransfer.files); }}
              onClick={() => fileInputRef.current?.click()}
              className={`group border-2 border-dashed rounded-[3rem] p-14 text-center cursor-pointer transition-all duration-500 ${isDragging ? 'drag-pulsing' : `theme-border hover:border-indigo-500/50 ${theme === 'dark' ? 'bg-slate-900/50 hover:bg-slate-900' : 'bg-white hover:bg-slate-50 shadow-lg'}`}`}
              title={t.dropzoneTitle}
            >
              <input type="file" multiple accept="image/*" className="hidden" ref={fileInputRef} onChange={(e) => handleFiles(e.target.files)} />
              <div className={`w-16 h-16 bg-indigo-500/10 rounded-[1.5rem] flex items-center justify-center mx-auto mb-6 transition-all group-hover:scale-110 ${isDragging ? 'scale-125 drag-content-pulsing' : ''}`}>
                <svg className="w-8 h-8 text-indigo-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>
              </div>
              <h3 className="text-2xl font-black mb-1 theme-text-main">{t.dropzoneTitle}</h3>
              <p className="theme-text-muted text-[10px] font-black uppercase tracking-[0.2em]">{t.dropzoneSub}</p>
            </div>

            {images.length > 0 && (
              <div className="relative">
                <input 
                  type="text" 
                  value={searchQuery} 
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder={t.searchPlaceholder}
                  className={`w-full pl-11 pr-4 py-4 border theme-border rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm theme-text-main theme-bg-card`} 
                  title={t.search}
                />
                <svg className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 theme-text-muted" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
              </div>
            )}

            <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-3 xl:grid-cols-4 gap-6">
              {filteredImages.map((img) => (
                <ImageCard 
                  key={img.id} 
                  item={img} 
                  t={t} 
                  theme={theme}
                  onRemove={(id) => setImages(prev => prev.filter(i => i.id !== id))} 
                  onSelect={(item) => { setSelectedIndex(images.indexOf(item)); setShowOriginalInModal(false); resetView(); }} 
                  onShare={handleShare} 
                />
              ))}
            </div>
          </section>
        </div>
      </main>

      {selectedIndex !== null && images[selectedIndex] && (
        <div 
          ref={modalRef} 
          className={`fixed inset-0 z-50 flex flex-col backdrop-blur-3xl animate-in fade-in duration-300 overflow-hidden ${theme === 'dark' ? 'bg-slate-950/98' : 'bg-slate-50/95'}`} 
          onClick={() => setSelectedIndex(null)}
          onWheel={handleWheel}
        >
          {/* Header Bar - Distinct & Sticky */}
          <div className={`absolute top-0 left-0 right-0 z-50 h-16 px-6 flex items-center justify-between border-b theme-border transition-all ${isFullScreen ? 'opacity-40 hover:opacity-100 bg-slate-900/30' : 'backdrop-blur-xl theme-bg-card'}`} onClick={e => e.stopPropagation()}>
            <div className="flex items-center gap-3 truncate">
               <span className={`text-[10px] font-black uppercase tracking-wider truncate px-3 py-1.5 rounded-lg border theme-border ${theme === 'dark' ? 'bg-slate-950 text-white' : 'bg-white text-slate-900'}`}>{images[selectedIndex].file.name}</span>
               {isFullScreen && <span className="text-[10px] font-bold text-indigo-400 animate-pulse tracking-widest bg-indigo-500/10 px-2 py-1 rounded">LIVE FULLSCREEN</span>}
            </div>
            <div className="flex items-center gap-3">
              {images[selectedIndex].resultUrl && (
                <button 
                  onClick={(e) => { e.stopPropagation(); setShowOriginalInModal(!showOriginalInModal); }} 
                  className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-[0.1em] transition-all border ${showOriginalInModal ? 'bg-indigo-600 text-white border-indigo-400' : 'theme-bg-app theme-text-main theme-border hover:bg-indigo-500/10'}`}
                  title={showOriginalInModal ? t.result : t.original}
                >
                  {showOriginalInModal ? t.result : t.original}
                </button>
              )}
              <button 
                onClick={(e) => { e.stopPropagation(); exportSingle(images[selectedIndex!]); }} 
                className="px-4 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl text-[10px] font-black uppercase tracking-[0.1em] disabled:opacity-50 transition-colors border border-indigo-400 shadow-lg"
                disabled={!images[selectedIndex].resultUrl}
                title={t.export}
              >
                {t.export}
              </button>
              <div className="w-px h-6 theme-border mx-1"></div>
              <button 
                onClick={() => setSelectedIndex(null)} 
                className="p-2 theme-text-main hover:text-rose-400 transition-colors"
                title={t.close}
              >
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>
          </div>

          {/* Main Viewport */}
          <div className="flex-1 flex items-center justify-center p-4 md:p-12 overflow-hidden" onClick={e => e.stopPropagation()}>
            <div className="relative transition-transform duration-100 ease-out" style={{ transform: `scale(${zoomLevel}) translate(${panOffset.x / zoomLevel}px, ${panOffset.y / zoomLevel}px)` }}>
              <img 
                src={showOriginalInModal || !images[selectedIndex].resultUrl ? images[selectedIndex].previewUrl : images[selectedIndex].resultUrl} 
                alt="Restored Preview" 
                className={`max-w-full max-h-[85vh] object-contain rounded-2xl md:rounded-[2rem] border theme-border ${theme === 'dark' ? 'shadow-[0_50px_100px_-20px_rgba(0,0,0,0.8)]' : 'shadow-2xl'}`} 
              />
              {images[selectedIndex].status === 'error' && (
                <div className="absolute inset-0 flex flex-col items-center justify-center bg-rose-950/60 backdrop-blur-md rounded-2xl md:rounded-[2rem] p-8 text-center border-2 border-rose-500/20">
                   <div className="w-20 h-20 bg-rose-500/30 rounded-full flex items-center justify-center mb-6 border border-rose-500/50 shadow-2xl animate-bounce">
                      <svg className="w-10 h-10 text-rose-300" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                   </div>
                   <h4 className="text-2xl font-black text-rose-300 mb-3 uppercase tracking-widest drop-shadow-lg">{t.error}</h4>
                   <p className="text-slate-100 text-sm max-w-lg bg-black/60 p-6 rounded-2xl border border-white/10 shadow-3xl font-mono leading-relaxed backdrop-blur-lg">
                     {images[selectedIndex].error || "A processing error occurred. Please check your internet or try a different image format."}
                   </p>
                </div>
              )}
            </div>
          </div>

          {/* Controls Island */}
          <div className={`absolute bottom-8 left-1/2 -translate-x-1/2 z-50 flex flex-col items-center gap-5 transition-all duration-500 ${isFullScreen ? 'bottom-12 scale-110' : ''}`} onClick={e => e.stopPropagation()}>
            <div className={`flex items-center gap-6 px-8 py-5 rounded-[2.5rem] border shadow-3xl transition-all duration-500 ${theme === 'dark' ? 'bg-slate-900/80 border-white/10 backdrop-blur-xl' : 'bg-white/90 border-slate-200 backdrop-blur-xl'}`}>
              <button 
                onClick={() => setZoomLevel(prev => Math.max(prev - 0.25, 1))} 
                className={`p-4 rounded-2xl border transition-all shadow-lg active:scale-90 ${theme === 'dark' ? 'bg-slate-800 text-slate-300 hover:bg-indigo-600 hover:text-white border-white/5' : 'bg-slate-100 text-slate-700 hover:bg-indigo-500 hover:text-white border-slate-200'}`}
                title={t.zoomOut}
              >
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M20 12H4" /></svg>
              </button>

              <div className="flex flex-col items-center gap-2 min-w-[140px]">
                 <input 
                   type="range" 
                   min="1" 
                   max="8" 
                   step="0.01" 
                   value={zoomLevel} 
                   onChange={(e) => setZoomLevel(parseFloat(e.target.value))} 
                   className="w-full accent-indigo-400 h-2 rounded-full cursor-pointer hover:accent-indigo-300 transition-all shadow-inner" 
                   title={t.zoomLevel}
                 />
                 <span className={`text-[10px] font-black uppercase tracking-widest ${theme === 'dark' ? 'text-indigo-200' : 'text-indigo-600'}`}>{t.zoomLevel}: {Math.round(zoomLevel * 100)}%</span>
              </div>

              <button 
                onClick={() => setZoomLevel(prev => Math.min(prev + 0.25, 8))} 
                className={`p-4 rounded-2xl border transition-all shadow-lg active:scale-90 ${theme === 'dark' ? 'bg-slate-800 text-slate-300 hover:bg-indigo-600 hover:text-white border-white/5' : 'bg-slate-100 text-slate-700 hover:bg-indigo-500 hover:text-white border-slate-200'}`}
                title={t.zoomIn}
              >
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 6v6m0 0v6m0-6h6m-6 0H6" /></svg>
              </button>

              <div className="w-px h-10 theme-border hidden sm:block"></div>

              <button 
                onClick={toggleFullScreen}
                className={`p-4 rounded-2xl border transition-all hidden sm:block shadow-lg active:scale-95 ${theme === 'dark' ? 'bg-slate-800 text-slate-300 hover:bg-slate-700 border-white/10' : 'bg-slate-100 text-slate-700 hover:bg-slate-200 border-slate-200'} ${isFullScreen ? 'ring-2 ring-indigo-500' : ''}`}
                title={t.fullScreen}
              >
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                   <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" />
                </svg>
              </button>
            </div>

            <button 
              onClick={resetView} 
              className={`px-6 py-2.5 rounded-full text-[10px] font-black uppercase tracking-[0.2em] transition-all shadow-2xl border ${theme === 'dark' ? 'bg-slate-950/80 text-indigo-400 border-white/5 hover:text-indigo-200' : 'bg-white text-indigo-600 border-slate-200 hover:bg-slate-50'}`}
              title={t.resetView}
            >
              {t.resetView}
            </button>
          </div>
        </div>
      )}

      <footer className="py-16 text-center opacity-40">
        <p className="text-[10px] font-black uppercase tracking-[0.5em] mb-3">Powered by Gemini 2.5 Restoration Engine</p>
        <p className="text-[10px] font-black uppercase tracking-[0.3em] text-indigo-400">© 2026 ChromaRestore Pro Systems</p>
      </footer>
    </div>
  );
};

export default App;

import React from 'react';
import { ImageItem, Translation } from '../types';

interface ImageCardProps {
  item: ImageItem;
  t: Translation;
  theme: 'dark' | 'light';
  onRemove: (id: string) => void;
  onSelect: (item: ImageItem) => void;
  onShare: (item: ImageItem) => void;
}

export const ImageCard: React.FC<ImageCardProps> = ({ item, t, theme, onRemove, onSelect, onShare }) => {
  const statusColors = {
    pending: theme === 'dark' ? 'bg-slate-600' : 'bg-slate-400',
    processing: 'bg-indigo-400 animate-pulse',
    completed: 'bg-emerald-500',
    error: 'bg-rose-500'
  };

  const statusLabel = t[item.status as keyof Translation] || item.status;
  const errorTooltip = item.error ? `${t.error}: ${item.error}` : t.error;

  return (
    <div className={`relative group rounded-2xl overflow-hidden shadow-sm hover:shadow-2xl border transition-all duration-300 ease-out hover:scale-[1.02] theme-border theme-bg-card`}>
      <div 
        className={`aspect-square relative overflow-hidden cursor-pointer ${theme === 'dark' ? 'bg-slate-950' : 'bg-slate-100'}`}
        onClick={() => onSelect(item)}
      >
        <img 
          src={item.previewUrl} 
          alt={item.file.name} 
          className={`w-full h-full object-cover transition-all duration-700 ${item.status === 'processing' ? 'scale-110 blur-md opacity-40' : 'scale-100 blur-0'}`}
        />

        {item.status === 'processing' && (
          <div className="absolute inset-0 flex items-center justify-center bg-indigo-950/20 backdrop-blur-[2px]">
            <div className="w-10 h-10 border-4 border-indigo-500/20 border-t-indigo-500 rounded-full animate-spin"></div>
          </div>
        )}

        {/* Status Dot Badge (Top Corner) */}
        <div 
          className={`absolute top-3 right-3 w-3 h-3 rounded-full border-2 shadow-xl z-20 ${statusColors[item.status]} ${theme === 'dark' ? 'border-slate-900' : 'border-white'}`} 
          title={item.status === 'error' ? errorTooltip : statusLabel} 
        />

        {item.status === 'error' && (
          <div className="absolute inset-0 flex items-center justify-center bg-rose-500/20 backdrop-blur-[1px] p-4 text-center">
            <span 
              className={`text-[10px] font-black uppercase tracking-widest px-2 py-1 rounded-md shadow-lg cursor-help ${theme === 'dark' ? 'bg-slate-950/80 text-rose-400' : 'bg-white/90 text-rose-600'}`}
              title={errorTooltip}
            >
              {t.error}
            </span>
          </div>
        )}
      </div>

      <div className={`p-3 flex items-center justify-between transition-colors theme-bg-card`}>
        <div className="flex items-center gap-2 truncate max-w-[65%]">
          <div 
            className={`w-2 h-2 rounded-full flex-shrink-0 ${statusColors[item.status]}`} 
            title={item.status === 'error' ? errorTooltip : statusLabel}
          />
          <p className={`text-[10px] font-bold truncate tracking-tight theme-text-muted`}>
            {item.file.name}
          </p>
        </div>
        <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
          <button 
            onClick={(e) => { e.stopPropagation(); onShare(item); }} 
            className={`p-1.5 rounded-lg transition-all ${theme === 'dark' ? 'hover:bg-indigo-500/20 text-indigo-400' : 'hover:bg-indigo-50 text-indigo-600'}`}
            title={t.share}
            aria-label={t.share}
          >
            <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z" /></svg>
          </button>
          <button 
            onClick={(e) => { e.stopPropagation(); onRemove(item.id); }} 
            className={`p-1.5 rounded-lg transition-all ${theme === 'dark' ? 'hover:bg-rose-500/20 text-rose-500' : 'hover:bg-rose-50 text-rose-600'}`}
            title={t.remove}
            aria-label={t.remove}
          >
            <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Language, ImageItem } from './types';
import { translations } from './i18n';
import { processImageWithGemini, fileToBase64 } from './services/geminiService';
import { ImageCard } from './components/ImageCard';
import { AdPlaceholder } from './components/AdPlaceholder';

const INITIAL_SUGGESTIONS = ['Personal Photos', 'Family Heritage', 'Travel 2024', 'Work Projects', 'Client Deliverables'];

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('en');
  const [theme, setTheme] = useState<'dark' | 'light'>(() => {
    return (localStorage.getItem('chroma-theme') as 'dark' | 'light') || 'dark';
  });
  const [images, setImages] = useState<ImageItem[]>([]);
  const [targetLabel, setTargetLabel] = useState('');
  const [usedLabels, setUsedLabels] = useState<string[]>(INITIAL_SUGGESTIONS);
  const [searchQuery, setSearchQuery] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const [zoomLevel, setZoomLevel] = useState(1);
  const [panOffset, setPanOffset] = useState({ x: 0, y: 0 });
  const [isFullScreen, setIsFullScreen] = useState(false);
  const [showOriginalInModal, setShowOriginalInModal] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const modalRef = useRef<HTMLDivElement>(null);
  const t = translations[lang];
  const isRtl = lang === 'he';

  useEffect(() => {
    localStorage.setItem('chroma-theme', theme);
    document.documentElement.className = theme;
  }, [theme]);

  const filteredImages = images.filter(img => 
    img.file.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const processNextPending = useCallback(async () => {
    const nextItem = images.find(img => img.status === 'pending');
    if (!nextItem || isProcessing) return;

    setIsProcessing(true);
    setImages(prev => prev.map(img => 
      img.id === nextItem.id ? { ...img, status: 'processing', error: undefined } : img
    ));

    try {
      const base64 = await fileToBase64(nextItem.file);
      const resultUrl = await processImageWithGemini(base64, nextItem.file.type);
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'completed', resultUrl, destination: targetLabel } : img
      ));

      if (targetLabel.trim() && !usedLabels.includes(targetLabel.trim())) {
        setUsedLabels(prev => [targetLabel.trim(), ...prev].slice(0, 15));
      }
    } catch (err: any) {
      const errorMessage = err?.message || String(err);
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'error', error: errorMessage } : img
      ));
    } finally {
      setIsProcessing(false);
    }
  }, [images, isProcessing, targetLabel, usedLabels]);

  useEffect(() => {
    processNextPending();
  }, [images, processNextPending]);

  const handleFiles = (files: FileList | null) => {
    if (!files) return;
    const newImages: ImageItem[] = Array.from(files).map(file => ({
      id: Math.random().toString(36).substr(2, 9),
      file,
      previewUrl: URL.createObjectURL(file),
      status: 'pending'
    }));
    setImages(prev => [...prev, ...newImages]);
  };

  const handleShare = (item: ImageItem) => {
    const url = item.resultUrl || item.previewUrl;
    navigator.clipboard.writeText(url).then(() => {
      alert(t.shareSuccess);
    });
  };

  const resetView = useCallback(() => {
    setZoomLevel(1);
    setPanOffset({ x: 0, y: 0 });
  }, []);

  const handleWheel = useCallback((e: React.WheelEvent) => {
    if (selectedIndex === null) return;
    const delta = -e.deltaY;
    const factor = 0.001;
    setZoomLevel(prev => Math.min(Math.max(prev + delta * factor * prev, 1), 8));
  }, [selectedIndex]);

  const toggleFullScreen = useCallback(() => {
    if (!document.fullscreenElement) {
      modalRef.current?.requestFullscreen().catch(err => {
        console.error(`Fullscreen failed: ${err.message}`);
      });
      setIsFullScreen(true);
    } else {
      document.exitFullscreen();
      setIsFullScreen(false);
    }
  }, []);

  const toggleTheme = () => setTheme(prev => prev === 'dark' ? 'light' : 'dark');

  useEffect(() => {
    const onFsChange = () => setIsFullScreen(!!document.fullscreenElement);
    document.addEventListener('fullscreenchange', onFsChange);
    return () => document.removeEventListener('fullscreenchange', onFsChange);
  }, []);

  const handlePickFolder = async () => {
    if ('showDirectoryPicker' in window) {
      try {
        const handle = await (window as any).showDirectoryPicker();
        setTargetLabel(handle.name);
      } catch (e) {
        console.debug('Folder picker cancelled', e);
      }
    } else {
      alert('Manual folder typing is required on this browser.');
    }
  };

  const exportSingle = (img: ImageItem) => {
    if (!img.resultUrl) return;
    const prefix = targetLabel.trim() || 'colorized';
    const link = document.createElement('a');
    link.href = img.resultUrl;
    link.download = `${prefix}_${img.file.name}`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const exportFiltered = () => {
    if (filteredImages.length === 0) return;
    const prefix = targetLabel || 'export';
    filteredImages.forEach((img, idx) => {
      if (img.resultUrl) {
        setTimeout(() => {
          const link = document.createElement('a');
          link.href = img.resultUrl!;
          link.download = `${prefix}_${img.file.name}`;
          link.click();
        }, idx * 150);
      }
    });
  };

  const handleKeyDown = useCallback((e: KeyboardEvent) => {
    if (selectedIndex === null) return;
    if (e.key === 'f' || e.key === 'F') { e.preventDefault(); toggleFullScreen(); }
    else if (e.key === '+' || e.key === '=') { e.preventDefault(); setZoomLevel(prev => Math.min(prev + 0.2, 8)); }
    else if (e.key === '-' || e.key === '_') { e.preventDefault(); setZoomLevel(prev => Math.max(prev - 0.2, 1)); }
    else if (e.key === '0') { e.preventDefault(); resetView(); }
    else if (e.key === 'Escape') {
      if (document.fullscreenElement) document.exitFullscreen();
      else setSelectedIndex(null);
    }
  }, [selectedIndex, toggleFullScreen, resetView]);

  useEffect(() => {
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleKeyDown]);

  return (
    <div className={`min-h-screen ${theme} theme-bg-app theme-text-main font-sans lang-${lang} ${isRtl ? 'rtl' : 'ltr'}`} dir={isRtl ? 'rtl' : 'ltr'}>
      <header className={`sticky top-0 z-40 backdrop-blur-xl border-b theme-border shadow-2xl ${theme === 'dark' ? 'bg-slate-900/90' : 'bg-white/90'}`}>
        <div className="max-w-6xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <span className="text-2xl drop-shadow-[0_0_10px_rgba(99,102,241,0.5)]" title={t.title}>🎨</span>
            <h1 className="text-lg font-black tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-indigo-500 to-indigo-300">{t.title}</h1>
          </div>
          <div className="flex items-center gap-3">
            <button 
              onClick={toggleTheme}
              className={`p-2 rounded-xl transition-all border theme-border ${theme === 'dark' ? 'bg-slate-800 text-yellow-400 hover:bg-slate-700' : 'bg-slate-100 text-slate-700 hover:bg-slate-200'}`}
              title={theme === 'dark' ? 'Switch to Light Mode' : 'Switch to Dark Mode'}
            >
              {theme === 'dark' ? (
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m9-9h-1M4 9H3m15.364-6.364l-.707.707M6.343 17.657l-.707.707m12.728 0l-.707-.707M6.343 6.343l-.707-.707M12 8a4 4 0 100 8 4 4 0 000-8z" /></svg>
              ) : (
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" /></svg>
              )}
            </button>
            <select 
              value={lang} 
              onChange={(e) => setLang(e.target.value as Language)}
              title={t.languageSelect}
              className={`border theme-border rounded-xl px-3 py-1.5 text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-500 transition-all cursor-pointer ${theme === 'dark' ? 'bg-slate-800 text-slate-100' : 'bg-slate-100 text-slate-900'}`}
            >
              <option value="en">English</option>
              <option value="he">עברית</option>
              <option value="zh">中文</option>
              <option value="hi">हिन्दी</option>
              <option value="de">Deutsch</option>
              <option value="es">Español</option>
              <option value="fr">Français</option>
            </select>
          </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-6 py-12">
        <div className="text-center mb-12">
          <h2 className="text-3xl md:text-5xl font-extrabold mb-4 tracking-tight theme-text-main">{t.subtitle}</h2>
          <div className="flex items-center justify-center gap-2">
            <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
            <p className="theme-text-muted max-w-xl text-sm font-medium">{t.offlineReady}</p>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
          <aside className="lg:col-span-1 space-y-6">
            <div className={`p-6 rounded-[2.5rem] shadow-2xl border theme-border theme-bg-card`}>
              <label className="block text-[10px] font-black uppercase tracking-[0.2em] theme-text-muted mb-3 ml-1">{t.targetFolder}</label>
              <div className="relative group">
                <input 
                  type="text" 
                  list="labels-list"
                  value={targetLabel} 
                  onChange={(e) => setTargetLabel(e.target.value)}
                  placeholder={t.targetFolderPlaceholder} 
                  className={`w-full pl-4 pr-10 py-3.5 border theme-border rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all text-sm font-medium theme-text-main ${theme === 'dark' ? 'bg-slate-950 placeholder:text-slate-700' : 'bg-slate-50 placeholder:text-slate-400'}`} 
                  title={t.targetFolder}
                />
                <datalist id="labels-list">
                  {usedLabels.map(s => <option key={s} value={s} />)}
                </datalist>
                <button 
                  onClick={handlePickFolder}
                  title={t.pickFolder}
                  className="absolute right-3 top-1/2 -translate-y-1/2 theme-text-muted hover:text-indigo-400 transition-colors"
                >
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z" /></svg>
                </button>
              </div>
              <div className="mt-8 space-y-3">
                <button 
                  onClick={exportFiltered} 
                  disabled={filteredImages.length === 0} 
                  className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-800 disabled:text-slate-500 disabled:opacity-50 text-white font-bold rounded-2xl shadow-xl transition-all flex items-center justify-center gap-2 text-sm"
                  title={t.downloadAll}
                >
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                  {t.downloadAll}
                </button>
                <button 
                  onClick={() => setImages([])} 
                  className="w-full py-3 theme-text-muted hover:text-rose-400 text-[10px] font-black uppercase tracking-[0.2em] transition-colors"
                  title={t.clearBtn}
                >
                  {t.clearBtn}
                </button>
              </div>
            </div>
            <AdPlaceholder label={t.adPlaceholder} />
          </aside>

          <section className="lg:col-span-3 space-y-6">
            <div 
              onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
              onDragLeave={() => setIsDragging(false)}
              onDrop={(e) => { e.preventDefault(); setIsDragging(false); handleFiles(e.dataTransfer.files); }}
              onClick={() => fileInputRef.current?.click()}
              className={`group border-2 border-dashed rounded-[3rem] p-14 text-center cursor-pointer transition-all duration-500 ${isDragging ? 'drag-pulsing' : `theme-border hover:border-indigo-500/50 ${theme === 'dark' ? 'bg-slate-900/50 hover:bg-slate-900' : 'bg-white hover:bg-slate-50 shadow-lg'}`}`}
              title={t.dropzoneTitle}
            >
              <input type="file" multiple accept="image/*" className="hidden" ref={fileInputRef} onChange={(e) => handleFiles(e.target.files)} />
              <div className={`w-16 h-16 bg-indigo-500/10 rounded-[1.5rem] flex items-center justify-center mx-auto mb-6 transition-all group-hover:scale-110 ${isDragging ? 'scale-125 drag-content-pulsing' : ''}`}>
                <svg className="w-8 h-8 text-indigo-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>
              </div>
              <h3 className={`text-2xl font-black mb-1 theme-text-main transition-all ${isDragging ? 'drag-content-pulsing' : ''}`}>{t.dropzoneTitle}</h3>
              <p className={`theme-text-muted text-[10px] font-black uppercase tracking-[0.2em] transition-all ${isDragging ? 'drag-content-pulsing' : ''}`}>{t.dropzoneSub}</p>
            </div>

            {images.length > 0 && (
              <div className="relative">
                <input 
                  type="text" 
                  value={searchQuery} 
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder={t.searchPlaceholder}
                  className={`w-full pl-11 pr-4 py-4 border theme-border rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm theme-text-main theme-bg-card`} 
                  title={t.search}
                />
                <svg className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 theme-text-muted" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
              </div>
            )}

            <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-3 xl:grid-cols-4 gap-6">
              {filteredImages.map((img) => (
                <ImageCard 
                  key={img.id} 
                  item={img} 
                  t={t} 
                  theme={theme}
                  onRemove={(id) => setImages(prev => prev.filter(i => i.id !== id))} 
                  onSelect={(item) => { setSelectedIndex(images.indexOf(item)); setShowOriginalInModal(false); resetView(); }} 
                  onShare={handleShare} 
                />
              ))}
            </div>
          </section>
        </div>
      </main>

      {selectedIndex !== null && images[selectedIndex] && (
        <div 
          ref={modalRef} 
          className={`fixed inset-0 z-50 flex flex-col backdrop-blur-3xl animate-in fade-in duration-300 overflow-hidden ${theme === 'dark' ? 'bg-slate-950/98' : 'bg-slate-50/95'}`} 
          onClick={() => setSelectedIndex(null)}
          onWheel={handleWheel}
        >
          {/* Header Bar - Distinct & Sticky */}
          <div className={`absolute top-0 left-0 right-0 z-50 h-16 px-6 flex items-center justify-between border-b theme-border transition-all ${isFullScreen ? 'opacity-40 hover:opacity-100 bg-slate-900/30' : 'backdrop-blur-xl theme-bg-card'}`} onClick={e => e.stopPropagation()}>
            <div className="flex items-center gap-3 truncate">
               <span className={`text-[10px] font-black uppercase tracking-wider truncate px-3 py-1.5 rounded-lg border theme-border ${theme === 'dark' ? 'bg-slate-950 text-white' : 'bg-white text-slate-900'}`}>{images[selectedIndex].file.name}</span>
               {isFullScreen && <span className="text-[10px] font-bold text-indigo-400 animate-pulse tracking-widest bg-indigo-500/10 px-2 py-1 rounded">LIVE FULLSCREEN</span>}
            </div>
            <div className="flex items-center gap-3">
              {images[selectedIndex].resultUrl && (
                <button 
                  onClick={(e) => { e.stopPropagation(); setShowOriginalInModal(!showOriginalInModal); }} 
                  className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-[0.1em] transition-all border ${showOriginalInModal ? 'bg-indigo-600 text-white border-indigo-400' : 'theme-bg-app theme-text-main theme-border hover:bg-indigo-500/10'}`}
                  title={showOriginalInModal ? t.result : t.original}
                >
                  {showOriginalInModal ? t.result : t.original}
                </button>
              )}
              <button 
                onClick={(e) => { e.stopPropagation(); exportSingle(images[selectedIndex!]); }} 
                className="px-4 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl text-[10px] font-black uppercase tracking-[0.1em] disabled:opacity-50 transition-colors border border-indigo-400 shadow-lg"
                disabled={!images[selectedIndex].resultUrl}
                title={t.export}
              >
                {t.export}
              </button>
              <div className="w-px h-6 theme-border mx-1"></div>
              <button 
                onClick={() => setSelectedIndex(null)} 
                className="p-2 theme-text-main hover:text-rose-400 transition-colors"
                title={t.close}
              >
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>
          </div>

          {/* Main Viewport */}
          <div className="flex-1 flex items-center justify-center p-4 md:p-12 overflow-hidden" onClick={e => e.stopPropagation()}>
            <div className="relative transition-transform duration-100 ease-out" style={{ transform: `scale(${zoomLevel}) translate(${panOffset.x / zoomLevel}px, ${panOffset.y / zoomLevel}px)` }}>
              <img 
                src={showOriginalInModal || !images[selectedIndex].resultUrl ? images[selectedIndex].previewUrl : images[selectedIndex].resultUrl} 
                alt="Restored Preview" 
                className={`max-w-full max-h-[85vh] object-contain rounded-2xl md:rounded-[2rem] border theme-border ${theme === 'dark' ? 'shadow-[0_50px_100px_-20px_rgba(0,0,0,0.8)]' : 'shadow-2xl'}`} 
              />
              {images[selectedIndex].status === 'error' && (
                <div className="absolute inset-0 flex flex-col items-center justify-center bg-rose-950/60 backdrop-blur-md rounded-2xl md:rounded-[2rem] p-8 text-center border-2 border-rose-500/20">
                   <div className="w-20 h-20 bg-rose-500/30 rounded-full flex items-center justify-center mb-6 border border-rose-500/50 shadow-2xl animate-bounce">
                      <svg className="w-10 h-10 text-rose-300" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                   </div>
                   <h4 className="text-2xl font-black text-rose-300 mb-3 uppercase tracking-widest drop-shadow-lg">{t.error}</h4>
                   <p className="text-slate-100 text-sm max-w-lg bg-black/60 p-6 rounded-2xl border border-white/10 shadow-3xl font-mono leading-relaxed backdrop-blur-lg">
                     {images[selectedIndex].error || "A processing error occurred. Please check your internet or try a different image format."}
                   </p>
                </div>
              )}
            </div>
          </div>

          {/* Controls Island */}
          <div className={`absolute bottom-8 left-1/2 -translate-x-1/2 z-50 flex flex-col items-center gap-5 transition-all duration-500 ${isFullScreen ? 'bottom-12 scale-110' : ''}`} onClick={e => e.stopPropagation()}>
            <div className={`flex items-center gap-6 px-8 py-5 rounded-[2.5rem] border shadow-3xl transition-all duration-500 ${theme === 'dark' ? 'bg-slate-900/80 border-white/10 backdrop-blur-xl' : 'bg-white/90 border-slate-200 backdrop-blur-xl'}`}>
              <button 
                onClick={() => setZoomLevel(prev => Math.max(prev - 0.25, 1))} 
                className={`p-4 rounded-2xl border transition-all shadow-lg active:scale-90 ${theme === 'dark' ? 'bg-slate-800 text-slate-300 hover:bg-indigo-600 hover:text-white border-white/5' : 'bg-slate-100 text-slate-700 hover:bg-indigo-500 hover:text-white border-slate-200'}`}
                title={t.zoomOut}
              >
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M20 12H4" /></svg>
              </button>

              <div className="flex flex-col items-center gap-2 min-w-[140px]">
                 <input 
                   type="range" 
                   min="1" 
                   max="8" 
                   step="0.01" 
                   value={zoomLevel} 
                   onChange={(e) => setZoomLevel(parseFloat(e.target.value))} 
                   className="w-full accent-indigo-400 h-2 rounded-full cursor-pointer hover:accent-indigo-300 transition-all shadow-inner" 
                   title={t.zoomLevel}
                 />
                 <span className={`text-[10px] font-black uppercase tracking-widest ${theme === 'dark' ? 'text-indigo-200' : 'text-indigo-600'}`}>{t.zoomLevel}: {Math.round(zoomLevel * 100)}%</span>
              </div>

              <button 
                onClick={() => setZoomLevel(prev => Math.min(prev + 0.25, 8))} 
                className={`p-4 rounded-2xl border transition-all shadow-lg active:scale-90 ${theme === 'dark' ? 'bg-slate-800 text-slate-300 hover:bg-indigo-600 hover:text-white border-white/5' : 'bg-slate-100 text-slate-700 hover:bg-indigo-500 hover:text-white border-slate-200'}`}
                title={t.zoomIn}
              >
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 6v6m0 0v6m0-6h6m-6 0H6" /></svg>
              </button>

              <div className="w-px h-10 theme-border hidden sm:block"></div>

              <button 
                onClick={toggleFullScreen}
                className={`p-4 rounded-2xl border transition-all hidden sm:block shadow-lg active:scale-95 ${theme === 'dark' ? 'bg-slate-800 text-slate-300 hover:bg-slate-700 border-white/10' : 'bg-slate-100 text-slate-700 hover:bg-slate-200 border-slate-200'} ${isFullScreen ? 'ring-2 ring-indigo-500' : ''}`}
                title={t.fullScreen}
              >
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                   <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" />
                </svg>
              </button>
            </div>

            <button 
              onClick={resetView} 
              className={`px-6 py-2.5 rounded-full text-[10px] font-black uppercase tracking-[0.2em] transition-all shadow-2xl border ${theme === 'dark' ? 'bg-slate-950/80 text-indigo-400 border-white/5 hover:text-indigo-200' : 'bg-white text-indigo-600 border-slate-200 hover:bg-slate-50'}`}
              title={t.resetView}
            >
              {t.resetView}
            </button>
          </div>
        </div>
      )}

      <footer className="py-16 text-center opacity-40">
        <p className="text-[10px] font-black uppercase tracking-[0.5em] mb-3">Powered by Gemini 2.5 Restoration Engine</p>
        <p className="text-[10px] font-black uppercase tracking-[0.3em] text-indigo-400">© 2026 ChromaRestore Pro Systems</p>
      </footer>
    </div>
  );
};

export default App;

@import url('https://cdnjs.cloudflare.com/ajax/libs/tailwindcss/2.2.19/tailwind.min.css');

:root { 
  --primary: #6366f1; 
  --transition-speed: 0.3s;
}

/* Base Theme Variables */
.dark {
  --bg-app: #020617;
  --bg-header: rgba(15, 23, 42, 0.9);
  --bg-card: #0f172a;
  --bg-input: #020617;
  --text-main: #f1f5f9;
  --text-muted: #94a3b8;
  --border-main: #1e293b;
  --shadow-main: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

.light {
  --bg-app: #f8fafc;
  --bg-header: rgba(255, 255, 255, 0.9);
  --bg-card: #ffffff;
  --bg-input: #ffffff;
  --text-main: #0f172a;
  --text-muted: #475569;
  --border-main: #e2e8f0;
  --shadow-main: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
}

body {
  font-family: 'Plus Jakarta Sans', sans-serif;
  transition: background-color var(--transition-speed), color var(--transition-speed);
  overflow-x: hidden;
}

/* RTL Support */
[dir="rtl"] { font-family: 'Heebo', sans-serif; }
.lang-zh { font-family: 'Noto Sans SC', sans-serif; }
.lang-hi { font-family: 'Noto Sans Devanagari', sans-serif; }

/* Theme Utility Overrides */
.theme-bg-app { background-color: var(--bg-app); }
.theme-bg-card { background-color: var(--bg-card); }
.theme-text-main { color: var(--text-main); }
.theme-text-muted { color: var(--text-muted); }
.theme-border { border-color: var(--border-main); }

/* Animations */
@keyframes pulse-border {
  0%, 100% { 
    border-color: rgba(99, 102, 241, 0.3); 
    box-shadow: 0 0 0 0 rgba(99, 102, 241, 0); 
  }
  50% { 
    border-color: rgba(99, 102, 241, 0.8); 
    box-shadow: 0 0 15px 0 rgba(99, 102, 241, 0.15); 
  }
}

@keyframes pulse-content {
  0%, 100% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.015); opacity: 0.9; }
}

@keyframes shimmer {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(100%); }
}

.drag-pulsing {
  animation: pulse-border 2s infinite ease-in-out;
  background-color: rgba(99, 102, 241, 0.06) !important;
  border-style: solid !important;
}

.drag-content-pulsing { 
  animation: pulse-content 2s infinite ease-in-out; 
}

.shimmer-effect::after {
  content: "";
  position: absolute;
  top: 0; left: 0; width: 100%; height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.1), transparent);
  animation: shimmer 2s infinite;
}

/* Scrollbar */
::-webkit-scrollbar { width: 10px; }
::-webkit-scrollbar-track { background: var(--bg-app); }
::-webkit-scrollbar-thumb { background: var(--border-main); border-radius: 5px; }
::-webkit-scrollbar-thumb:hover { background: var(--text-muted); }

.backdrop-blur-xl { backdrop-filter: blur(24px); }
.backdrop-blur-3xl { backdrop-filter: blur(64px); }

/* Theme Transition Helper */
* {
  transition: background-color var(--transition-speed) ease, border-color var(--transition-speed) ease, color var(--transition-speed) ease, box-shadow var(--transition-speed) ease;
}

import React from 'react';
import { ImageItem, Translation } from '../types';

interface ImageCardProps {
  item: ImageItem;
  t: Translation;
  theme: 'dark' | 'light';
  onRemove: (id: string) => void;
  onSelect: (item: ImageItem) => void;
  onShare: (item: ImageItem) => void;
}

export const ImageCard: React.FC<ImageCardProps> = ({ item, t, theme, onRemove, onSelect, onShare }) => {
  const statusColors = {
    pending: theme === 'dark' ? 'bg-slate-600' : 'bg-slate-400',
    processing: 'bg-indigo-400 animate-pulse',
    completed: 'bg-emerald-500',
    error: 'bg-rose-500'
  };

  const statusLabel = t[item.status as keyof Translation] || item.status;
  const errorTooltip = item.error ? `${t.error}: ${item.error}` : t.error;

  return (
    <div className={`relative group rounded-2xl overflow-hidden shadow-sm hover:shadow-2xl border transition-all duration-300 ease-out hover:scale-[1.02] theme-border theme-bg-card`}>
      <div 
        className={`aspect-square relative overflow-hidden cursor-pointer ${theme === 'dark' ? 'bg-slate-950' : 'bg-slate-100'}`}
        onClick={() => onSelect(item)}
      >
        <img 
          src={item.previewUrl} 
          alt={item.file.name} 
          className={`w-full h-full object-cover transition-all duration-700 ${item.status === 'processing' ? 'scale-110 blur-md opacity-40' : 'scale-100 blur-0'}`}
        />

        {item.status === 'processing' && (
          <div className="absolute inset-0 flex items-center justify-center bg-indigo-950/20 backdrop-blur-[2px]">
            <div className="w-10 h-10 border-4 border-indigo-500/20 border-t-indigo-500 rounded-full animate-spin"></div>
          </div>
        )}

        {/* Status Dot Badge (Top Corner) */}
        <div 
          className={`absolute top-3 right-3 w-3 h-3 rounded-full border-2 shadow-xl z-20 ${statusColors[item.status]} ${theme === 'dark' ? 'border-slate-900' : 'border-white'}`} 
          title={item.status === 'error' ? errorTooltip : statusLabel} 
        />

        {item.status === 'error' && (
          <div className="absolute inset-0 flex items-center justify-center bg-rose-500/20 backdrop-blur-[1px] p-4 text-center">
            <span 
              className={`text-[10px] font-black uppercase tracking-widest px-2 py-1 rounded-md shadow-lg cursor-help ${theme === 'dark' ? 'bg-slate-950/80 text-rose-400' : 'bg-white/90 text-rose-600'}`}
              title={errorTooltip}
            >
              {t.error}
            </span>
          </div>
        )}
      </div>

      <div className={`p-3 flex items-center justify-between transition-colors theme-bg-card`}>
        <div className="flex items-center gap-2 truncate max-w-[50%]">
          <div 
            className={`w-2 h-2 rounded-full flex-shrink-0 ${statusColors[item.status]}`} 
            title={item.status === 'error' ? errorTooltip : statusLabel}
          />
          <p className={`text-[10px] font-bold truncate tracking-tight theme-text-muted`}>
            {item.file.name}
          </p>
        </div>
        <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
          <button 
            onClick={(e) => { e.stopPropagation(); onSelect(item); }} 
            className={`p-1.5 rounded-lg transition-all ${theme === 'dark' ? 'hover:bg-indigo-500/20 text-indigo-400' : 'hover:bg-indigo-50 text-indigo-600'}`}
            title={t.fullScreen}
            aria-label={t.fullScreen}
          >
            <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" /></svg>
          </button>
          <button 
            onClick={(e) => { e.stopPropagation(); onShare(item); }} 
            className={`p-1.5 rounded-lg transition-all ${theme === 'dark' ? 'hover:bg-indigo-500/20 text-indigo-400' : 'hover:bg-indigo-50 text-indigo-600'}`}
            title={t.share}
            aria-label={t.share}
          >
            <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 105.367-2.684 3 3 0 00-5.367 2.684zm0 9.316a3 3 0 105.368 2.684 3 3 0 00-5.368-2.684z" /></svg>
          </button>
          <button 
            onClick={(e) => { e.stopPropagation(); onRemove(item.id); }} 
            className={`p-1.5 rounded-lg transition-all ${theme === 'dark' ? 'hover:bg-rose-500/20 text-rose-500' : 'hover:bg-rose-50 text-rose-600'}`}
            title={t.remove}
            aria-label={t.remove}
          >
            <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Language, ImageItem } from './types';
import { translations } from './i18n';
import { processImageWithGemini, fileToBase64 } from './services/geminiService';
import { ImageCard } from './components/ImageCard';
import { AdPlaceholder } from './components/AdPlaceholder';

const INITIAL_SUGGESTIONS = ['Personal Photos', 'Family Heritage', 'Travel 2024', 'Work Projects', 'Client Deliverables'];

interface ViewState {
  zoom: number;
  pan: { x: number; y: number };
}

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('en');
  const [theme, setTheme] = useState<'dark' | 'light'>(() => {
    return (localStorage.getItem('chroma-theme') as 'dark' | 'light') || 'dark';
  });
  const [images, setImages] = useState<ImageItem[]>([]);
  const [targetLabel, setTargetLabel] = useState('');
  const [usedLabels, setUsedLabels] = useState<string[]>(INITIAL_SUGGESTIONS);
  const [searchQuery, setSearchQuery] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const [zoomLevel, setZoomLevel] = useState(1);
  const [panOffset, setPanOffset] = useState({ x: 0, y: 0 });
  const [isFullScreen, setIsFullScreen] = useState(false);
  const [showOriginalInModal, setShowOriginalInModal] = useState(false);
  const [viewStates, setViewStates] = useState<Record<string, ViewState>>({});

  const fileInputRef = useRef<HTMLInputElement>(null);
  const modalRef = useRef<HTMLDivElement>(null);
  const isDraggingImage = useRef(false);
  const lastMousePos = useRef({ x: 0, y: 0 });
  const t = translations[lang];
  const isRtl = lang === 'he';

  useEffect(() => {
    localStorage.setItem('chroma-theme', theme);
    document.documentElement.className = theme;
  }, [theme]);

  const filteredImages = images.filter(img => 
    img.file.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  // Sync state back to viewStates map when it changes
  useEffect(() => {
    if (selectedIndex !== null && images[selectedIndex]) {
      const id = images[selectedIndex].id;
      setViewStates(prev => ({
        ...prev,
        [id]: { zoom: zoomLevel, pan: panOffset }
      }));
    }
  }, [zoomLevel, panOffset, selectedIndex, images]);

  const processNextPending = useCallback(async () => {
    const nextItem = images.find(img => img.status === 'pending');
    if (!nextItem || isProcessing) return;

    setIsProcessing(true);
    setImages(prev => prev.map(img => 
      img.id === nextItem.id ? { ...img, status: 'processing', error: undefined } : img
    ));

    try {
      const base64 = await fileToBase64(nextItem.file);
      const resultUrl = await processImageWithGemini(base64, nextItem.file.type);
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'completed', resultUrl, destination: targetLabel } : img
      ));

      if (targetLabel.trim() && !usedLabels.includes(targetLabel.trim())) {
        setUsedLabels(prev => [targetLabel.trim(), ...prev].slice(0, 15));
      }
    } catch (err: any) {
      const errorMessage = err?.message || String(err);
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'error', error: errorMessage } : img
      ));
    } finally {
      setIsProcessing(false);
    }
  }, [images, isProcessing, targetLabel, usedLabels]);

  useEffect(() => {
    processNextPending();
  }, [images, processNextPending]);

  const handleFiles = (files: FileList | null) => {
    if (!files) return;
    const newImages: ImageItem[] = Array.from(files).map(file => ({
      id: Math.random().toString(36).substr(2, 9),
      file,
      previewUrl: URL.createObjectURL(file),
      status: 'pending'
    }));
    setImages(prev => [...prev, ...newImages]);
  };

  const handleShare = (item: ImageItem) => {
    const url = item.resultUrl || item.previewUrl;
    navigator.clipboard.writeText(url).then(() => {
      alert(t.shareSuccess);
    });
  };

  const resetView = useCallback(() => {
    setZoomLevel(1);
    setPanOffset({ x: 0, y: 0 });
  }, []);

  const handleWheel = useCallback((e: React.WheelEvent) => {
    if (selectedIndex === null) return;
    const delta = -e.deltaY;
    const factor = 0.001;
    setZoomLevel(prev => Math.min(Math.max(prev + delta * factor * prev, 1), 8));
  }, [selectedIndex]);

  const handleMouseDown = (e: React.MouseEvent) => {
    if (selectedIndex === null) return;
    isDraggingImage.current = true;
    lastMousePos.current = { x: e.clientX, y: e.clientY };
  };

  const handleMouseMove = useCallback((e: MouseEvent) => {
    if (!isDraggingImage.current) return;
    const dx = e.clientX - lastMousePos.current.x;
    const dy = e.clientY - lastMousePos.current.y;
    setPanOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
    lastMousePos.current = { x: e.clientX, y: e.clientY };
  }, []);

  const handleMouseUp = useCallback(() => {
    isDraggingImage.current = false;
  }, []);

  useEffect(() => {
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [handleMouseMove, handleMouseUp]);

  const toggleFullScreen = useCallback(() => {
    if (!document.fullscreenElement) {
      modalRef.current?.requestFullscreen().catch(err => {
        console.error(`Fullscreen failed: ${err.message}`);
      });
      setIsFullScreen(true);
    } else {
      document.exitFullscreen();
      setIsFullScreen(false);
    }
  }, []);

  const toggleTheme = () => setTheme(prev => prev === 'dark' ? 'light' : 'dark');

  useEffect(() => {
    const onFsChange = () => setIsFullScreen(!!document.fullscreenElement);
    document.addEventListener('fullscreenchange', onFsChange);
    return () => document.removeEventListener('fullscreenchange', onFsChange);
  }, []);

  const handlePickFolder = async () => {
    if ('showDirectoryPicker' in window) {
      try {
        const handle = await (window as any).showDirectoryPicker();
        setTargetLabel(handle.name);
      } catch (e) {
        console.debug('Folder picker cancelled', e);
      }
    } else {
      alert('Manual folder typing is required on this browser.');
    }
  };

  const exportSingle = (img: ImageItem) => {
    if (!img.resultUrl) return;
    const prefix = targetLabel.trim() || 'colorized';
    const link = document.createElement('a');
    link.href = img.resultUrl;
    link.download = `${prefix}_${img.file.name}`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const exportFiltered = () => {
    if (filteredImages.length === 0) return;
    const prefix = targetLabel || 'export';
    filteredImages.forEach((img, idx) => {
      if (img.resultUrl) {
        setTimeout(() => {
          const link = document.createElement('a');
          link.href = img.resultUrl!;
          link.download = `${prefix}_${img.file.name}`;
          link.click();
        }, idx * 150);
      }
    });
  };

  const handleKeyDown = useCallback((e: KeyboardEvent) => {
    if (selectedIndex === null) return;
    if (e.key === 'f' || e.key === 'F') { e.preventDefault(); toggleFullScreen(); }
    else if (e.key === '+' || e.key === '=') { e.preventDefault(); setZoomLevel(prev => Math.min(prev + 0.2, 8)); }
    else if (e.key === '-' || e.key === '_') { e.preventDefault(); setZoomLevel(prev => Math.max(prev - 0.2, 1)); }
    else if (e.key === '0') { e.preventDefault(); resetView(); }
    else if (e.key === 'Escape') {
      if (document.fullscreenElement) document.exitFullscreen();
      else setSelectedIndex(null);
    }
  }, [selectedIndex, toggleFullScreen, resetView]);

  useEffect(() => {
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleKeyDown]);

  const onSelectImage = (item: ImageItem) => {
    const index = images.indexOf(item);
    setSelectedIndex(index);
    setShowOriginalInModal(false);

    // Load preserved view state if available
    const savedState = viewStates[item.id];
    if (savedState) {
      setZoomLevel(savedState.zoom);
      setPanOffset(savedState.pan);
    } else {
      resetView();
    }
  };

  return (
    <div className={`min-h-screen ${theme} theme-bg-app theme-text-main font-sans lang-${lang} ${isRtl ? 'rtl' : 'ltr'}`} dir={isRtl ? 'rtl' : 'ltr'}>
      <header className={`sticky top-0 z-40 backdrop-blur-xl border-b theme-border shadow-2xl ${theme === 'dark' ? 'bg-slate-900/90' : 'bg-white/90'}`}>
        <div className="max-w-6xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <span className="text-2xl drop-shadow-[0_0_10px_rgba(99,102,241,0.5)]" title={t.title}>🎨</span>
            <h1 className="text-lg font-black tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-indigo-500 to-indigo-300">{t.title}</h1>
          </div>
          <div className="flex items-center gap-3">
            <button 
              onClick={toggleTheme}
              className={`p-2 rounded-xl transition-all border theme-border ${theme === 'dark' ? 'bg-slate-800 text-yellow-400 hover:bg-slate-700' : 'bg-slate-100 text-slate-700 hover:bg-slate-200'}`}
              title={theme === 'dark' ? 'Switch to Light Mode' : 'Switch to Dark Mode'}
            >
              {theme === 'dark' ? (
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m9-9h-1M4 9H3m15.364-6.364l-.707.707M6.343 17.657l-.707.707m12.728 0l-.707-.707M6.343 6.343l-.707-.707M12 8a4 4 0 100 8 4 4 0 000-8z" /></svg>
              ) : (
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" /></svg>
              )}
            </button>
            <select 
              value={lang} 
              onChange={(e) => setLang(e.target.value as Language)}
              title={t.languageSelect}
              className={`border theme-border rounded-xl px-3 py-1.5 text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-500 transition-all cursor-pointer ${theme === 'dark' ? 'bg-slate-800 text-slate-100' : 'bg-slate-100 text-slate-900'}`}
            >
              <option value="en">English</option>
              <option value="he">עברית</option>
              <option value="zh">中文</option>
              <option value="hi">हिन्दी</option>
              <option value="de">Deutsch</option>
              <option value="es">Español</option>
              <option value="fr">Français</option>
            </select>
          </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-6 py-12">
        <div className="text-center mb-12">
          <h2 className="text-3xl md:text-5xl font-extrabold mb-4 tracking-tight theme-text-main">{t.subtitle}</h2>
          <div className="flex items-center justify-center gap-2">
            <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
            <p className="theme-text-muted max-w-xl text-sm font-medium">{t.offlineReady}</p>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
          <aside className="lg:col-span-1 space-y-6">
            <div className={`p-6 rounded-[2.5rem] shadow-2xl border theme-border theme-bg-card`}>
              <label className="block text-[10px] font-black uppercase tracking-[0.2em] theme-text-muted mb-3 ml-1">{t.targetFolder}</label>
              <div className="relative group">
                <input 
                  type="text" 
                  list="labels-list"
                  value={targetLabel} 
                  onChange={(e) => setTargetLabel(e.target.value)}
                  placeholder={t.targetFolderPlaceholder} 
                  className={`w-full pl-4 pr-10 py-3.5 border theme-border rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all text-sm font-medium theme-text-main ${theme === 'dark' ? 'bg-slate-950 placeholder:text-slate-700' : 'bg-slate-50 placeholder:text-slate-400'}`} 
                  title={t.targetFolder}
                />
                <datalist id="labels-list">
                  {usedLabels.map(s => <option key={s} value={s} />)}
                </datalist>
                <button 
                  onClick={handlePickFolder}
                  title={t.pickFolder}
                  className="absolute right-3 top-1/2 -translate-y-1/2 theme-text-muted hover:text-indigo-400 transition-colors"
                >
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z" /></svg>
                </button>
              </div>
              <div className="mt-8 space-y-3">
                <button 
                  onClick={exportFiltered} 
                  disabled={filteredImages.length === 0} 
                  className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-800 disabled:text-slate-500 disabled:opacity-50 text-white font-bold rounded-2xl shadow-xl transition-all flex items-center justify-center gap-2 text-sm"
                  title={t.downloadAll}
                >
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                  {t.downloadAll}
                </button>
                <button 
                  onClick={() => setImages([])} 
                  className="w-full py-3 theme-text-muted hover:text-rose-400 text-[10px] font-black uppercase tracking-[0.2em] transition-colors"
                  title={t.clearBtn}
                >
                  {t.clearBtn}
                </button>
              </div>
            </div>
            <AdPlaceholder label={t.adPlaceholder} />
          </aside>

          <section className="lg:col-span-3 space-y-6">
            <div 
              onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
              onDragLeave={() => setIsDragging(false)}
              onDrop={(e) => { e.preventDefault(); setIsDragging(false); handleFiles(e.dataTransfer.files); }}
              onClick={() => fileInputRef.current?.click()}
              className={`group border-2 border-dashed rounded-[3rem] p-14 text-center cursor-pointer transition-all duration-500 ${isDragging ? 'drag-pulsing' : `theme-border hover:border-indigo-500/50 ${theme === 'dark' ? 'bg-slate-900/50 hover:bg-slate-900' : 'bg-white hover:bg-slate-50 shadow-lg'}`}`}
              title={t.dropzoneTitle}
            >
              <input type="file" multiple accept="image/*" className="hidden" ref={fileInputRef} onChange={(e) => handleFiles(e.target.files)} />
              <div className={`w-16 h-16 bg-indigo-500/10 rounded-[1.5rem] flex items-center justify-center mx-auto mb-6 transition-all group-hover:scale-110 ${isDragging ? 'scale-125 drag-content-pulsing' : ''}`}>
                <svg className="w-8 h-8 text-indigo-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>
              </div>
              <h3 className={`text-2xl font-black mb-1 theme-text-main transition-all ${isDragging ? 'drag-content-pulsing' : ''}`}>{t.dropzoneTitle}</h3>
              <p className={`theme-text-muted text-[10px] font-black uppercase tracking-[0.2em] transition-all ${isDragging ? 'drag-content-pulsing' : ''}`}>{t.dropzoneSub}</p>
            </div>

            {images.length > 0 && (
              <div className="relative">
                <input 
                  type="text" 
                  value={searchQuery} 
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder={t.searchPlaceholder}
                  className={`w-full pl-11 pr-4 py-4 border theme-border rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm theme-text-main theme-bg-card`} 
                  title={t.search}
                />
                <svg className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 theme-text-muted" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
              </div>
            )}

            <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-3 xl:grid-cols-4 gap-6">
              {filteredImages.map((img) => (
                <ImageCard 
                  key={img.id} 
                  item={img} 
                  t={t} 
                  theme={theme}
                  onRemove={(id) => setImages(prev => prev.filter(i => i.id !== id))} 
                  onSelect={onSelectImage} 
                  onShare={handleShare} 
                />
              ))}
            </div>
          </section>
        </div>
      </main>

      {selectedIndex !== null && images[selectedIndex] && (
        <div 
          ref={modalRef} 
          className={`fixed inset-0 z-50 flex flex-col backdrop-blur-3xl animate-in fade-in duration-300 overflow-hidden ${theme === 'dark' ? 'bg-slate-950/98' : 'bg-slate-50/95'}`} 
          onClick={() => setSelectedIndex(null)}
          onWheel={handleWheel}
        >
          {/* Header Bar - Distinct & Sticky */}
          <div className={`absolute top-0 left-0 right-0 z-50 h-16 px-6 flex items-center justify-between border-b theme-border transition-all ${isFullScreen ? 'opacity-40 hover:opacity-100 bg-slate-900/30' : 'backdrop-blur-xl theme-bg-card'}`} onClick={e => e.stopPropagation()}>
            <div className="flex items-center gap-3 truncate">
               <span className={`text-[10px] font-black uppercase tracking-wider truncate px-3 py-1.5 rounded-lg border theme-border ${theme === 'dark' ? 'bg-slate-950 text-white' : 'bg-white text-slate-900'}`}>{images[selectedIndex].file.name}</span>
               {isFullScreen && <span className="text-[10px] font-bold text-indigo-400 animate-pulse tracking-widest bg-indigo-500/10 px-2 py-1 rounded">LIVE FULLSCREEN</span>}
            </div>
            <div className="flex items-center gap-3">
              {images[selectedIndex].resultUrl && (
                <button 
                  onClick={(e) => { e.stopPropagation(); setShowOriginalInModal(!showOriginalInModal); }} 
                  className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-[0.1em] transition-all border ${showOriginalInModal ? 'bg-indigo-600 text-white border-indigo-400' : 'theme-bg-app theme-text-main theme-border hover:bg-indigo-500/10'}`}
                  title={showOriginalInModal ? t.result : t.original}
                >
                  {showOriginalInModal ? t.result : t.original}
                </button>
              )}
              <button 
                onClick={(e) => { e.stopPropagation(); exportSingle(images[selectedIndex!]); }} 
                className="px-4 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl text-[10px] font-black uppercase tracking-[0.1em] disabled:opacity-50 transition-colors border border-indigo-400 shadow-lg"
                disabled={!images[selectedIndex].resultUrl}
                title={t.export}
              >
                {t.export}
              </button>
              <div className="w-px h-6 theme-border mx-1"></div>
              <button 
                onClick={() => setSelectedIndex(null)} 
                className="p-2 theme-text-main hover:text-rose-400 transition-colors"
                title={t.close}
              >
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>
          </div>

          {/* Main Viewport */}
          <div className="flex-1 flex items-center justify-center p-4 md:p-12 overflow-hidden" onClick={e => e.stopPropagation()}>
            <div 
              className="relative transition-transform duration-100 ease-out cursor-grab active:cursor-grabbing" 
              style={{ transform: `scale(${zoomLevel}) translate(${panOffset.x / zoomLevel}px, ${panOffset.y / zoomLevel}px)` }}
              onMouseDown={handleMouseDown}
            >
              <img 
                src={showOriginalInModal || !images[selectedIndex].resultUrl ? images[selectedIndex].previewUrl : images[selectedIndex].resultUrl} 
                alt="Restored Preview" 
                draggable={false}
                className={`max-w-full max-h-[85vh] object-contain rounded-2xl md:rounded-[2rem] border theme-border select-none ${theme === 'dark' ? 'shadow-[0_50px_100px_-20px_rgba(0,0,0,0.8)]' : 'shadow-2xl'}`} 
              />
              {images[selectedIndex].status === 'error' && (
                <div className="absolute inset-0 flex flex-col items-center justify-center bg-rose-950/60 backdrop-blur-md rounded-2xl md:rounded-[2rem] p-8 text-center border-2 border-rose-500/20">
                   <div className="w-20 h-20 bg-rose-500/30 rounded-full flex items-center justify-center mb-6 border border-rose-500/50 shadow-2xl animate-bounce">
                      <svg className="w-10 h-10 text-rose-300" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                   </div>
                   <h4 className="text-2xl font-black text-rose-300 mb-3 uppercase tracking-widest drop-shadow-lg">{t.error}</h4>
                   <p className="text-slate-100 text-sm max-w-lg bg-black/60 p-6 rounded-2xl border border-white/10 shadow-3xl font-mono leading-relaxed backdrop-blur-lg">
                     {images[selectedIndex].error || "A processing error occurred. Please check your internet or try a different image format."}
                   </p>
                </div>
              )}
            </div>
          </div>

          {/* Controls Island */}
          <div className={`absolute bottom-8 left-1/2 -translate-x-1/2 z-50 flex flex-col items-center gap-5 transition-all duration-500 ${isFullScreen ? 'bottom-12 scale-110' : ''}`} onClick={e => e.stopPropagation()}>
            <div className={`flex items-center gap-6 px-8 py-5 rounded-[2.5rem] border shadow-3xl transition-all duration-500 ${theme === 'dark' ? 'bg-slate-900/80 border-white/10 backdrop-blur-xl' : 'bg-white/90 border-slate-200 backdrop-blur-xl'}`}>
              <button 
                onClick={() => setZoomLevel(prev => Math.max(prev - 0.25, 1))} 
                className={`p-4 rounded-2xl border transition-all shadow-lg active:scale-90 ${theme === 'dark' ? 'bg-slate-800 text-slate-300 hover:bg-indigo-600 hover:text-white border-white/5' : 'bg-slate-100 text-slate-700 hover:bg-indigo-500 hover:text-white border-slate-200'}`}
                title={t.zoomOut}
              >
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M20 12H4" /></svg>
              </button>

              <div className="flex flex-col items-center gap-2 min-w-[140px]">
                 <input 
                   type="range" 
                   min="1" 
                   max="8" 
                   step="0.01" 
                   value={zoomLevel} 
                   onChange={(e) => setZoomLevel(parseFloat(e.target.value))} 
                   className="w-full accent-indigo-400 h-2 rounded-full cursor-pointer hover:accent-indigo-300 transition-all shadow-inner" 
                   title={t.zoomLevel}
                 />
                 <span className={`text-[10px] font-black uppercase tracking-widest ${theme === 'dark' ? 'text-indigo-200' : 'text-indigo-600'}`}>{t.zoomLevel}: {Math.round(zoomLevel * 100)}%</span>
              </div>

              <button 
                onClick={() => setZoomLevel(prev => Math.min(prev + 0.25, 8))} 
                className={`p-4 rounded-2xl border transition-all shadow-lg active:scale-90 ${theme === 'dark' ? 'bg-slate-800 text-slate-300 hover:bg-indigo-600 hover:text-white border-white/5' : 'bg-slate-100 text-slate-700 hover:bg-indigo-500 hover:text-white border-slate-200'}`}
                title={t.zoomIn}
              >
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 6v6m0 0v6m0-6h6m-6 0H6" /></svg>
              </button>

              <div className="w-px h-10 theme-border hidden sm:block"></div>

              <button 
                onClick={toggleFullScreen}
                className={`p-4 rounded-2xl border transition-all hidden sm:block shadow-lg active:scale-95 ${theme === 'dark' ? 'bg-slate-800 text-slate-300 hover:bg-slate-700 border-white/10' : 'bg-slate-100 text-slate-700 hover:bg-slate-200 border-slate-200'} ${isFullScreen ? 'ring-2 ring-indigo-500' : ''}`}
                title={t.fullScreen}
              >
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                   <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" />
                </svg>
              </button>
            </div>

            <button 
              onClick={resetView} 
              className={`px-6 py-2.5 rounded-full text-[10px] font-black uppercase tracking-[0.2em] transition-all shadow-2xl border ${theme === 'dark' ? 'bg-slate-950/80 text-indigo-400 border-white/5 hover:text-indigo-200' : 'bg-white text-indigo-600 border-slate-200 hover:bg-slate-50'}`}
              title={t.resetView}
            >
              {t.resetView}
            </button>
          </div>
        </div>
      )}

      <footer className="py-16 text-center opacity-40">
        <p className="text-[10px] font-black uppercase tracking-[0.5em] mb-3">Powered by Gemini 2.5 Restoration Engine</p>
        <p className="text-[10px] font-black uppercase tracking-[0.3em] text-indigo-400">© 2026 ChromaRestore Pro Systems</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Language, ImageItem } from './types';
import { translations } from './i18n';
import { processImageWithGemini, fileToBase64 } from './services/geminiService';
import { ImageCard } from './components/ImageCard';
import { AdPlaceholder } from './components/AdPlaceholder';

const INITIAL_SUGGESTIONS = ['Personal Photos', 'Family Heritage', 'Travel 2024', 'Work Projects', 'Client Deliverables'];

interface ViewState {
  zoom: number;
  pan: { x: number; y: number };
}

const App: React.FC = () => {
  const [lang, setLang] = useState<Language>('en');
  const [theme, setTheme] = useState<'dark' | 'light'>(() => {
    return (localStorage.getItem('chroma-theme') as 'dark' | 'light') || 'dark';
  });
  const [images, setImages] = useState<ImageItem[]>([]);
  const [targetLabel, setTargetLabel] = useState('');
  const [usedLabels, setUsedLabels] = useState<string[]>(INITIAL_SUGGESTIONS);
  const [searchQuery, setSearchQuery] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState<number | null>(null);
  const [zoomLevel, setZoomLevel] = useState(1);
  const [panOffset, setPanOffset] = useState({ x: 0, y: 0 });
  const [isFullScreen, setIsFullScreen] = useState(false);
  const [showOriginalInModal, setShowOriginalInModal] = useState(false);
  const [viewStates, setViewStates] = useState<Record<string, ViewState>>({});

  const fileInputRef = useRef<HTMLInputElement>(null);
  const modalRef = useRef<HTMLDivElement>(null);
  const isDraggingImage = useRef(false);
  const lastMousePos = useRef({ x: 0, y: 0 });
  const t = translations[lang];
  const isRtl = lang === 'he';

  useEffect(() => {
    localStorage.setItem('chroma-theme', theme);
    document.documentElement.className = theme;
  }, [theme]);

  const filteredImages = images.filter(img => 
    img.file.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  useEffect(() => {
    if (selectedIndex !== null && images[selectedIndex]) {
      const id = images[selectedIndex].id;
      setViewStates(prev => ({
        ...prev,
        [id]: { zoom: zoomLevel, pan: panOffset }
      }));
    }
  }, [zoomLevel, panOffset, selectedIndex, images]);

  const processNextPending = useCallback(async () => {
    const nextItem = images.find(img => img.status === 'pending');
    if (!nextItem || isProcessing) return;

    setIsProcessing(true);
    setImages(prev => prev.map(img => 
      img.id === nextItem.id ? { ...img, status: 'processing', error: undefined } : img
    ));

    try {
      const base64 = await fileToBase64(nextItem.file);
      const resultUrl = await processImageWithGemini(base64, nextItem.file.type);
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'completed', resultUrl, destination: targetLabel } : img
      ));

      if (targetLabel.trim() && !usedLabels.includes(targetLabel.trim())) {
        setUsedLabels(prev => [targetLabel.trim(), ...prev].slice(0, 15));
      }
    } catch (err: any) {
      const errorMessage = err?.message || String(err);
      setImages(prev => prev.map(img => 
        img.id === nextItem.id ? { ...img, status: 'error', error: errorMessage } : img
      ));
    } finally {
      setIsProcessing(false);
    }
  }, [images, isProcessing, targetLabel, usedLabels]);

  useEffect(() => {
    processNextPending();
  }, [images, processNextPending]);

  const handleFiles = (files: FileList | null) => {
    if (!files) return;
    const newImages: ImageItem[] = Array.from(files).map(file => ({
      id: Math.random().toString(36).substr(2, 9),
      file,
      previewUrl: URL.createObjectURL(file),
      status: 'pending'
    }));
    setImages(prev => [...prev, ...newImages]);
  };

  const handleShare = (item: ImageItem) => {
    const url = item.resultUrl || item.previewUrl;
    navigator.clipboard.writeText(url).then(() => {
      alert(t.shareSuccess);
    });
  };

  const resetView = useCallback(() => {
    setZoomLevel(1);
    setPanOffset({ x: 0, y: 0 });
  }, []);

  const handleWheel = useCallback((e: React.WheelEvent) => {
    if (selectedIndex === null) return;
    const delta = -e.deltaY;
    const factor = 0.0005; // Finer grain zoom
    setZoomLevel(prev => Math.min(Math.max(prev + delta * factor * prev, 1), 8));
  }, [selectedIndex]);

  const handleMouseDown = (e: React.MouseEvent) => {
    if (selectedIndex === null) return;
    isDraggingImage.current = true;
    lastMousePos.current = { x: e.clientX, y: e.clientY };
  };

  const handleMouseMove = useCallback((e: MouseEvent) => {
    if (!isDraggingImage.current) return;
    const dx = e.clientX - lastMousePos.current.x;
    const dy = e.clientY - lastMousePos.current.y;
    setPanOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
    lastMousePos.current = { x: e.clientX, y: e.clientY };
  }, []);

  const handleMouseUp = useCallback(() => {
    isDraggingImage.current = false;
  }, []);

  useEffect(() => {
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [handleMouseMove, handleMouseUp]);

  const toggleFullScreen = useCallback(() => {
    if (!document.fullscreenElement) {
      modalRef.current?.requestFullscreen().catch(err => {
        console.error(`Fullscreen failed: ${err.message}`);
      });
    } else {
      document.exitFullscreen();
    }
  }, []);

  const toggleTheme = () => setTheme(prev => prev === 'dark' ? 'light' : 'dark');

  useEffect(() => {
    const onFsChange = () => setIsFullScreen(!!document.fullscreenElement);
    document.addEventListener('fullscreenchange', onFsChange);
    return () => document.removeEventListener('fullscreenchange', onFsChange);
  }, []);

  const handlePickFolder = async () => {
    if ('showDirectoryPicker' in window) {
      try {
        const handle = await (window as any).showDirectoryPicker();
        setTargetLabel(handle.name);
      } catch (e) {
        console.debug('Folder picker cancelled', e);
      }
    } else {
      alert('Manual folder typing is required on this browser.');
    }
  };

  const exportSingle = (img: ImageItem) => {
    if (!img.resultUrl) return;
    const prefix = targetLabel.trim() || 'colorized';
    const link = document.createElement('a');
    link.href = img.resultUrl;
    link.download = `${prefix}_${img.file.name}`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const exportFiltered = () => {
    if (filteredImages.length === 0) return;
    const prefix = targetLabel || 'export';
    filteredImages.forEach((img, idx) => {
      if (img.resultUrl) {
        setTimeout(() => {
          const link = document.createElement('a');
          link.href = img.resultUrl!;
          link.download = `${prefix}_${img.file.name}`;
          link.click();
        }, idx * 150);
      }
    });
  };

  const handleKeyDown = useCallback((e: KeyboardEvent) => {
    if (selectedIndex === null) return;
    if (e.key === 'f' || e.key === 'F') { e.preventDefault(); toggleFullScreen(); }
    else if (e.key === '+' || e.key === '=') { e.preventDefault(); setZoomLevel(prev => Math.min(prev + 0.2, 8)); }
    else if (e.key === '-' || e.key === '_') { e.preventDefault(); setZoomLevel(prev => Math.max(prev - 0.2, 1)); }
    else if (e.key === '0') { e.preventDefault(); resetView(); }
    else if (e.key === 'Escape') {
      if (document.fullscreenElement) document.exitFullscreen();
      else setSelectedIndex(null);
    }
  }, [selectedIndex, toggleFullScreen, resetView]);

  useEffect(() => {
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleKeyDown]);

  const onSelectImage = (item: ImageItem) => {
    const index = images.indexOf(item);
    setSelectedIndex(index);
    setShowOriginalInModal(false);
    const savedState = viewStates[item.id];
    if (savedState) {
      setZoomLevel(savedState.zoom);
      setPanOffset(savedState.pan);
    } else {
      resetView();
    }
  };

  return (
    <div className={`min-h-screen ${theme} theme-bg-app theme-text-main font-sans lang-${lang} ${isRtl ? 'rtl' : 'ltr'}`} dir={isRtl ? 'rtl' : 'ltr'}>
      <header className={`sticky top-0 z-40 backdrop-blur-xl border-b theme-border shadow-2xl ${theme === 'dark' ? 'bg-slate-900/90' : 'bg-white/90'}`}>
        <div className="max-w-6xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <span className="text-2xl drop-shadow-[0_0_10px_rgba(99,102,241,0.5)]" title={t.title}>🎨</span>
            <h1 className="text-lg font-black tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-indigo-500 to-indigo-300">{t.title}</h1>
          </div>
          <div className="flex items-center gap-3">
            <button 
              onClick={toggleTheme}
              className={`p-2 rounded-xl transition-all border theme-border ${theme === 'dark' ? 'bg-slate-800 text-yellow-400 hover:bg-slate-700' : 'bg-slate-100 text-slate-700 hover:bg-slate-200'}`}
              title={theme === 'dark' ? 'Switch to Light Mode' : 'Switch to Dark Mode'}
            >
              {theme === 'dark' ? (
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m9-9h-1M4 9H3m15.364-6.364l-.707.707M6.343 17.657l-.707.707m12.728 0l-.707-.707M6.343 6.343l-.707-.707M12 8a4 4 0 100 8 4 4 0 000-8z" /></svg>
              ) : (
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" /></svg>
              )}
            </button>
            <select 
              value={lang} 
              onChange={(e) => setLang(e.target.value as Language)}
              title={t.languageSelect}
              className={`border theme-border rounded-xl px-3 py-1.5 text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-500 transition-all cursor-pointer ${theme === 'dark' ? 'bg-slate-800 text-slate-100' : 'bg-slate-100 text-slate-900'}`}
            >
              <option value="en">English</option>
              <option value="he">עברית</option>
              <option value="zh">中文</option>
              <option value="hi">हिन्दी</option>
              <option value="de">Deutsch</option>
              <option value="es">Español</option>
              <option value="fr">Français</option>
            </select>
          </div>
        </div>
      </header>

      <main className="max-w-6xl mx-auto px-6 py-12">
        <div className="text-center mb-12">
          <h2 className="text-3xl md:text-5xl font-extrabold mb-4 tracking-tight theme-text-main">{t.subtitle}</h2>
          <div className="flex items-center justify-center gap-2">
            <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
            <p className="theme-text-muted max-w-xl text-sm font-medium">{t.offlineReady}</p>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
          <aside className="lg:col-span-1 space-y-6">
            <div className={`p-6 rounded-[2.5rem] shadow-2xl border theme-border theme-bg-card`}>
              <label className="block text-[10px] font-black uppercase tracking-[0.2em] theme-text-muted mb-3 ml-1">{t.targetFolder}</label>
              <div className="relative group">
                <input 
                  type="text" 
                  list="labels-list"
                  value={targetLabel} 
                  onChange={(e) => setTargetLabel(e.target.value)}
                  placeholder={t.targetFolderPlaceholder} 
                  className={`w-full pl-4 pr-10 py-3.5 border theme-border rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none transition-all text-sm font-medium theme-text-main ${theme === 'dark' ? 'bg-slate-950 placeholder:text-slate-700' : 'bg-slate-50 placeholder:text-slate-400'}`} 
                  title={t.targetFolder}
                />
                <datalist id="labels-list">
                  {usedLabels.map(s => <option key={s} value={s} />)}
                </datalist>
                <button 
                  onClick={handlePickFolder}
                  title={t.pickFolder}
                  className="absolute right-3 top-1/2 -translate-y-1/2 theme-text-muted hover:text-indigo-400 transition-colors"
                >
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z" /></svg>
                </button>
              </div>
              <div className="mt-8 space-y-3">
                <button 
                  onClick={exportFiltered} 
                  disabled={filteredImages.length === 0} 
                  className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 disabled:bg-slate-800 disabled:text-slate-500 disabled:opacity-50 text-white font-bold rounded-2xl shadow-xl transition-all flex items-center justify-center gap-2 text-sm"
                  title={t.downloadAll}
                >
                  <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                  {t.downloadAll}
                </button>
                <button 
                  onClick={() => setImages([])} 
                  className="w-full py-3 theme-text-muted hover:text-rose-400 text-[10px] font-black uppercase tracking-[0.2em] transition-colors"
                  title={t.clearBtn}
                >
                  {t.clearBtn}
                </button>
              </div>
            </div>
            <AdPlaceholder label={t.adPlaceholder} />
          </aside>

          <section className="lg:col-span-3 space-y-6">
            <div 
              onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
              onDragLeave={() => setIsDragging(false)}
              onDrop={(e) => { e.preventDefault(); setIsDragging(false); handleFiles(e.dataTransfer.files); }}
              onClick={() => fileInputRef.current?.click()}
              className={`group border-2 border-dashed rounded-[3rem] p-14 text-center cursor-pointer transition-all duration-500 ${isDragging ? 'drag-pulsing' : `theme-border hover:border-indigo-500/50 ${theme === 'dark' ? 'bg-slate-900/50 hover:bg-slate-900' : 'bg-white hover:bg-slate-50 shadow-lg'}`}`}
              title={t.dropzoneTitle}
            >
              <input type="file" multiple accept="image/*" className="hidden" ref={fileInputRef} onChange={(e) => handleFiles(e.target.files)} />
              <div className={`w-16 h-16 bg-indigo-500/10 rounded-[1.5rem] flex items-center justify-center mx-auto mb-6 transition-all group-hover:scale-110 ${isDragging ? 'scale-125 drag-content-pulsing' : ''}`}>
                <svg className="w-8 h-8 text-indigo-400" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" /></svg>
              </div>
              <h3 className={`text-2xl font-black mb-1 theme-text-main transition-all ${isDragging ? 'drag-content-pulsing' : ''}`}>{t.dropzoneTitle}</h3>
              <p className={`theme-text-muted text-[10px] font-black uppercase tracking-[0.2em] transition-all ${isDragging ? 'drag-content-pulsing' : ''}`}>{t.dropzoneSub}</p>
            </div>

            {images.length > 0 && (
              <div className="relative">
                <input 
                  type="text" 
                  value={searchQuery} 
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder={t.searchPlaceholder}
                  className={`w-full pl-11 pr-4 py-4 border theme-border rounded-2xl focus:ring-2 focus:ring-indigo-500 outline-none text-sm theme-text-main theme-bg-card`} 
                  title={t.search}
                />
                <svg className="w-5 h-5 absolute left-4 top-1/2 -translate-y-1/2 theme-text-muted" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
              </div>
            )}

            <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-3 xl:grid-cols-4 gap-6">
              {filteredImages.map((img) => (
                <ImageCard 
                  key={img.id} 
                  item={img} 
                  t={t} 
                  theme={theme}
                  onRemove={(id) => setImages(prev => prev.filter(i => i.id !== id))} 
                  onSelect={onSelectImage} 
                  onShare={handleShare} 
                />
              ))}
            </div>
          </section>
        </div>
      </main>

      {selectedIndex !== null && images[selectedIndex] && (
        <div 
          ref={modalRef} 
          className={`fixed inset-0 z-50 flex flex-col backdrop-blur-3xl animate-in fade-in duration-300 overflow-hidden ${theme === 'dark' ? 'bg-slate-950/98' : 'bg-slate-50/95'}`} 
          onClick={() => setSelectedIndex(null)}
          onWheel={handleWheel}
        >
          {/* Header Bar - More distinct in normal mode, subtle in fullscreen */}
          <div className={`absolute top-0 left-0 right-0 z-50 h-16 px-6 flex items-center justify-between border-b theme-border transition-all ${isFullScreen ? 'opacity-40 hover:opacity-100 bg-slate-900/30' : 'backdrop-blur-xl theme-bg-card'}`} onClick={e => e.stopPropagation()}>
            <div className="flex items-center gap-3 truncate">
               <span className={`text-[10px] font-black uppercase tracking-wider truncate px-3 py-1.5 rounded-lg border theme-border ${theme === 'dark' ? 'bg-slate-950 text-white' : 'bg-white text-slate-900'}`}>{images[selectedIndex].file.name}</span>
               {isFullScreen && <span className="text-[10px] font-bold text-indigo-400 animate-pulse tracking-widest bg-indigo-500/10 px-2 py-1 rounded">FULLSCREEN</span>}
            </div>
            <div className="flex items-center gap-3">
              {images[selectedIndex].resultUrl && (
                <button 
                  onClick={(e) => { e.stopPropagation(); setShowOriginalInModal(!showOriginalInModal); }} 
                  className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-[0.1em] transition-all border ${showOriginalInModal ? 'bg-indigo-600 text-white border-indigo-400' : 'theme-bg-app theme-text-main theme-border hover:bg-indigo-500/10'}`}
                  title={showOriginalInModal ? t.result : t.original}
                >
                  {showOriginalInModal ? t.result : t.original}
                </button>
              )}
              <button 
                onClick={(e) => { e.stopPropagation(); exportSingle(images[selectedIndex!]); }} 
                className="px-4 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl text-[10px] font-black uppercase tracking-[0.1em] disabled:opacity-50 transition-colors border border-indigo-400 shadow-lg"
                disabled={!images[selectedIndex].resultUrl}
                title={t.export}
              >
                {t.export}
              </button>
              <div className="w-px h-6 theme-border mx-1"></div>
              <button 
                onClick={() => setSelectedIndex(null)} 
                className="p-2 theme-text-main hover:text-rose-400 transition-colors"
                title={t.close}
              >
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>
          </div>

          {/* Main Viewport */}
          <div className="flex-1 flex items-center justify-center p-4 md:p-12 overflow-hidden" onClick={e => e.stopPropagation()}>
            <div 
              className="relative transition-transform duration-100 ease-out cursor-grab active:cursor-grabbing" 
              style={{ transform: `scale(${zoomLevel}) translate(${panOffset.x / zoomLevel}px, ${panOffset.y / zoomLevel}px)` }}
              onMouseDown={handleMouseDown}
            >
              <img 
                src={showOriginalInModal || !images[selectedIndex].resultUrl ? images[selectedIndex].previewUrl : images[selectedIndex].resultUrl} 
                alt="Restored Preview" 
                draggable={false}
                className={`max-w-full max-h-[85vh] object-contain rounded-2xl md:rounded-[2rem] border theme-border select-none ${theme === 'dark' ? 'shadow-[0_50px_100px_-20px_rgba(0,0,0,0.8)]' : 'shadow-2xl'}`} 
              />
              {images[selectedIndex].status === 'error' && (
                <div className="absolute inset-0 flex flex-col items-center justify-center bg-rose-950/60 backdrop-blur-md rounded-2xl md:rounded-[2rem] p-8 text-center border-2 border-rose-500/20">
                   <div className="w-20 h-20 bg-rose-500/30 rounded-full flex items-center justify-center mb-6 border border-rose-500/50 shadow-2xl animate-bounce">
                      <svg className="w-10 h-10 text-rose-300" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                   </div>
                   <h4 className="text-2xl font-black text-rose-300 mb-3 uppercase tracking-widest drop-shadow-lg">{t.error}</h4>
                   <p className="text-slate-100 text-sm max-w-lg bg-black/60 p-6 rounded-2xl border border-white/10 shadow-3xl font-mono leading-relaxed backdrop-blur-lg">
                     {images[selectedIndex].error || "Processing failed. This may be due to image complexity or model constraints."}
                   </p>
                </div>
              )}
            </div>
          </div>

          {/* Controls Island - Floating centered bar */}
          <div className={`absolute bottom-8 left-1/2 -translate-x-1/2 z-50 flex flex-col items-center gap-5 transition-all duration-500 ${isFullScreen ? 'bottom-12 scale-110' : ''}`} onClick={e => e.stopPropagation()}>
            <div className={`flex items-center gap-6 px-8 py-5 rounded-[2.5rem] border shadow-3xl transition-all duration-500 ${theme === 'dark' ? 'bg-slate-900/80 border-white/10 backdrop-blur-xl' : 'bg-white/90 border-slate-200 backdrop-blur-xl'}`}>
              <button 
                onClick={() => setZoomLevel(prev => Math.max(prev - 0.25, 1))} 
                className={`p-4 rounded-2xl border transition-all shadow-lg active:scale-90 ${theme === 'dark' ? 'bg-slate-800 text-slate-300 hover:bg-indigo-600 hover:text-white border-white/5' : 'bg-slate-100 text-slate-700 hover:bg-indigo-500 hover:text-white border-slate-200'}`}
                title={t.zoomOut}
              >
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M20 12H4" /></svg>
              </button>

              <div className="flex flex-col items-center gap-2 min-w-[140px]">
                 <input 
                   type="range" 
                   min="1" 
                   max="8" 
                   step="0.01" 
                   value={zoomLevel} 
                   onChange={(e) => setZoomLevel(parseFloat(e.target.value))} 
                   className="w-full accent-indigo-400 h-2 rounded-full cursor-pointer hover:accent-indigo-300 transition-all shadow-inner" 
                   title={t.zoomLevel}
                 />
                 <span className={`text-[10px] font-black uppercase tracking-widest ${theme === 'dark' ? 'text-indigo-200' : 'text-indigo-600'}`}>{t.zoomLevel}: {Math.round(zoomLevel * 100)}%</span>
              </div>

              <button 
                onClick={() => setZoomLevel(prev => Math.min(prev + 0.25, 8))} 
                className={`p-4 rounded-2xl border transition-all shadow-lg active:scale-90 ${theme === 'dark' ? 'bg-slate-800 text-slate-300 hover:bg-indigo-600 hover:text-white border-white/5' : 'bg-slate-100 text-slate-700 hover:bg-indigo-500 hover:text-white border-slate-200'}`}
                title={t.zoomIn}
              >
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 6v6m0 0v6m0-6h6m-6 0H6" /></svg>
              </button>

              <div className="w-px h-10 theme-border hidden sm:block"></div>

              <button 
                onClick={toggleFullScreen}
                className={`p-4 rounded-2xl border transition-all hidden sm:block shadow-lg active:scale-95 ${theme === 'dark' ? 'bg-slate-800 text-slate-300 hover:bg-slate-700 border-white/10' : 'bg-slate-100 text-slate-700 hover:bg-slate-200 border-slate-200'} ${isFullScreen ? 'ring-2 ring-indigo-500' : ''}`}
                title={t.fullScreen}
              >
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                   <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" />
                </svg>
              </button>
            </div>

            <button 
              onClick={resetView} 
              className={`px-6 py-2.5 rounded-full text-[10px] font-black uppercase tracking-[0.2em] transition-all shadow-2xl border ${theme === 'dark' ? 'bg-slate-950/80 text-indigo-400 border-white/5 hover:text-indigo-200' : 'bg-white text-indigo-600 border-slate-200 hover:bg-slate-50'}`}
              title={t.resetView}
            >
              {t.resetView}
            </button>
          </div>
        </div>
      )}

      <footer className="py-16 text-center opacity-40">
        <p className="text-[10px] font-black uppercase tracking-[0.5em] mb-3">Powered by Gemini 2.5 Restoration Engine</p>
        <p className="text-[10px] font-black uppercase tracking-[0.3em] text-indigo-400">© 2026 ChromaRestore Pro Systems</p>
      </footer>
    </div>
  );
};

export default App;

@import url('https://cdnjs.cloudflare.com/ajax/libs/tailwindcss/2.2.19/tailwind.min.css');

:root { 
  --primary: #6366f1; 
  --transition-speed: 0.3s;
}

/* Base Theme Variables */
.dark {
  --bg-app: #020617;
  --bg-header: rgba(15, 23, 42, 0.9);
  --bg-card: #0f172a;
  --bg-input: #020617;
  --text-main: #f1f5f9;
  --text-muted: #94a3b8;
  --border-main: #1e293b;
  --shadow-main: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --bg-tooltip: #1e293b;
  --text-tooltip: #f1f5f9;
}

.light {
  --bg-app: #f8fafc;
  --bg-header: rgba(255, 255, 255, 0.9);
  --bg-card: #ffffff;
  --bg-input: #ffffff;
  --text-main: #0f172a;
  --text-muted: #475569;
  --border-main: #e2e8f0;
  --shadow-main: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);
  --bg-tooltip: #ffffff;
  --text-tooltip: #0f172a;
}

body {
  font-family: 'Plus Jakarta Sans', sans-serif;
  transition: background-color var(--transition-speed), color var(--transition-speed);
  overflow-x: hidden;
}

/* Tooltip System */
[data-tooltip] {
  position: relative;
}

[data-tooltip]::before {
  content: attr(data-tooltip);
  position: absolute;
  bottom: 125%;
  left: 50%;
  transform: translateX(-50%) translateY(5px);
  padding: 6px 10px;
  background: var(--bg-tooltip);
  color: var(--text-tooltip);
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
  white-space: nowrap;
  border-radius: 8px;
  opacity: 0;
  visibility: hidden;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  z-index: 50;
  border: 1px solid rgba(128, 128, 128, 0.1);
  box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.2);
  pointer-events: none;
  letter-spacing: 0.05em;
}

[data-tooltip]::after {
  content: '';
  position: absolute;
  bottom: 110%;
  left: 50%;
  transform: translateX(-50%) translateY(5px);
  border: 5px solid transparent;
  border-top-color: var(--bg-tooltip);
  opacity: 0;
  visibility: hidden;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  z-index: 50;
  pointer-events: none;
}

[data-tooltip]:hover::before,
[data-tooltip]:hover::after {
  opacity: 1;
  visibility: visible;
  transform: translateX(-50%) translateY(0);
}

/* RTL Support */
[dir="rtl"] { font-family: 'Heebo', sans-serif; }
.lang-zh { font-family: 'Noto Sans SC', sans-serif; }
.lang-hi { font-family: 'Noto Sans Devanagari', sans-serif; }

/* Theme Utility Overrides */
.theme-bg-app { background-color: var(--bg-app); }
.theme-bg-card { background-color: var(--bg-card); }
.theme-text-main { color: var(--text-main); }
.theme-text-muted { color: var(--text-muted); }
.theme-border { border-color: var(--border-main); }

/* Animations */
@keyframes pulse-border {
  0%, 100% { 
    border-color: rgba(99, 102, 241, 0.3); 
    box-shadow: 0 0 0 0 rgba(99, 102, 241, 0); 
  }
  50% { 
    border-color: rgba(99, 102, 241, 0.8); 
    box-shadow: 0 0 15px 0 rgba(99, 102, 241, 0.15); 
  }
}

@keyframes pulse-content {
  0%, 100% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.015); opacity: 0.9; }
}

@keyframes shimmer {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(100%); }
}

.drag-pulsing {
  animation: pulse-border 2s infinite ease-in-out;
  background-color: rgba(99, 102, 241, 0.06) !important;
  border-style: solid !important;
}

.drag-content-pulsing { 
  animation: pulse-content 2s infinite ease-in-out; 
}

.shimmer-effect::after {
  content: "";
  position: absolute;
  top: 0; left: 0; width: 100%; height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.1), transparent);
  animation: shimmer 2s infinite;
}

/* Scrollbar */
::-webkit-scrollbar { width: 10px; }
::-webkit-scrollbar-track { background: var(--bg-app); }
::-webkit-scrollbar-thumb { background: var(--border-main); border-radius: 5px; }
::-webkit-scrollbar-thumb:hover { background: var(--text-muted); }

.backdrop-blur-xl { backdrop-filter: blur(24px); }
.backdrop-blur-3xl { backdrop-filter: blur(64px); }

/* Theme Transition Helper */
* {
  transition: background-color var(--transition-speed) ease, border-color var(--transition-speed) ease, color var(--transition-speed) ease, box-shadow var(--transition-speed) ease;
}

