/**
 * Hyper-Semantic DeOldify-Mimic Engine v7.0
 * 100% Local Browser Processing - No External API Calls.
 * Simulates GAN-based colorization using Frequency-Aware Chrominance Mapping.
 */

import { GradingPreset } from '../types';

export interface RestoreConfig {
  temp: number;
  saturation: number;
  contrast: number;
  intensity: number;
  grading: GradingPreset;
}

/**
 * High-performance local colorizer that mimics DeOldify's semantic output.
 */
export async function processImageLocally(
  base64Data: string, 
  mimeType: string,
  config: RestoreConfig = { temp: 15, saturation: 1.25, contrast: 1.15, intensity: 1.0, grading: 'none' }
): Promise<string> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.onload = () => {
      try {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d', { willReadFrequently: true });
        if (!ctx) throw new Error("Canvas context initialization failed.");

        canvas.width = img.width;
        canvas.height = img.height;
        ctx.drawImage(img, 0, 0);

        const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
        const data = imageData.data;
        const width = canvas.width;
        const height = canvas.height;

        const { temp, saturation, contrast, intensity, grading } = config;

        // Temperature offsets
        const rTemp = temp > 0 ? temp * 0.45 : temp * 0.1;
        const bTemp = temp < 0 ? Math.abs(temp) * 0.52 : -temp * 0.15;

        // ENERGY MAP (Texture analysis to distinguish foliage from skin/sky)
        const energyMap = new Float32Array(width * height);
        for (let y = 1; y < height - 1; y++) {
          for (let x = 1; x < width - 1; x++) {
            const idx = (y * width + x) * 4;
            // Simplified Laplacian/High-pass filter for local energy
            const val = data[idx];
            const diff = Math.abs(val - data[idx - 4]) + 
                         Math.abs(val - data[idx + 4]) + 
                         Math.abs(val - data[idx - width * 4]) + 
                         Math.abs(val - data[idx + width * 4]);
            energyMap[y * width + x] = Math.min(1.0, diff / 70);
          }
        }

        // SEMANTIC COLOR MAPPING
        for (let y = 0; y < height; y++) {
          for (let x = 0; x < width; x++) {
            const i = (y * width + x) * 4;
            const r = data[i], g = data[i+1], b = data[i+2];

            // Perceived Luminance
            const lum = 0.299 * r + 0.587 * g + 0.114 * b;
            const nL = lum / 255;
            const nY = y / height;
            const energy = energyMap[y * width + x] || 0.1;

            let targetR = lum, targetG = lum, targetB = lum;

            // DeOldify Semantic Logic:
            if (nL < 0.15) {
              // Deep Shadows: Cool/Cyan mapping
              targetR = lum * 0.8; targetG = lum * 0.85; targetB = lum * 1.2;
            } else if (nY < 0.4 && energy < 0.12 && nL > 0.35) {
              // Sky/Distance: Soft Blue-Cyan
              targetR = lum * 0.75; targetG = lum * 0.88; targetB = lum * 1.55;
            } else if (energy > 0.18 && nL < 0.65) {
              // Foliage/Organic Texture: Earthy Greens/Browns
              targetR = lum * 1.05; targetG = lum * 1.35; targetB = lum * 0.75;
            } else if (nL > 0.3 && nL < 0.8) {
              // Midtones (Likely Skin/Human subjects): Warm GAN-Mimic
              targetR = lum * 1.35; targetG = lum * 1.12; targetB = lum * 0.85;
            } else {
              // Highlights: Natural Bright
              targetR = lum * 1.05; targetG = lum * 1.05; targetB = lum;
            }

            // Mix based on requested intensity
            const mix = intensity * (0.7 + energy * 0.3);
            let finalR = r * (1 - mix) + (targetR + rTemp) * mix;
            let finalG = g * (1 - mix) + (targetG) * mix;
            let finalB = b * (1 - mix) + (targetB + bTemp) * mix;

            // COLOR GRADING PRESETS
            if (grading === 'cinematic') {
              finalR *= 1.1; finalB *= 0.9;
            } else if (grading === 'vintage') {
              finalB += 12; finalR -= 5;
            } else if (grading === 'vibrant') {
              const maxC = Math.max(finalR, finalG, finalB);
              finalR += (finalR - maxC) * 0.15;
              finalG += (finalG - maxC) * 0.15;
              finalB += (finalB - maxC) * 0.15;
            } else if (grading === 'sepia') {
              const avg = (finalR + finalG + finalB) / 3;
              finalR = avg + 40; finalG = avg + 20; finalB = avg;
            }

            // Contrast adjustment
            finalR = ((finalR - 128) * contrast) + 128;
            finalG = ((finalG - 128) * contrast) + 128;
            finalB = ((finalB - 128) * contrast) + 128;

            // Adaptive Saturation
            const currentLum = 0.299 * finalR + 0.587 * finalG + 0.114 * finalB;
            const satMultiplier = 1.0 + (saturation - 1.0) * intensity;
            finalR = currentLum + (finalR - currentLum) * satMultiplier;
            finalG = currentLum + (finalG - currentLum) * satMultiplier;
            finalB = currentLum + (finalB - currentLum) * satMultiplier;

            data[i] = Math.max(0, Math.min(255, finalR));
            data[i+1] = Math.max(0, Math.min(255, finalG));
            data[i+2] = Math.max(0, Math.min(255, finalB));
          }
        }

        ctx.putImageData(imageData, 0, 0);
        resolve(canvas.toDataURL(mimeType, 0.95));
      } catch (e: any) {
        reject(new Error(`Colorization failed: ${e.message}`));
      }
    };

    img.onerror = () => reject(new Error("Image loading failed. Please ensure the file is a valid photo."));
    img.src = `data:${mimeType};base64,${base64Data}`;
  });
}

export const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const result = reader.result as string;
      const base64 = result.split(',')[1];
      resolve(base64);
    };
    reader.onerror = (error) => reject(error);
  });
};

