/**
 * Adaptive Semantic Colorization Engine v8.2
 * 100% Local Browser Processing - No External API Calls.
 * Mimics GAN-based colorization (like DeOldify) using Spatial-Aware Chrominance Heuristics.
 */

import { GradingPreset } from '../types';

export interface RestoreConfig {
  temp: number;
  saturation: number;
  contrast: number;
  intensity: number;
  grading: GradingPreset;
}

/**
 * Refined local colorizer that analyzes image structure for natural results.
 */
export async function processImageLocally(
  base64Data: string, 
  mimeType: string,
  config: RestoreConfig = { temp: 15, saturation: 1.25, contrast: 1.15, intensity: 1.0, grading: 'none' }
): Promise<string> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.onload = () => {
      try {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d', { willReadFrequently: true });
        if (!ctx) throw new Error("Canvas context initialization failed.");

        canvas.width = img.width;
        canvas.height = img.height;
        ctx.drawImage(img, 0, 0);

        const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
        const data = imageData.data;
        const width = canvas.width;
        const height = canvas.height;

        const { temp, saturation, contrast, intensity, grading } = config;

        // Intensity mapping
        const colorWeight = intensity;

        // ANALYZE LOCAL TEXTURE (Energy Map)
        // High energy = texture (foliate/fabric), Low energy = smooth (sky/skin/walls)
        const energyMap = new Float32Array(width * height);
        for (let y = 1; y < height - 1; y += 2) {
          for (let x = 1; x < width - 1; x += 2) {
            const idx = (y * width + x) * 4;
            const lum = 0.299 * data[idx] + 0.587 * data[idx+1] + 0.114 * data[idx+2];
            const diff = Math.abs(lum - (0.299 * data[idx-4] + 0.587 * data[idx-3] + 0.114 * data[idx-2]));
            energyMap[y * width + x] = diff;
          }
        }

        for (let y = 0; y < height; y++) {
          const yNorm = y / height;
          for (let x = 0; x < width; x++) {
            const i = (y * width + x) * 4;
            const r = data[i], g = data[i+1], b = data[i+2];

            // Original Luminance (Grayscale value)
            const L = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
            const energy = energyMap[y * width + x] || 0.1;

            let tR = L, tG = L, tB = L;

            // SEMANTIC HEURISTIC MAPPING
            if (L < 0.15) {
              // Deep Shadows: Cool / Deep Blue
              tR = L * 0.85; tG = L * 0.9; tB = L * 1.15;
            } else if (yNorm < 0.45 && L > 0.4 && energy < 15) {
              // High probability Sky: Cyan-Blue Gradient
              tR = L * 0.7; tG = L * 0.85; tB = L * 1.4;
            } else if (energy > 25 && L < 0.7 && L > 0.2) {
              // High probability Vegetation/Texture: Earthy Green
              tR = L * 0.95; tG = L * 1.25; tB = L * 0.8;
            } else if (L > 0.3 && L < 0.85) {
              // Midtones (Skin/Architecture): Warm GAN-Mimic
              // Skin tones usually sit in the mid-range luminance
              const skinWarmth = 1.3 - (yNorm * 0.1); 
              tR = L * skinWarmth; tG = L * 1.05; tB = L * 0.85;
            } else {
              // Highlights: Natural Bright
              tR = L * 1.02; tG = L * 1.02; tB = L;
            }

            // Mix original with semantic target based on intensity
            let finalR = (r / 255) * (1 - colorWeight) + tR * colorWeight;
            let finalG = (g / 255) * (1 - colorWeight) + tG * colorWeight;
            let finalB = (b / 255) * (1 - colorWeight) + tB * colorWeight;

            // Apply Temperature
            const tempShift = temp / 500;
            finalR += tempShift;
            finalB -= tempShift;

            // Apply Color Grading Presets
            if (grading === 'cinematic') {
              finalR *= 1.1; finalB *= 0.95; finalG *= 0.98;
            } else if (grading === 'vintage') {
              finalR *= 1.05; finalG *= 1.02; finalB *= 0.9;
              finalR += 0.05; // Add slight sepia tint
            } else if (grading === 'vibrant') {
              const maxVal = Math.max(finalR, finalG, finalB);
              finalR += (finalR - maxVal) * 0.1;
              finalG += (finalG - maxVal) * 0.1;
              finalB += (finalB - maxVal) * 0.1;
            } else if (grading === 'sepia') {
              const avg = (finalR + finalG + finalB) / 3;
              finalR = avg + 0.15; finalG = avg + 0.05; finalB = avg - 0.05;
            }

            // Adjust Contrast
            finalR = ((finalR - 0.5) * contrast) + 0.5;
            finalG = ((finalG - 0.5) * contrast) + 0.5;
            finalB = ((finalB - 0.5) * contrast) + 0.5;

            // Adjust Saturation
            const finalLum = 0.299 * finalR + 0.587 * finalG + 0.114 * finalB;
            finalR = finalLum + (finalR - finalLum) * saturation;
            finalG = finalLum + (finalG - finalLum) * saturation;
            finalB = finalLum + (finalB - finalLum) * saturation;

            data[i] = Math.min(255, Math.max(0, finalR * 255));
            data[i+1] = Math.min(255, Math.max(0, finalG * 255));
            data[i+2] = Math.min(255, Math.max(0, finalB * 255));
          }
        }

        ctx.putImageData(imageData, 0, 0);
        resolve(canvas.toDataURL(mimeType, 0.92));
      } catch (e: any) {
        reject(new Error(`Local restoration failed: ${e.message}`));
      }
    };

    img.onerror = () => reject(new Error("Image processing failed. Resource may be blocked or invalid."));
    img.src = `data:${mimeType};base64,${base64Data}`;
  });
}

export const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      const result = reader.result as string;
      const base64 = result.split(',')[1];
      resolve(base64);
    };
    reader.onerror = (error) => reject(error);
  });
};

const CACHE_NAME = 'chroma-restore-v6';
const ASSETS = [
  '/',
  '/index.html',
  '/index.css',
  '/manifest.json'
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => {
      return Promise.allSettled(
        ASSETS.map(url => cache.add(url))
      );
    })
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) => Promise.all(
      keys.map((key) => {
        if (key !== CACHE_NAME) return caches.delete(key);
      })
    ))
  );
});

self.addEventListener('fetch', (event) => {
  if (event.request.method !== 'GET') return;

  // Skip non-local requests (like AdSense or CDN) from caching to avoid ERR_BLOCKED_BY_CLIENT issues
  const url = new URL(event.request.url);
  if (url.origin !== self.location.origin) return;

  event.respondWith(
    caches.match(event.request).then((cached) => {
      return cached || fetch(event.request).then((response) => {
        if (!response || response.status !== 200 || response.type !== 'basic') {
          return response;
        }
        const responseToCache = response.clone();
        caches.open(CACHE_NAME).then((cache) => {
          cache.put(event.request, responseToCache);
        });
        return response;
      }).catch(() => {
        // Fallback for navigation requests
        if (event.request.mode === 'navigate') {
          return caches.match('/');
        }
      });
    })
  );
});

